INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-CTX-01', 'Sal en el agua de riego y germinación del fríjol', 'En algunas zonas secas del Caribe colombiano, ciertos pozos tienen agua con sales disueltas. Un grupo de estudiantes quiso averiguar si la sal del agua de riego afecta la germinación de las semillas de fríjol.
Colocaron 20 semillas de la misma variedad en cada uno de cuatro platos con algodón y regaron cada plato con 10 mL diarios de una solución distinta. Los cuatro platos se mantuvieron a 25 °C y con la misma iluminación. Después de 7 días contaron las semillas germinadas en cada plato:
• Plato 1 · agua sin sal (0 g/L): 18 semillas germinadas.
• Plato 2 · agua con 2 g/L de sal: 15 semillas germinadas.
• Plato 3 · agua con 4 g/L de sal: 9 semillas germinadas.
• Plato 4 · agua con 8 g/L de sal: 2 semillas germinadas.', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
-- CIE-BIO-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-BIO-01-CTX', NULL, 'En una granja de Pasto (Nariño), Rosa cría cuyes. Considere que el color del pelaje de estos cuyes depende de un solo gen: el alelo N (pelaje negro) es dominante y el alelo n (pelaje blanco) es recesivo. Rosa cruzó un macho negro con una hembra blanca y, en varias camadas, obtuvo 12 crías: 6 negras y 6 blancas.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-BIO-01', (SELECT id FROM subtemas WHERE slug = 'biologia'), (SELECT id FROM contextos WHERE codigo = 'CIE-BIO-01-CTX'), 'Si Rosa cruza entre sí dos de las crías negras, ¿qué porcentaje de crías blancas puede esperar en la nueva descendencia?', NULL,
  NULL, 2, 'Uso comprensivo del conocimiento científico', '**Paso 1.** La madre es blanca, así que su genotipo es nn: solo puede transmitir el alelo n.
**Paso 2.** Cada cría negra recibió un alelo n de la madre y, para ser negra, un alelo N del padre. Por tanto, todas las crías negras son heterocigotas (Nn).
**Paso 3.** Al cruzar dos de ellas (Nn × Nn), el cuadro de Punnett da cuatro combinaciones igualmente probables: NN, Nn, nN y nn.
**Paso 4.** Solo nn produce pelaje blanco: 1 de 4 combinaciones, es decir, **25 %**. Las otras tres (75 %) darán crías negras.
Dato extra: que la mitad de las crías del primer cruce saliera blanca indica que el macho original también era Nn.', 120,
  ARRAY['genética mendeliana', 'alelos dominantes y recesivos', 'cuadro de Punnett', 'heterocigoto']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-01'), 'A', '0 %, porque dos cuyes negros solo pueden tener crías negras.', false, 'Es un error común creer que el rasgo recesivo desaparece. Las crías negras son portadoras (Nn): cada una puede transmitir el alelo n y, si ambas lo aportan, la cría será nn, es decir, blanca.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-01'), 'B', '25 %, porque cada cría negra heredó un alelo n de su madre blanca.', true, 'Correcto. La madre (nn) solo aporta alelos n, así que toda cría negra es Nn. El cruce Nn × Nn produce NN, Nn, Nn y nn: 1 de cada 4 crías (25 %) será blanca.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-01'), 'C', '50 %, porque se repetirá la proporción observada en el primer cruce.', false, 'La proporción 1:1 del primer cruce se debió a que uno de los padres era nn (Nn × nn). En el nuevo cruce ambos padres son Nn, y la proporción esperada cambia a 3 negras : 1 blanca.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-01'), 'D', '75 %, porque en el cuadro de Punnett tres de cada cuatro combinaciones tienen el alelo N.', false, 'El 75 % corresponde a las crías con al menos un alelo N (NN y Nn), que son negras. Una cría blanca debe ser nn, y eso ocurre solo en 1 de las 4 combinaciones.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-BIO-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-BIO-02-CTX', NULL, 'Muchos ciclistas colombianos entrenan en Boyacá, por ejemplo en Paipa, a unos 2.500 m de altitud. Estos son algunos datos del aire en Paipa y en Santa Marta, que está al nivel del mar:
• Santa Marta (0 m): oxígeno = 21 % del aire; presión atmosférica = 101 kPa.
• Paipa (2.500 m): oxígeno = 21 % del aire; presión atmosférica = 75 kPa.
Un ciclista samario que llega a entrenar en Paipa se fatiga con facilidad durante los primeros días. Después de cuatro semanas, sus exámenes muestran que su sangre tiene más glóbulos rojos que antes del viaje.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-BIO-02', (SELECT id FROM subtemas WHERE slug = 'biologia'), (SELECT id FROM contextos WHERE codigo = 'CIE-BIO-02-CTX'), '¿Cuál de las siguientes afirmaciones explica mejor el cambio observado en la sangre del ciclista?', NULL,
  NULL, 3, 'Explicación de fenómenos', '**Paso 1.** Compara los datos: el porcentaje de oxígeno es el mismo (21 %), pero la presión en Paipa es menor (75 kPa frente a 101 kPa).
**Paso 2.** A menor presión, el aire está menos comprimido: cada litro contiene menos moléculas de todos los gases, incluido el O₂. Por eso cada inhalación aporta menos oxígeno y el ciclista se fatiga al principio.
**Paso 3.** Los glóbulos rojos contienen hemoglobina, la proteína que transporta el O₂ desde los pulmones hasta los tejidos. No producen oxígeno ni defienden al cuerpo; esa última función es de los glóbulos blancos.
**Paso 4.** La falta de oxígeno estimula a los riñones a liberar la hormona eritropoyetina (EPO), y la médula ósea fabrica más glóbulos rojos. Así la sangre transporta más oxígeno aunque cada inhalación traiga menos.
Esta adaptación es la base del entrenamiento en altura.', 150,
  ARRAY['glóbulos rojos', 'hemoglobina', 'sistema respiratorio', 'presión atmosférica', 'adaptación a la altura']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-02'), 'A', 'En Paipa el aire contiene un menor porcentaje de oxígeno, y los glóbulos rojos adicionales producen el oxígeno que les falta a los músculos.', false, 'Tiene dos errores. Según los datos, el porcentaje de oxígeno es el mismo (21 %) en ambas ciudades; lo que cambia es la presión. Además, los glóbulos rojos no producen oxígeno: lo transportan unido a la hemoglobina.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-02'), 'B', 'En Paipa el porcentaje de oxígeno es igual al de Santa Marta, así que los glóbulos rojos aumentan porque el cuerpo refuerza sus defensas por el esfuerzo.', false, 'Que el porcentaje sea igual no significa que se inhale la misma cantidad de oxígeno: con menor presión, cada litro de aire tiene menos moléculas de O₂. Además, la defensa del organismo es función de los glóbulos blancos, no de los rojos.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-02'), 'C', 'En Paipa el aire es más puro y cada inhalación aporta más oxígeno, por lo que el cuerpo fabrica más glóbulos rojos para aprovecharlo.', false, 'El aire de montaña puede tener menos contaminantes, pero eso no aumenta el oxígeno disponible. Con una presión de 75 kPa, cada inhalación contiene menos moléculas de O₂ que al nivel del mar, no más.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-BIO-02'), 'D', 'En Paipa cada inhalación aporta menos moléculas de oxígeno, y los glóbulos rojos adicionales permiten que la sangre transporte más oxígeno a los músculos.', true, 'Correcto. Con el mismo 21 % de oxígeno pero menor presión, el aire está menos concentrado: cada inhalación lleva menos moléculas de O₂. El cuerpo compensa fabricando más glóbulos rojos, cuya hemoglobina transporta el oxígeno; así cada litro de sangre lleva más O₂ a los músculos.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-MED-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-MED-01-CTX', NULL, 'El páramo de Chingaza abastece buena parte del agua que se consume en Bogotá. En los páramos, los frailejones atrapan la humedad de la niebla con sus hojas cubiertas de vellosidades, y los musgos y los suelos, ricos en materia orgánica, almacenan grandes cantidades de agua. Esa agua se libera lentamente hacia las quebradas durante todo el año, incluso en la temporada seca.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-MED-01', (SELECT id FROM subtemas WHERE slug = 'medio-ambiente'), (SELECT id FROM contextos WHERE codigo = 'CIE-MED-01-CTX'), 'Si en una zona del páramo se retiran los frailejones y los musgos y se ara el suelo para sembrar papa, lo más probable es que las quebradas que nacen allí', NULL,
  NULL, 1, 'Explicación de fenómenos', '**Paso 1.** Identifica la función del páramo en el texto: captura agua de la lluvia y de la niebla, la almacena en suelos y musgos y la libera lentamente.
**Paso 2.** Al retirar frailejones y musgos, se pierde la captura de agua de la niebla. Al arar, el suelo queda expuesto al sol y al viento, se seca y pierde materia orgánica, así que retiene cada vez menos agua.
**Paso 3.** Sin esa ''esponja'', el agua de lluvia escurre rápidamente y no queda reserva para la temporada seca.
**Conclusión:** las quebradas llevarán menos agua justo cuando más se necesita. Por eso los páramos son ecosistemas estratégicos para el abastecimiento de agua en Colombia.', 90,
  ARRAY['páramos', 'regulación hídrica', 'biodiversidad colombiana', 'servicios ecosistémicos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-MED-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-01'), 'A', 'lleven menos agua en la temporada seca, porque el suelo pierde su capacidad de almacenar agua y liberarla poco a poco.', true, 'Correcto. Sin frailejones ni musgos, y con el suelo arado y expuesto, se pierde la ''esponja'' del páramo: el agua de lluvia escurre rápido y en la temporada seca queda muy poca para alimentar las quebradas.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-01'), 'B', 'lleven más agua durante todo el año, porque ya no habrá plantas que absorban el agua de la lluvia.', false, 'Sin vegetación el agua escurre más rápido durante los aguaceros, pero se pierde la capacidad de almacenarla. El resultado no es más agua todo el año, sino crecientes en época de lluvias y quebradas casi secas en la temporada seca.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-01'), 'C', 'mantengan el mismo caudal, porque el agua de las quebradas depende solo de la cantidad de lluvia.', false, 'La lluvia importa, pero el texto muestra que el páramo también captura agua de la niebla y la regula: la guarda en sus suelos y musgos y la libera poco a poco. Si se destruye ese sistema, el caudal cambia aunque llueva lo mismo.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-01'), 'D', 'se congelen con más frecuencia, porque sin vegetación el agua del páramo se transforma en hielo.', false, 'Aquí se confunde el páramo con los glaciares de los nevados. El páramo no almacena el agua como hielo, sino en sus suelos y musgos; retirar la vegetación no convierte el agua en hielo.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-MED-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-MED-02-CTX', NULL, 'Una laguna andina está rodeada de cultivos de cebolla que se abonan con fertilizantes ricos en nitratos y fosfatos. Después de cada temporada de lluvias, el agua de la laguna se vuelve verde por la gran cantidad de algas y, semanas más tarde, los pescadores encuentran muchos peces muertos. Los análisis del agua no detectan sustancias tóxicas para los peces, pero sí una concentración muy baja de oxígeno disuelto.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-MED-02', (SELECT id FROM subtemas WHERE slug = 'medio-ambiente'), (SELECT id FROM contextos WHERE codigo = 'CIE-MED-02-CTX'), '¿Cuál de las siguientes secuencias explica mejor la muerte de los peces?', NULL,
  NULL, 2, 'Explicación de fenómenos', '**Paso 1.** Descarta lo que contradicen los datos: no hay sustancias tóxicas (se descarta el envenenamiento) y hay poco oxígeno (se descarta un exceso de oxígeno).
**Paso 2.** Las lluvias arrastran los fertilizantes de los cultivos hacia la laguna. Los nitratos y fosfatos son nutrientes para las algas, que se multiplican y tiñen el agua de verde.
**Paso 3.** Cuando las algas mueren, las bacterias descomponedoras las degradan y, en ese proceso, consumen gran parte del oxígeno disuelto.
**Paso 4.** Sin oxígeno suficiente, los peces mueren. Este fenómeno se llama **eutrofización** y se previene usando menos fertilizantes y conservando franjas de vegetación en las orillas, que retienen los nutrientes antes de que lleguen al agua.', 120,
  ARRAY['eutrofización', 'contaminación del agua', 'fertilizantes', 'oxígeno disuelto', 'descomponedores']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-MED-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-02'), 'A', 'Lluvias → los fertilizantes llegan a la laguna → los nitratos y fosfatos se acumulan en las branquias → los peces mueren envenenados.', false, 'Los análisis descartan sustancias tóxicas para los peces. Los nitratos y fosfatos actúan como nutrientes para las algas; el daño a los peces es indirecto, por la falta de oxígeno.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-02'), 'B', 'Lluvias → los fertilizantes llegan a la laguna → las algas se multiplican y producen un exceso de oxígeno → el exceso de oxígeno intoxica a los peces.', false, 'Los análisis muestran muy poco oxígeno, no un exceso. Las algas producen oxígeno mientras viven, pero cuando mueren en grandes cantidades su descomposición lo agota.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-02'), 'C', 'Lluvias → los fertilizantes llegan a la laguna → las algas se multiplican → al morir, las bacterias que las descomponen consumen el oxígeno → los peces mueren.', true, 'Correcto. Es el proceso de eutrofización: el exceso de nutrientes dispara el crecimiento de las algas; cuando estas mueren, las bacterias descomponedoras usan el oxígeno disuelto para degradarlas y los peces mueren por asfixia.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MED-02'), 'D', 'Lluvias → el agua de la laguna se enfría → el agua fría retiene menos oxígeno disuelto → los peces mueren por falta de oxígeno.', false, 'Ocurre lo contrario: el agua fría puede disolver más oxígeno que el agua caliente. Además, esta secuencia no explica por qué el agua se vuelve verde ni el papel de los fertilizantes.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-FIS-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-FIS-01-CTX', NULL, 'Un bus del MIO, en Cali, avanza en línea recta con velocidad constante y frena de repente. Los pasajeros que van de pie y no se sostienen de las barandas se inclinan hacia adelante.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-FIS-01', (SELECT id FROM subtemas WHERE slug = 'fisica'), (SELECT id FROM contextos WHERE codigo = 'CIE-FIS-01-CTX'), '¿Cuál de los siguientes principios explica lo que les ocurre a los pasajeros?', NULL,
  NULL, 1, 'Uso comprensivo del conocimiento científico', '**Paso 1.** Antes de frenar, el bus y los pasajeros se mueven juntos, con la misma velocidad.
**Paso 2.** Al frenar, el bus reduce su velocidad. A los pasajeros solo los frena la fricción del piso sobre sus pies; sobre el resto del cuerpo no actúa ninguna fuerza que lo detenga.
**Paso 3.** Por la **primera ley de Newton (inercia)**, todo cuerpo tiende a conservar su velocidad si no actúa una fuerza neta que la cambie. Por eso los pies se frenan con el bus, pero el tronco sigue hacia adelante.
**Conclusión:** ninguna fuerza empuja a los pasajeros hacia adelante; simplemente siguen moviéndose mientras el bus se detiene. Por eso es importante sostenerse de las barandas.', 75,
  ARRAY['leyes de Newton', 'inercia', 'primera ley de Newton', 'fuerza']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-01'), 'A', 'Toda acción tiene una reacción: al frenar, el bus empuja a los pasajeros hacia adelante con una fuerza igual a la del freno.', false, 'Se aplica mal la tercera ley de Newton: las fuerzas de acción y reacción actúan sobre cuerpos distintos, y aquí ninguna fuerza empuja a los pasajeros hacia adelante. Lo que ocurre es que su cuerpo sigue moviéndose mientras el bus se frena.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-01'), 'B', 'Todo cuerpo tiende a conservar su estado de movimiento: los pasajeros siguen moviéndose hacia adelante mientras el bus se detiene.', true, 'Correcto. Es la primera ley de Newton o principio de inercia. Los pasajeros llevaban la misma velocidad del bus; cuando este frena, sus cuerpos tienden a mantener esa velocidad y por eso se van hacia adelante.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-01'), 'C', 'Los cuerpos en movimiento acumulan una fuerza propia que los sigue impulsando hacia adelante hasta que se agota.', false, 'Es una idea muy común, pero incorrecta: un cuerpo no necesita una ''fuerza guardada'' para seguir moviéndose. Mantener la velocidad no requiere fuerza; cambiarla, sí.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-01'), 'D', 'Al frenar, la fuerza de gravedad dentro del bus cambia de dirección y empuja a los pasajeros hacia adelante.', false, 'La gravedad (el peso) siempre apunta hacia el centro de la Tierra, es decir, hacia abajo, y no cambia porque el bus frene. La inclinación hacia adelante se debe a la inercia.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-FIS-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-FIS-02-CTX', NULL, 'Un bus articulado de TransMilenio viaja en línea recta entre dos estaciones. La gráfica muestra cómo cambió su velocidad durante el recorrido.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-FIS-02', (SELECT id FROM subtemas WHERE slug = 'fisica'), (SELECT id FROM contextos WHERE codigo = 'CIE-FIS-02-CTX'), 'Con base en la gráfica, ¿cuál de las siguientes conclusiones es válida?', '/img/preguntas/CIE-FIS-02.svg',
  'Gráfica de velocidad (m/s) contra tiempo (s). La velocidad aumenta en línea recta de 0 a 10 m/s entre 0 y 10 s, se mantiene constante en 10 m/s entre 10 y 40 s y disminuye en línea recta hasta 0 m/s entre 40 y 50 s.', 3, 'Indagación', '**Paso 1.** Lee la gráfica por tramos: de 0 a 10 s la velocidad sube de 0 a 10 m/s; de 10 a 40 s se mantiene en 10 m/s; de 40 a 50 s baja de 10 m/s a 0.
**Paso 2.** En el tramo de 10 a 40 s, Δv = 0, así que la aceleración es a = Δv/Δt = 0 m/s².
**Paso 3.** Por la segunda ley de Newton, F neta = m·a = 0. El bus sí se mueve, pero la fuerza que lo impulsa está equilibrada con la fricción y la resistencia del aire.
**Paso 4.** Descarta las demás: de 0 a 10 s recorre ½ × 10 s × 10 m/s = 50 m (no 100 m); una línea horizontal en v–t no significa reposo; y de 40 a 50 s la velocidad sigue siendo positiva, así que el bus frena sin devolverse.
**Clave:** moverse con velocidad constante no requiere fuerza neta; cambiar la velocidad sí.', 150,
  ARRAY['gráfica velocidad-tiempo', 'MRUA', 'segunda ley de Newton', 'fuerza neta', 'interpretación de gráficas']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-02'), 'A', 'Entre 0 s y 10 s el bus recorre 100 m, porque al final de ese intervalo su velocidad es 10 m/s.', false, 'Multiplicar la velocidad final por el tiempo supone que el bus fue a 10 m/s todo el intervalo, pero partió del reposo. La distancia es el área del triángulo: ½ × 10 s × 10 m/s = 50 m.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-02'), 'B', 'Entre 10 s y 40 s el bus está detenido, porque la línea de la gráfica es horizontal.', false, 'Se confunde una gráfica de velocidad con una de posición. Una línea horizontal en una gráfica velocidad–tiempo indica velocidad constante (aquí, 10 m/s), no reposo. El bus estaría detenido solo si la línea estuviera sobre v = 0.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-02'), 'C', 'Entre 40 s y 50 s el bus se devuelve hacia la estación de partida, porque la línea de la gráfica desciende.', false, 'La velocidad disminuye, pero sigue siendo positiva hasta llegar a cero: el bus avanza cada vez más despacio en el mismo sentido y se detiene. Solo se devolvería si la velocidad tomara valores negativos.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-FIS-02'), 'D', 'Entre 10 s y 40 s la fuerza neta sobre el bus es cero, porque su velocidad no cambia.', true, 'Correcto. Entre 10 s y 40 s la velocidad es constante (10 m/s), así que la aceleración es cero. Por la segunda ley de Newton (F neta = m·a), la fuerza neta también es cero: la fuerza que impulsa al bus se equilibra con la fricción y la resistencia del aire.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-QUI-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-QUI-01-CTX', NULL, 'En el laboratorio del colegio, Valentina calienta al aire un trozo de lana de acero (hierro) de 10,0 g hasta que se oscurece; al pesarlo de nuevo, la balanza marca 10,8 g. Al mismo tiempo, Andrés quema en un plato abierto una hoja de papel de 5,0 g; las cenizas que quedan pesan 0,2 g.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-QUI-01', (SELECT id FROM subtemas WHERE slug = 'quimica'), (SELECT id FROM contextos WHERE codigo = 'CIE-QUI-01-CTX'), '¿Cuál de las siguientes afirmaciones explica correctamente ambos resultados?', NULL,
  NULL, 2, 'Explicación de fenómenos', '**Paso 1.** Recuerda la ley de conservación de la masa: en una reacción química los átomos no se crean ni se destruyen, solo se reorganizan.
**Paso 2.** Hierro: el oxígeno del aire se une al hierro y forma un óxido (por ejemplo, 3 Fe + 2 O₂ → Fe₃O₄). El sólido pesa más porque ahora incluye oxígeno: los 0,8 g adicionales corresponden al oxígeno incorporado.
**Paso 3.** Papel: la celulosa reacciona con el O₂ y produce CO₂ y vapor de agua, gases que escapan del plato abierto. Solo quedan 0,2 g de cenizas, formadas por minerales que no arden.
**Paso 4.** La balanza no registra los gases que entran o salen. Si cada experimento se hiciera en un recipiente cerrado, la masa total antes y después de la reacción sería la misma.
**Clave:** cuando una masa parece aparecer o desaparecer, busca un gas que entró o salió del sistema.', 120,
  ARRAY['conservación de la masa', 'reacciones químicas', 'combustión', 'oxidación', 'sistemas abiertos y cerrados']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-01'), 'A', 'El hierro se combina con el oxígeno del aire y forma un óxido de mayor masa; el papel produce dióxido de carbono y vapor de agua, que escapan al aire. En ambos casos, la masa total se conserva.', true, 'Correcto. La balanza solo registra lo que queda en el plato. El hierro gana la masa del oxígeno que incorpora y el papel pierde la masa de los gases que se van. Si ambas reacciones ocurrieran en recipientes cerrados, la masa total no cambiaría.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-01'), 'B', 'La combustión del papel destruye parte de la materia y la oxidación del hierro crea materia nueva, porque la ley de conservación de la masa no se cumple cuando hay fuego.', false, 'La ley de conservación de la masa se cumple en todas las reacciones químicas, con o sin fuego. La materia no se crea ni se destruye: los átomos se reorganizan y, en este caso, algunos entran desde el aire o salen hacia él.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-01'), 'C', 'El hierro absorbe el calor de la llama y ese calor aumenta su masa; el papel, en cambio, libera su calor al aire y por eso su masa disminuye.', false, 'El calor es energía que se transfiere, no una sustancia con masa que se pueda medir en una balanza. El cambio de masa se debe a los átomos de oxígeno que se unen al hierro y a los gases que escapan del papel.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-01'), 'D', 'El hierro se dilata al calentarse y por eso pesa más; el papel se transforma completamente en energía y por eso la mayor parte de su masa desaparece.', false, 'Dilatarse aumenta el volumen, no la masa. Y el papel no se convierte en energía: sus átomos de carbono e hidrógeno forman CO₂ y H₂O, gases que se dispersan en el aire.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-QUI-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-QUI-02-CTX', NULL, 'La gráfica muestra la solubilidad del nitrato de potasio (KNO₃), una sal usada como fertilizante, a diferentes temperaturas. En el laboratorio se disuelve la máxima cantidad posible de KNO₃ en 50 g de agua a 60 °C; luego la solución se enfría hasta 20 °C y se deja en reposo hasta que dejan de formarse cristales.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-QUI-02', (SELECT id FROM subtemas WHERE slug = 'quimica'), (SELECT id FROM contextos WHERE codigo = 'CIE-QUI-02-CTX'), '¿Qué masa de KNO₃ se separa de la solución en forma de cristales?', '/img/preguntas/CIE-QUI-02.svg',
  'Curva de solubilidad del KNO₃: gramos de sal que se disuelven en 100 g de agua según la temperatura. La curva crece cada vez más rápido: 13 g a 0 °C, 21 g a 10 °C, 32 g a 20 °C, 46 g a 30 °C, 64 g a 40 °C, 86 g a 50 °C y 110 g a 60 °C. Los puntos de 20 °C (32 g) y 60 °C (110 g) están resaltados.', 3, 'Uso comprensivo del conocimiento científico', '**Paso 1.** Lee la gráfica: la solubilidad del KNO₃ es de 110 g por cada 100 g de agua a 60 °C y de 32 g por cada 100 g de agua a 20 °C.
**Paso 2.** Ajusta a 50 g de agua, que es la mitad: a 60 °C se disuelven 110 ÷ 2 = 55 g y a 20 °C solo caben 32 ÷ 2 = 16 g.
**Paso 3.** Al enfriar, el agua ya no puede mantener disuelto todo el soluto y el exceso se cristaliza: 55 g − 16 g = **39 g**.
**Paso 4.** Comprueba: 39 g de cristales + 16 g disueltos = 55 g, la misma masa de soluto del comienzo.
Este proceso, llamado cristalización por enfriamiento, se usa para purificar sales cuya solubilidad cambia mucho con la temperatura.', 180,
  ARRAY['solubilidad', 'curva de solubilidad', 'cristalización', 'soluciones saturadas', 'temperatura']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-02'), 'A', '16 g', false, '16 g es la masa que sigue disuelta a 20 °C (32 g × 50/100), no la que se cristaliza. Los cristales son la diferencia entre lo que estaba disuelto y lo que el agua todavía puede retener.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-02'), 'B', '39 g', true, 'Correcto. A 60 °C, 50 g de agua disuelven 110 g ÷ 2 = 55 g de KNO₃; a 20 °C solo pueden retener 32 g ÷ 2 = 16 g. El exceso, 55 g − 16 g = 39 g, se separa como cristales.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-02'), 'C', '55 g', false, '55 g es todo lo que se disolvió a 60 °C. Al enfriar no se cristaliza todo el soluto: a 20 °C el agua todavía mantiene disueltos 16 g.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-QUI-02'), 'D', '78 g', false, '78 g (110 g − 32 g) sería la respuesta si hubiera 100 g de agua. Como solo hay 50 g, todas las cantidades se reducen a la mitad.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-MET-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-MET-01', (SELECT id FROM subtemas WHERE slug = 'metodo-cientifico'), (SELECT id FROM contextos WHERE codigo = 'CIE-CTX-01'), '¿Cuál es la variable independiente en este experimento?', NULL,
  NULL, 1, 'Indagación', '**Paso 1.** Busca qué cambia a propósito entre los platos: solo la concentración de sal (0, 2, 4 y 8 g/L). Esa es la **variable independiente**.
**Paso 2.** Busca qué se mide como resultado: el número de semillas germinadas. Esa es la **variable dependiente**.
**Paso 3.** Todo lo que se mantiene igual (temperatura, luz, variedad de fríjol, número de semillas, volumen de riego y tiempo) son **variables controladas**.
Truco: la independiente es la causa que el investigador manipula; la dependiente es el efecto que mide.', 60,
  ARRAY['variables', 'variable independiente', 'diseño experimental']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-MET-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-01'), 'A', 'La concentración de sal en el agua de riego.', true, 'Correcto. La concentración de sal es lo que los estudiantes cambiaron a propósito entre un plato y otro (0, 2, 4 y 8 g/L) para ver su efecto.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-01'), 'B', 'El número de semillas germinadas en cada plato.', false, 'Esa es la variable dependiente: lo que se mide para ver cómo responde la germinación al cambio en la concentración de sal.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-01'), 'C', 'La temperatura de 25 °C a la que estaban los platos.', false, 'La temperatura fue la misma en los cuatro platos: es una variable controlada, que se mantiene fija para que no influya en los resultados.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-01'), 'D', 'La variedad de fríjol que se utilizó.', false, 'Todos los platos tenían semillas de la misma variedad, así que es una variable controlada, no la independiente.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-MET-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-MET-02', (SELECT id FROM subtemas WHERE slug = 'metodo-cientifico'), (SELECT id FROM contextos WHERE codigo = 'CIE-CTX-01'), '¿Cuál de las siguientes conclusiones es válida a partir de los resultados del experimento?', NULL,
  NULL, 2, 'Indagación', '**Paso 1.** Organiza los datos: 0 g/L → 18; 2 g/L → 15; 4 g/L → 9; 8 g/L → 2 semillas germinadas de 20.
**Paso 2.** Identifica la tendencia: cada vez que aumenta la concentración de sal, germinan menos semillas.
**Paso 3.** Verifica que la conclusión hable solo de lo que se midió (germinación, no altura), de lo que se probó (fríjol, no todas las semillas) y que compare con el grupo control (agua sin sal).
**Paso 4.** La conclusión válida es que, en las condiciones del experimento, a mayor concentración de sal germinaron menos semillas de fríjol. Una buena conclusión no exagera ni va más allá de los datos.', 105,
  ARRAY['conclusiones válidas', 'interpretación de datos', 'grupo control', 'generalización']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-MET-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-02'), 'A', 'La sal impide por completo la germinación de cualquier tipo de semilla, sin importar su concentración.', false, 'Es una generalización excesiva: incluso con 8 g/L germinaron 2 semillas, y solo se probó el fríjol. El resultado no puede extenderse a todas las semillas ni a todas las concentraciones.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-02'), 'B', 'Las plantas de fríjol regadas con agua sin sal crecieron más altas que las regadas con agua salada.', false, 'Los estudiantes contaron semillas germinadas; no midieron la altura de las plantas. Una conclusión válida solo puede referirse a lo que se midió.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-02'), 'C', 'En las condiciones del experimento, a mayor concentración de sal en el agua de riego, menos semillas de fríjol germinaron.', true, 'Correcto. Los datos muestran una tendencia clara: 18, 15, 9 y 2 semillas germinadas con 0, 2, 4 y 8 g/L de sal. La conclusión se limita a lo medido y a las condiciones del experimento.'),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-MET-02'), 'D', 'Una concentración baja de sal (2 g/L) favorece la germinación del fríjol, porque en ese plato germinaron 15 semillas.', false, 'Hay que comparar con el grupo control: sin sal germinaron 18 semillas y con 2 g/L germinaron 15. La sal no favoreció la germinación; la redujo.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;

-- ---------------------------------------------------------------- ingles.json
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('ING-CTX-01', 'Flowers on my back', 'My name is Sara, and I live in Santa Elena, a small village in the mountains near Medellín. My family grows flowers, and for us, August is the most important month of the year because of the Flower Festival.

The most famous event of the festival is the silleteros parade. Silleteros are farmers who carry big flower arrangements, called silletas, on their backs. My grandfather Julio has walked in the parade for more than forty years. When I was twelve, he taught me how to choose the flowers, how to organize them by color and how to tie them to the wooden frame without breaking them.

Last year, I carried my own silleta in the parade for the first time. It wasn''t very big, but it was heavy, and after two kilometers my back hurt a lot. I wanted to stop, but then I heard people clapping and shouting my name. At that moment, I forgot about the pain.

Some of my friends think the parade is just a show for tourists. For me, it is much more than that. Every flower tells a story about my family, and one day I want to teach my own children how to make a silleta.', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('ING-CTX-02', 'Sundays on wheels', 'Every Sunday and public holiday, from 7 a.m. to 2 p.m., many of Bogotá''s main roads are closed to cars and open to people. This is the Ciclovía, one of the city''s most popular traditions. People of all ages (1) ______ part in it every week: children learning to ride a bike, teenagers on skates, runners and even grandparents walking their dogs. Along the way, there are small stands where you can buy a cold fruit juice or get a flat tire fixed.

(2) ______ the Ciclovía started as a small event on just a few streets in the 1970s, today it covers more than one hundred kilometers, and cities all over the world have copied the idea.', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
-- ING-REA-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-REA-01', (SELECT id FROM subtemas WHERE slug = 'reading'), (SELECT id FROM contextos WHERE codigo = 'ING-CTX-01'), 'According to the text, what did Sara learn from her grandfather?', NULL,
  NULL, 2, 'Parte 5 · Comprensión literal', 'En la **Parte 5 (comprensión literal)** la respuesta está en el texto, aunque expresada con otras palabras. Haz scanning con la palabra clave de la pregunta, **grandfather**: aparece en el segundo párrafo, donde Sara dice que él le enseñó (taught, pasado de teach) a escoger las flores, organizarlas por color y amarrarlas al marco de madera. Esos tres pasos equivalen a **hacer una silleta**, y la última oración del texto lo confirma con la frase how to make a silleta. Las opciones incorrectas copian palabras reales del texto (grow flowers, organize, two kilometers), pero las combinan en ideas que el texto no dice. **Consejo:** desconfía de las opciones que repiten palabras exactas; la correcta suele ser una paráfrasis.', 150,
  ARRAY['A2', 'comprensión literal', 'scanning', 'paráfrasis', 'cultura colombiana']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-REA-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-01'), 'A', 'How to grow flowers in the mountains.', false, 'El texto dice que la familia de Sara cultiva flores (My family grows flowers), pero en ningún momento dice que el abuelo le enseñara a cultivarlas. La opción combina palabras del texto (flowers, mountains) para formar una idea que no aparece.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-01'), 'B', 'How to make a silleta.', true, '¡Correcto! En el segundo párrafo, Sara cuenta que su abuelo le enseñó a escoger las flores, organizarlas por color y amarrarlas al marco de madera: justamente los pasos para hacer una silleta. El último párrafo lo confirma: ella quiere enseñarles a sus hijos how to make a silleta.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-01'), 'C', 'How to organize the Flower Festival.', false, 'El verbo organize sí aparece, pero se refiere a organizar las flores por color (organize them by color), no a organizar la Feria de las Flores. Es el error de reconocer una palabra suelta sin leer la oración completa.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-01'), 'D', 'How to walk two kilometers without pain.', false, 'Los dos kilómetros y el dolor aparecen en el tercer párrafo, cuando Sara desfiló por primera vez, y allí dice que sí le dolió la espalda. Nadie le enseñó a caminar sin dolor.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-REA-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-REA-02', (SELECT id FROM subtemas WHERE slug = 'reading'), (SELECT id FROM contextos WHERE codigo = 'ING-CTX-01'), 'Which statement best describes Sara''s attitude toward the silleteros parade?', NULL,
  NULL, 3, 'Parte 6 · Comprensión inferencial', 'En la **Parte 6 (comprensión inferencial)** la respuesta no está escrita de forma literal: debes deducirla uniendo varias pistas. Para identificar la **actitud** de Sara, observa el último párrafo. Primero presenta la opinión de sus amigos (just a show for tourists) y luego la contrasta con la suya (For me, it is much more than that). Después dice que cada flor cuenta una historia sobre su familia y que quiere enseñarles a sus hijos a hacer silletas. Todas esas pistas indican que valora el desfile como una **tradición familiar** que quiere continuar. **Ojo:** la opción A es una trampa típica, porque presenta como opinión de la narradora lo que en realidad piensan otras personas.', 120,
  ARRAY['B1', 'comprensión inferencial', 'actitud del autor', 'cultura colombiana']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-REA-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-02'), 'A', 'She enjoys it, but she agrees that it is mainly a show for tourists.', false, 'Quienes piensan que el desfile es just a show for tourists son algunos amigos de Sara, no ella. Justo después, ella dice lo contrario: For me, it is much more than that. Esta opción le atribuye a Sara la opinión de otras personas.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-02'), 'B', 'She thinks carrying a silleta is too hard, so she plans to stop.', false, 'Es verdad que le dolió la espalda, pero Sara cuenta que olvidó el dolor al escuchar al público y que quiere enseñarles la tradición a sus hijos. Nada indica que piense dejar de participar.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-02'), 'C', 'She sees it as a family tradition that she wants to continue.', true, '¡Correcto! Frases como Every flower tells a story about my family y one day I want to teach my own children how to make a silleta muestran que para ella el desfile es una herencia familiar que quiere mantener viva.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-REA-02'), 'D', 'She only takes part because her grandfather asks her to.', false, 'El abuelo le enseñó a hacer silletas, pero el texto no dice que la obligue a desfilar. Al contrario, Sara habla con orgullo y quiere transmitir la tradición por decisión propia.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-GRA-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('ING-GRA-01-CTX', NULL, 'Hi, Mateo!
I''m in Cartagena with my family. The old city is beautiful, but the weather here is much ______ than in Bogotá. Yesterday it was 33 °C!
See you on Monday,
Juliana', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-GRA-01', (SELECT id FROM subtemas WHERE slug = 'grammar'), (SELECT id FROM contextos WHERE codigo = 'ING-GRA-01-CTX'), 'Read Juliana''s message. Which word correctly completes the gap?', NULL,
  NULL, 1, 'Parte 4 · Gramática en contexto', 'La clave está en las palabras que rodean el hueco: **much** antes y **than** después. La estructura **much + comparativo + than** significa «mucho más… que». Como hot es un adjetivo corto (una sílaba), su comparativo se forma con **-er**, y como termina en consonante-vocal-consonante, duplica la última letra: hot → hotter (igual que big → bigger). Con adjetivos largos sí se usa more: The old city is more beautiful than I expected. Evita «more hot» o «more big»: son errores típicos de hispanohablantes.', 60,
  ARRAY['A2', 'comparativos', 'adjetivos', 'much + comparativo']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-GRA-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-01'), 'A', 'hotter', true, '¡Correcto! Hot es un adjetivo corto (una sílaba) que termina en consonante-vocal-consonante, así que duplica la t y añade -er: hot → hotter. Con much delante, la idea es «mucho más caliente que».'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-01'), 'B', 'more hot', false, 'Es una traducción literal de «más caliente». En inglés, los adjetivos de una sílaba forman el comparativo con -er, no con more: hot → hotter, cold → colder.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-01'), 'C', 'hottest', false, 'Hottest es el superlativo («el más caliente»). Se usa con the para destacar algo dentro de un grupo (the hottest city in Colombia), no para comparar dos cosas con than.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-01'), 'D', 'hot', false, 'Hot es la forma base del adjetivo. La palabra than después del hueco indica una comparación, así que se necesita la forma comparativa.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-GRA-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('ING-GRA-02-CTX', NULL, 'My name is Valentina. I was born in Pasto, but my family moved to Cali when I was ten. We ______ in Cali since 2020, and now I can''t imagine living anywhere else.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-GRA-02', (SELECT id FROM subtemas WHERE slug = 'grammar'), (SELECT id FROM contextos WHERE codigo = 'ING-GRA-02-CTX'), 'Read what Valentina says about herself. Which option correctly completes the gap?', NULL,
  NULL, 2, 'Parte 4 · Gramática en contexto', 'Fíjate en las pistas de tiempo. En la primera oración, **was born** y **moved** están en pasado simple porque son hechos terminados (when I was ten). En el hueco aparece **since 2020**, que indica desde cuándo ocurre algo que todavía es verdad: Valentina sigue viviendo en Cali (now I can''t imagine living anywhere else). Esa combinación exige el **present perfect**: Subject + have/has + past participle → We have lived. En español usamos el presente («vivimos… desde»), por eso muchos estudiantes eligen live. Expresiones como since, for, already, yet, ever y never suelen acompañar al present perfect.', 75,
  ARRAY['B1', 'present perfect', 'since', 'tiempos verbales']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-GRA-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-02'), 'A', 'live', false, 'Es el error más común de los hispanohablantes: en español decimos «vivimos en Cali desde 2020» (presente), pero en inglés, cuando una situación empezó en el pasado y continúa hoy, no se usa el presente simple con since.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-02'), 'B', 'lived', false, 'Lived (pasado simple) sirve para situaciones terminadas en un momento concreto del pasado (We lived in Pasto until 2020). Aquí Valentina todavía vive en Cali, y since indica que la situación continúa.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-02'), 'C', 'are living', false, 'El presente continuo describe algo que ocurre ahora o que es temporal, pero no se combina con since para expresar duración desde un punto del pasado hasta hoy.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-GRA-02'), 'D', 'have lived', true, '¡Correcto! Since 2020 marca el punto de inicio de una situación que sigue siendo verdad. Por eso se usa el present perfect: have + participio pasado (have lived).')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-VOC-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-VOC-01', (SELECT id FROM subtemas WHERE slug = 'vocabulary'), NULL, 'Where can you see this notice?', '/img/preguntas/ING-VOC-01.svg',
  'Aviso con el título NOTICE que dice: «You can borrow up to 3 books for 15 days. Please show your student card.»', 1, 'Parte 1 · Avisos', 'En la **Parte 1** debes identificar dónde aparecería un aviso. Busca las palabras clave: **borrow** (pedir prestado), **books** (libros), **for 15 days** (por 15 días) y **student card** (carné estudiantil). Solo en una biblioteca escolar te prestan libros por un tiempo limitado y te piden el carné. Cuidado con el falso amigo: **library = biblioteca**, mientras que **bookstore / bookshop = librería**. Recuerda también la diferencia entre **borrow** (recibir algo prestado: I borrow a book) y **lend** (prestarle algo a otra persona: The library lends books to students).', 60,
  ARRAY['A1', 'avisos', 'lugares', 'borrow vs lend', 'falsos amigos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-VOC-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-01'), 'A', 'At a bank.', false, 'Quizá te guiaste por borrow (pedir prestado), que también se usa con dinero (borrow money), y por card. Pero en un banco no te prestan libros durante 15 días.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-01'), 'B', 'In a bookstore.', false, 'En una librería (bookstore) los libros se compran, no se piden prestados. Ojo con el falso amigo: library no significa «librería», sino «biblioteca».'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-01'), 'C', 'In a school library.', true, '¡Correcto! Borrow significa «pedir prestado». El lugar donde puedes llevarte hasta 3 libros durante 15 días mostrando tu carné estudiantil es la biblioteca del colegio.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-01'), 'D', 'At a bus station.', false, 'Student card puede recordarte la tarjeta del transporte, pero en una estación de bus no se prestan libros. Lee el aviso completo, no solo la última línea.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-VOC-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-VOC-02', (SELECT id FROM subtemas WHERE slug = 'vocabulary'), NULL, 'Which word matches this description?

“Any member of your family, for example an aunt, an uncle or a cousin.”', NULL,
  NULL, 1, 'Parte 2 · Léxico', 'En la **Parte 2** relacionas una descripción con la palabra que le corresponde. Esta descripción habla de **cualquier miembro de la familia** (any member of your family) y da ejemplos: una tía, un tío, un primo. La palabra que significa «pariente» es **relative**. La trampa principal es **parent**, un falso amigo: se parece a «pariente», pero significa «papá o mamá». Otra trampa es relationship, que comparte la raíz relat- pero significa «relación». **Consejo:** cuando una opción se parezca mucho a una palabra en español, comprueba su significado real antes de elegirla.', 60,
  ARRAY['A2', 'léxico', 'familia', 'falsos amigos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-VOC-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-02'), 'A', 'relationship', false, 'Relationship significa «relación» (por ejemplo, una amistad o un noviazgo). Es un sustantivo abstracto, no una persona; se parece a relative, pero no significa lo mismo.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-02'), 'B', 'parent', false, 'Falso amigo clásico: parent no significa «pariente», sino «papá o mamá» (parents = padres). Una tía o un primo no son parents.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-02'), 'C', 'neighbor', false, 'Neighbor significa «vecino»: una persona que vive cerca de ti, no necesariamente alguien de tu familia.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-VOC-02'), 'D', 'relative', true, '¡Correcto! Relative significa «pariente» o «familiar»: cualquier miembro de tu familia, como una tía, un tío o un primo. Ejemplo: All my relatives come to my house on Christmas Eve.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-CON-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('ING-CON-01-CTX', NULL, 'Clerk: Good afternoon. How can I help you?
Customer: Hi. I bought these headphones here yesterday, but the left side doesn''t work.
Clerk: ______
Customer: Yes, here it is. I paid in cash.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-CON-01', (SELECT id FROM subtemas WHERE slug = 'context-understanding'), (SELECT id FROM contextos WHERE codigo = 'ING-CON-01-CTX'), 'Complete the conversation. What does the clerk say?', NULL,
  NULL, 2, 'Parte 3 · Conversación', 'En la **Parte 3** no basta con leer lo que va antes del hueco: **la línea que viene después es la pista más fuerte**. El cliente responde Yes, here it is («sí, aquí está»), así que el empleado hizo una pregunta de sí o no pidiéndole un objeto. Como el cliente viene a reclamar por unos audífonos dañados, lo natural es que le pidan el **receipt** (recibo o factura) para comprobar la compra. Las preguntas con what o how much no se contestan con yes, y la opción D contradice lo que el cliente ya dijo. Vocabulario útil: receipt = recibo, refund = reembolso, pay in cash = pagar en efectivo.', 90,
  ARRAY['A2', 'conversación', 'funciones comunicativas', 'compras']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-CON-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-01'), 'A', 'Do you have the receipt?', true, '¡Correcto! La respuesta del cliente (Yes, here it is. I paid in cash) muestra que le hicieron una pregunta de sí o no para pedirle un objeto. En un reclamo por un producto dañado, lo lógico es pedir el recibo (receipt), que además muestra cómo se pagó.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-01'), 'B', 'What color would you like?', false, 'Una pregunta con what no se responde con Yes. Además, el problema del cliente es que los audífonos no funcionan, no su color.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-01'), 'C', 'How much did you pay for them?', false, 'Te pudo atraer la palabra paid de la última línea, pero una pregunta con how much se responde con un precio, no con Yes, here it is.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-01'), 'D', 'Are you going to buy them today?', false, 'El cliente ya los compró ayer (I bought these headphones here yesterday), así que la pregunta no tiene sentido, y here it is tampoco la respondería.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-CON-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('ING-CON-02-CTX', NULL, '★★★☆☆ Coffee farm tour in Salento
Review by Daniela R.

The farm was beautiful, and our guide, Don Álvaro, knew everything about coffee. We picked coffee cherries, learned how the beans are dried and, of course, tasted a delicious cup at the end. However, the website said the tour lasted two hours, and it took almost four. Because of that, we missed the last bus back to Armenia and had to pay for an expensive taxi. My advice: go, but don''t plan anything else for that afternoon!', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-CON-02', (SELECT id FROM subtemas WHERE slug = 'context-understanding'), (SELECT id FROM contextos WHERE codigo = 'ING-CON-02-CTX'), 'What is the main purpose of Daniela''s review?', NULL,
  NULL, 3, 'Parte 6 · Comprensión inferencial', 'Preguntar por el **propósito (purpose)** de un texto es típico de la **Parte 6**: debes deducir para qué lo escribió el autor, no solo qué dice. Observa la estructura de la reseña: primero, aspectos positivos (the farm was beautiful, the guide knew everything about coffee, a delicious cup); luego, un problema introducido por **However** (el tour duró casi el doble de lo anunciado); y al final, un consejo para futuros visitantes (**My advice: go, but…**). Las tres estrellas confirman una opinión mixta. Por eso, el propósito es recomendar la experiencia y, al mismo tiempo, advertir sobre su duración real. Conectores como however y but suelen marcar el giro clave en este tipo de textos.', 150,
  ARRAY['B1', 'comprensión inferencial', 'propósito del autor', 'reseñas', 'conectores']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-CON-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-02'), 'A', 'To complain to the bus company about its schedule.', false, 'Daniela menciona que perdió el último bus, pero la causa fue la duración del tour, no la empresa de buses. Además, la reseña está dirigida a otros visitantes, no a esa empresa.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-02'), 'B', 'To recommend the tour and warn others about how long it really takes.', true, '¡Correcto! Primero elogia la finca, al guía y el café (recomendación) y cierra con My advice: go, but don''t plan anything else for that afternoon: invita a ir, pero advierte que el tour dura mucho más de lo anunciado.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-02'), 'C', 'To ask the farm to give her money back.', false, 'Pedir un reembolso sería propio de un reclamo formal, pero Daniela no lo pide en ninguna parte. Su reseña mezcla elogios y una advertencia; no busca recuperar dinero.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-CON-02'), 'D', 'To thank the guide for driving her back to Armenia.', false, 'El texto dice que tuvieron que pagar un taxi costoso para volver a Armenia; el guía no los llevó. La opción mezcla dos datos reales del texto (el guía y Armenia) en una idea falsa.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-LAN-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-LAN-01', (SELECT id FROM subtemas WHERE slug = 'language-use'), (SELECT id FROM contextos WHERE codigo = 'ING-CTX-02'), 'Which word best completes gap (1) in the text?', NULL,
  NULL, 2, 'Parte 7 · Texto incompleto', 'En la **Parte 7** muchos huecos evalúan **colocaciones**: combinaciones fijas de palabras que se aprenden como un bloque. Aquí la pista son las palabras que siguen al hueco: **part in it**. La expresión correcta es **take part in** (participar en). En Colombia decimos «hacer parte de», por eso make es la trampa más frecuente; pero en inglés «ser parte de» se dice **be part of** y «participar» se dice **take part in**. Otras colocaciones con take: take a photo, take a bus, take a break.', 120,
  ARRAY['B1', 'colocaciones', 'take part in', 'texto incompleto']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-LAN-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-01'), 'A', 'make', false, 'Es un calco del español colombiano «hacer parte de». En inglés, «participar» se dice take part in y «ser parte de» se dice be part of; make part no existe como expresión.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-01'), 'B', 'do', false, 'Do se usa con actividades y tareas (do homework, do exercise), pero no forma ninguna expresión con part in.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-01'), 'C', 'take', true, '¡Correcto! Take part in something significa «participar en algo». Es una colocación fija: People of all ages take part in it every week.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-01'), 'D', 'give', false, 'Give significa «dar» y no forma con part in ninguna expresión que signifique participar.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- ING-LAN-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('ING-LAN-02', (SELECT id FROM subtemas WHERE slug = 'language-use'), (SELECT id FROM contextos WHERE codigo = 'ING-CTX-02'), 'Which word best completes gap (2) in the text?', NULL,
  NULL, 3, 'Parte 7 · Texto incompleto', 'El hueco está al inicio de una oración que une dos ideas opuestas: la Ciclovía **empezó pequeña** (a small event on just a few streets) y **hoy es enorme** (more than one hundred kilometers… cities all over the world). Se necesita un conector de **contraste** seguido de sujeto + verbo: **Although**. Despite también expresa contraste, pero exige un sustantivo o un verbo con -ing (Despite its small start…); even necesita though para funcionar como «aunque» (even though); y because expresa causa. Recuerda: **Although + sujeto + verbo** / **Despite + sustantivo o verbo-ing**.', 90,
  ARRAY['B+', 'conectores', 'although vs despite', 'texto incompleto']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'ING-LAN-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-02'), 'A', 'Although', true, '¡Correcto! Although («aunque») va seguido de una oración completa (sujeto + verbo: the Ciclovía started…) y expresa contraste: empezó siendo pequeña, pero hoy es enorme.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-02'), 'B', 'Despite', false, 'Despite también expresa contraste, pero va seguido de un sustantivo o de un verbo con -ing (Despite starting as a small event…), nunca de sujeto + verbo conjugado.'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-02'), 'C', 'Even', false, 'Even solo no funciona como «aunque»: se necesita even though (Even though the Ciclovía started…). Omitir though es un error típico al traducir «aun cuando».'),
  ((SELECT id FROM preguntas WHERE codigo = 'ING-LAN-02'), 'D', 'Because', false, 'Because expresa causa, no contraste. Haber empezado en pocas calles no es la razón de que hoy mida más de cien kilómetros: las dos ideas se oponen.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;

-- ---------------------------------------------------------------- lectura-critica.json
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('LEC-CTX-01', 'El taller del abuelo Efraín', 'Mi abuelo Efraín arregló radios durante cuarenta años en un local junto a la plaza de Guateque. Cuando los celulares se tomaron el pueblo, los clientes dejaron de llegar y el letrero de «Electrónica Efraín» se fue quedando sin letras, como un diente de leche que nadie se atreve a arrancar.

El año pasado mi mamá decidió que el abuelo se viniera a vivir con nosotros. Él aceptó con una sola condición: traer su mesa de trabajo. La instaló junto a la ventana de la sala, con los destornilladores ordenados de mayor a menor y una lupa enorme que parecía un ojo de pescado.

Durante semanas nadie le llevó nada. El abuelo limpiaba las herramientas por la mañana y las volvía a limpiar por la tarde. Hablaba poco; comía menos.

Un martes, doña Leonor, la vecina del segundo piso, tocó el timbre con un radio de pilas envuelto en una toalla de flores. Dijo que se le había dañado y que solo confiaba en él. El jueves llegó don Anselmo, el de la tienda, con otro. Después, la profesora de mi hermano. En un mes, la mesa estaba llena de aparatos que olían a polvo y a casa ajena.

Yo no entendía de dónde salían tantos radios dañados en pleno siglo veintiuno. Una tarde vi a mi mamá en la escalera entregándole a doña Leonor el radio de nuestra cocina, envuelto en la misma toalla de flores. Pensé que se lo estaba prestando mientras el abuelo le arreglaba el suyo.

Esa noche el abuelo silbaba mientras soldaba un cable. Le pregunté si no estaba cansado de tanto trabajo.

—Cansado no, mija —me dijo sin levantar la vista—. Cansado estaba antes.', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('LEC-CTX-02', 'El recreo también se aprende', 'Hace dos años, en mi colegio de Bucaramanga, el recreo era un concierto de silencio: trescientos estudiantes sentados en las gradas, cada uno inclinado sobre su celular. Nadie jugaba microfútbol; nadie discutía por la última pregunta del examen. Este año, las directivas decidieron que los teléfonos se guardan en un casillero desde la entrada hasta la salida, y yo, que al principio protesté, hoy defiendo esa medida.

La primera razón es la atención. Cada notificación interrumpe una explicación, y recuperar el hilo de una clase cuesta más de lo que creemos. La segunda es la convivencia: sin pantallas, el patio volvió a llenarse de balones, de partidas de parqués y de conversaciones que antes ocurrían por chat aunque estuviéramos a dos metros. La tercera es el ciberacoso: muchos de los videos con los que se humillaba a algunos compañeros se grababan dentro del colegio, en los baños o en los salones.

Ahora bien, sé que el celular también sirve para consultar, traducir o practicar en plataformas educativas. Nadie propone desterrarlo para siempre de la escuela: para esas actividades, el profesor puede autorizar su uso durante un tiempo definido. Lo que sobra no es la herramienta, sino su presencia permanente.

Algunos compañeros dicen que la norma es inútil porque «de todas formas usamos el celular en la casa». Es cierto, pero ese argumento mezcla dos asuntos: el colegio no puede controlar lo que hacemos por la noche, aunque sí puede ofrecernos siete horas diarias para aprender a estar sin pantalla. Así como aprendemos a leer y a sumar, también necesitamos aprender a aburrirnos, a conversar y a esperar.', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('LEC-CTX-03', '¿Se puede votar la verdad?', 'En una asamblea de curso se puede votar a qué lugar irá la excursión, de qué color será la chaqueta de la promoción o quién será el representante estudiantil. En esos casos decide la mayoría, y es justo que así sea, porque se trata de preferencias: nadie está equivocado por preferir el mar a la montaña. Pero ¿se puede votar si la Tierra gira alrededor del Sol o si un acusado cometió realmente un delito?

Hay quienes responden que sí. Sostienen que, si casi todos en una comunidad creen algo, eso es verdadero para esa comunidad. Durante siglos, sin embargo, la mayoría creyó que la Tierra permanecía quieta en el centro del universo, y la Tierra no dejó de moverse por eso. Lo que cambió con el tiempo no fue el planeta, sino las razones que tenían las personas para creer una cosa u otra.

Esto no significa que la opinión de la mayoría carezca de valor. En la vida pública, votar es la mejor manera que conocemos de tomar decisiones sobre lo que queremos hacer juntos. El problema aparece cuando confundimos dos preguntas distintas: «¿qué debemos hacer?», que admite acuerdos y votaciones, y «¿cómo son las cosas?», que solo se responde examinando pruebas.

Quizá por eso la verdad resulta incómoda para las democracias y, al mismo tiempo, indispensable para ellas. Una comunidad puede decidir libremente construir un puente; lo que no puede decidir por votación es que el puente resista sin cálculos.', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('LEC-CTX-04', 'Las esponjas de la montaña', 'En las cordilleras colombianas, generalmente por encima de los 3.000 metros de altura, se extiende un ecosistema frío, nublado y aparentemente pobre: el páramo. Colombia alberga cerca de la mitad de los páramos del planeta, y de ellos depende buena parte del agua que llega a los hogares de ciudades como Bogotá y Bucaramanga.

El secreto del páramo no está en que llueva mucho, sino en la forma en que guarda el agua. Sus suelos, oscuros y llenos de materia orgánica que el frío descompone muy lentamente, funcionan como una esponja: absorben la lluvia y la liberan poco a poco, durante semanas. Los musgos, capaces de retener varias veces su propio peso en agua, cumplen una función parecida.

Los frailejones aportan un recurso adicional. Sus hojas están cubiertas de pelos finos que, además de protegerlas del frío, ayudan a atrapar las gotas diminutas de la niebla; esa agua escurre por la planta hasta el suelo. Así, el páramo capta humedad incluso en días sin lluvia.

Gracias a esa liberación lenta, los ríos que nacen en el páramo mantienen un caudal relativamente estable durante todo el año, incluso en temporada seca. Por eso, cuando el suelo se remueve para sembrar papa o para abrir potreros, el daño va más allá del lugar intervenido: un suelo compactado o expuesto pierde su capacidad de retener agua, que entonces corre rápidamente cuesta abajo. A esto se suma otro problema: un frailejón crece apenas alrededor de un centímetro al año, de modo que un páramo degradado puede tardar décadas en recuperarse.', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('LEC-CTX-05', 'Pantallas y sueño en grado 11 (infografía)', 'INFOGRAFÍA · ¿Cuánto duermen los estudiantes de grado 11?
Encuesta aplicada a 1.200 estudiantes de grado 11 de colegios públicos de Pereira. Pregunta: «En las noches antes de un día de colegio, ¿cuánto tiempo usas pantallas (celular, computador o televisor) durante la última hora antes de dormir?».

Tiempo de pantallas en la última hora antes de dormir → % de estudiantes · horas de sueño (promedio) · % que se siente cansado en clase
• Nada → 12 % · 7,6 h · 21 %
• Menos de 30 minutos → 26 % · 7,1 h · 34 %
• Entre 30 y 60 minutos → 38 % · 6,4 h · 52 %
• Toda la hora → 24 % · 5,8 h · 69 %

Dato de referencia: los especialistas recomiendan que los adolescentes duerman entre 8 y 10 horas cada noche.
Fuente de los datos: encuesta ficticia elaborada con fines pedagógicos.

Después de conocer los resultados, dos personas los comentaron:

Rectora de un colegio participante: «Los datos demuestran que las pantallas hacen que nuestros estudiantes duerman menos. Si logramos que nadie use el celular antes de dormir, todos dormirán las horas recomendadas».

Personero estudiantil: «La mayoría de los encuestados usa pantallas por lo menos media hora antes de dormir, y en esos grupos el promedio de sueño no llega a siete horas».', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
-- LEC-COM-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-COM-01', (SELECT id FROM subtemas WHERE slug = 'comprension-textual'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-01'), 'En el primer párrafo, la narradora dice que el letrero del negocio «se fue quedando sin letras, como un diente de leche que nadie se atreve a arrancar». Con esta comparación sugiere que', NULL,
  NULL, 1, 'Identificar y entender los contenidos locales', 'Para interpretar una comparación, identifica los dos elementos que se relacionan y qué tienen en común. Aquí el letrero del negocio se compara con **un diente de leche flojo**: algo que ya está a punto de caerse, pero que nadie se atreve a arrancar. La frase aparece justo después de que la narradora cuenta que, con la llegada de los celulares, «los clientes dejaron de llegar». Por eso, el letrero que pierde sus letras representa el **deterioro lento del negocio**, y la parte de «nadie se atreve a arrancar» sugiere que nadie tomaba la decisión de cerrarlo del todo. Las demás opciones inventan hechos (un cambio de nombre, la falta de dinero) o leen la imagen de forma literal.', 75,
  ARRAY['sentido en contexto', 'comparación', 'lenguaje figurado', 'texto narrativo']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-COM-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-01'), 'A', 'el abuelo le cambió el nombre al negocio para atraer a los nuevos clientes que usaban celular.', false, 'El texto no menciona ningún cambio de nombre. Las letras se caen por abandono, no por una decisión del abuelo; además, se dice que los clientes «dejaron de llegar».'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-01'), 'B', 'los celulares que llegaron al pueblo fueron la causa directa de que el letrero se dañara físicamente.', false, 'Es una lectura demasiado literal. Los celulares explican que se acabaran los clientes, no que dañaran el letrero: la imagen del letrero expresa el deterioro del negocio.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-01'), 'C', 'el negocio se fue apagando poco a poco, pero nadie se decidía a cerrarlo definitivamente.', true, 'Correcta. El letrero que pierde letras muestra un deterioro lento, y el diente de leche flojo que «nadie se atreve a arrancar» es algo a punto de caer que nadie se decide a quitar del todo.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-01'), 'D', 'el abuelo no tenía dinero para arreglar el letrero, aunque todavía tenía muchos clientes.', false, 'Contradice el texto: justo antes se afirma que «los clientes dejaron de llegar». Tampoco se habla del dinero del abuelo.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-COM-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-COM-02', (SELECT id FROM subtemas WHERE slug = 'comprension-textual'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-04'), 'Según el texto, ¿de qué manera contribuyen los frailejones a que el páramo capte agua?', NULL,
  NULL, 1, 'Identificar y entender los contenidos locales', 'Es una pregunta de **información explícita**: la respuesta está escrita en el texto y hay que localizarla con precisión. El tercer párrafo explica que las hojas de los frailejones «están cubiertas de pelos finos que, además de protegerlas del frío, ayudan a atrapar las gotas diminutas de la niebla; esa agua escurre por la planta hasta el suelo». Las opciones incorrectas mezclan información de otros párrafos (D atribuye a las hojas la función de los suelos), contradicen el texto (C) o agregan datos que no aparecen (B). Estrategia: ubica la palabra clave de la pregunta («frailejones») y relee solo ese fragmento antes de elegir.', 60,
  ARRAY['información explícita', 'localizar información', 'texto expositivo', 'páramos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-COM-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-02'), 'A', 'Los pelos finos de sus hojas ayudan a atrapar las gotas de la niebla, y esa agua escurre por la planta hasta el suelo.', true, 'Correcta. Es lo que dice el tercer párrafo: los pelos de las hojas «ayudan a atrapar las gotas diminutas de la niebla; esa agua escurre por la planta hasta el suelo».'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-02'), 'B', 'Sus raíces profundas extraen agua subterránea y la llevan hasta la superficie del páramo.', false, 'El texto no menciona las raíces de los frailejones ni el agua subterránea. Es información agregada que suena científica, pero no está en la lectura.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-02'), 'C', 'Crecen muy rápido y forman bosques densos que atraen las lluvias hacia la montaña.', false, 'Contradice el texto: el frailejón crece «apenas alrededor de un centímetro al año». Además, el autor aclara que el secreto del páramo «no está en que llueva mucho».'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-COM-02'), 'D', 'Sus hojas absorben la lluvia y la guardan durante semanas, igual que los suelos oscuros del páramo.', false, 'Confunde la función de los suelos, que absorben la lluvia y la liberan «durante semanas», con la de los frailejones, que atrapan agua de la niebla.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-INF-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-INF-01', (SELECT id FROM subtemas WHERE slug = 'inferencias'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-01'), 'En el quinto párrafo, la narradora ve a su mamá entregarle a doña Leonor el radio de la cocina y piensa que se lo está prestando. Teniendo en cuenta todo el relato, sobre la perspectiva de la narradora es válido afirmar que', NULL,
  NULL, 2, 'Comprender cómo se articulan las partes de un texto', 'Esta pregunta combina **perspectiva del narrador** e **inferencia**. La historia la cuenta en primera persona la nieta del abuelo (él la llama «mija»), que solo sabe lo que ve y oye. Ella misma admite: «Yo no entendía de dónde salían tantos radios dañados en pleno siglo veintiuno». Sin embargo, el texto deja pistas: el abuelo estaba decaído cuando nadie le llevaba trabajo («Hablaba poco; comía menos»), los radios empiezan a llegar de repente y la mamá entrega el radio de la cocina envuelto en «la misma toalla de flores» con la que doña Leonor había llevado el suyo. Al unir esas pistas, el lector deduce que la mamá se puso de acuerdo con los vecinos para darle trabajo al abuelo, y la frase final («Cansado estaba antes») confirma que el plan funcionó. Por eso se dice que esta narradora **cuenta más de lo que entiende**.', 120,
  ARRAY['perspectiva del narrador', 'inferencia', 'narrador en primera persona', 'texto narrativo']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-INF-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-01'), 'A', 'conoce desde el principio el plan de su mamá, pero lo oculta para sorprender al lector en la última línea.', false, 'La narradora reconoce: «Yo no entendía de dónde salían tantos radios dañados». No oculta un plan: todavía no lo ha descubierto.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-01'), 'B', 'cuenta lo que ve sin captar su sentido completo, lo que permite al lector deducir algo que ella no advierte: que la llegada de los radios fue organizada para que el abuelo se sintiera útil.', true, 'Correcta. Las pistas (el decaimiento del abuelo, los radios que aparecen de repente, el radio de la cocina envuelto en «la misma toalla de flores») le permiten al lector ir más allá de la interpretación ingenua de la narradora.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-01'), 'C', 'es una narradora que conoce los pensamientos de todos los personajes, incluidos los del abuelo y los de los vecinos.', false, 'Es una narradora en primera persona que solo cuenta lo que ve y oye. Del abuelo conoce lo que dice y hace («me dijo sin levantar la vista»), no lo que piensa.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-01'), 'D', 'desconfía de doña Leonor y sospecha que la vecina quiere quedarse con el radio de la familia.', false, 'Nada en el texto indica desconfianza: la narradora supone, sin malicia, que se trata de un préstamo mientras el abuelo repara el radio de la vecina.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-INF-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-INF-02', (SELECT id FROM subtemas WHERE slug = 'inferencias'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-04'), 'A partir de la información del texto, se puede inferir que, si se degradara el páramo del que se abastece una ciudad,', NULL,
  NULL, 2, 'Comprender cómo se articulan las partes de un texto', 'Una inferencia válida no está escrita literalmente, pero se apoya en lo que el texto sí dice. Aquí hay que conectar dos partes. El segundo y el cuarto párrafo explican que los suelos del páramo **liberan el agua poco a poco** y que, gracias a eso, los ríos mantienen un caudal **estable incluso en temporada seca**. El cuarto párrafo agrega que un suelo compactado o expuesto **pierde su capacidad de retener agua**, que «corre rápidamente cuesta abajo». Al unir ambas ideas se concluye que un páramo degradado ya no regularía el agua: bajaría de golpe cuando llueve y faltaría cuando no llueve. La opción B es la trampa más común, porque confunde «más rápido» con «más agua»; la A y la C contradicen datos del texto.', 120,
  ARRAY['inferencia', 'causa y efecto', 'texto expositivo', 'páramos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-INF-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-02'), 'A', 'la ciudad dejaría de recibir lluvias, porque el páramo es el ecosistema que produce la lluvia en la región.', false, 'El texto no dice que el páramo produzca lluvia; al contrario, aclara que su secreto «no está en que llueva mucho», sino en la forma en que guarda el agua.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-02'), 'B', 'los ríos tendrían más agua durante todo el año, porque el agua bajaría más rápido desde la montaña.', false, 'Es una lectura parcial: que el agua corra más rápido no significa que haya más agua. Sin la liberación lenta, el caudal dejaría de ser estable y bajaría en temporada seca.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-02'), 'C', 'el problema se resolvería en pocos meses sembrando nuevos frailejones en las zonas afectadas.', false, 'Contradice el último párrafo: un frailejón crece «apenas alrededor de un centímetro al año» y un páramo degradado «puede tardar décadas en recuperarse».'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INF-02'), 'D', 'el caudal de los ríos se volvería más irregular: el agua bajaría rápidamente en época de lluvias y escasearía en temporada seca.', true, 'Correcta. Se deduce al unir dos ideas del texto: la liberación lenta del agua mantiene estable el caudal, y un suelo dañado «pierde su capacidad de retener agua, que entonces corre rápidamente cuesta abajo».')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-INT-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-INT-01', (SELECT id FROM subtemas WHERE slug = 'interpretacion'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-03'), '¿Cuál de los siguientes enunciados expresa mejor la idea principal del texto?', NULL,
  NULL, 2, 'Comprender cómo se articulan las partes de un texto', 'La idea principal es la afirmación que organiza todo el texto y que las demás partes sostienen. El autor distingue dos tipos de preguntas: las de **preferencia o acción colectiva** (a dónde ir de excursión, qué hacer en común), que se deciden legítimamente por mayoría, y las preguntas sobre **hechos** (si la Tierra se mueve, si alguien cometió un delito), que solo se responden examinando pruebas. El ejemplo histórico del segundo párrafo, la aclaración del tercero y la imagen del puente del cuarto apoyan esa misma distinción. La opción C es un **detalle** que funciona como ejemplo; la A es una **exageración** que el texto desmiente; la D es una **extrapolación** que el autor nunca plantea. Truco: la idea principal debe «caber» en todos los párrafos, no solo en uno.', 120,
  ARRAY['idea principal', 'tesis', 'texto filosófico', 'verdad']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-INT-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-01'), 'A', 'La opinión de la mayoría no tiene valor, porque a lo largo de la historia las personas se han equivocado muchas veces.', false, 'Contradice el tercer párrafo: «Esto no significa que la opinión de la mayoría carezca de valor». Es una exageración que el propio autor rechaza.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-01'), 'B', 'Votar es legítimo para decidir sobre preferencias y acciones colectivas, pero la verdad de un hecho no depende de la mayoría, sino de las pruebas.', true, 'Correcta. Recoge las dos partes de la tesis: el valor de votar sobre «lo que queremos hacer juntos» y el límite de las votaciones frente a la pregunta «¿cómo son las cosas?».'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-01'), 'C', 'Durante siglos, la mayoría de las personas creyó que la Tierra permanecía quieta en el centro del universo.', false, 'Es un dato que aparece en el texto, pero funciona como ejemplo dentro del segundo párrafo; no resume lo que plantea el texto completo.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-01'), 'D', 'Las democracias deberían dejar las decisiones públicas en manos de científicos e ingenieros.', false, 'El texto no propone eso: afirma que votar es «la mejor manera que conocemos» de decidir juntos. La imagen del puente y los cálculos es una comparación, no una propuesta.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-INT-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-INT-02', (SELECT id FROM subtemas WHERE slug = 'interpretacion'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-05'), 'De acuerdo con la infografía, a medida que aumenta el tiempo de uso de pantallas en la última hora antes de dormir,', NULL,
  NULL, 1, 'Identificar y entender los contenidos locales', 'En un texto discontinuo, primero identifica qué representa cada columna y luego compara los valores en orden. La primera columna organiza a los estudiantes de menor a mayor uso de pantallas: nada, menos de 30 minutos, entre 30 y 60 minutos y toda la hora. Si sigues ese orden, las horas de sueño **bajan** (7,6 → 7,1 → 6,4 → 5,8) y el porcentaje de cansancio **sube** (21 % → 34 % → 52 % → 69 %). Ojo: la tabla muestra que ambas cosas ocurren juntas, pero por sí sola no demuestra que una cause la otra. Las opciones incorrectas confunden columnas (A), invierten la tendencia (B) o leen solo una parte de los datos (D).', 75,
  ARRAY['texto discontinuo', 'tablas', 'tendencias', 'interpretación de datos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-INT-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-02'), 'A', 'aumenta el porcentaje de estudiantes que hay en cada grupo.', false, 'Confunde las columnas: los porcentajes de estudiantes por grupo son 12 %, 26 %, 38 % y 24 %; suben y luego bajan, así que no aumentan de forma constante.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-02'), 'B', 'aumenta el promedio de horas de sueño, aunque también el cansancio en clase.', false, 'Invierte la tendencia de la columna de sueño: el promedio baja de 7,6 a 5,8 horas.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-02'), 'C', 'disminuye el promedio de horas de sueño y aumenta el porcentaje de estudiantes que dicen sentirse cansados en clase.', true, 'Correcta. El sueño baja de 7,6 h a 7,1 h, 6,4 h y 5,8 h, mientras que el cansancio sube de 21 % a 34 %, 52 % y 69 %.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-INT-02'), 'D', 'el promedio de horas de sueño se mantiene casi igual, pero el cansancio en clase aumenta.', false, 'Una diferencia de casi dos horas (de 7,6 a 5,8) no es «casi igual». Esta opción solo lee bien una de las dos columnas.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-ANA-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-ANA-01', (SELECT id FROM subtemas WHERE slug = 'analisis-textos'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-02'), 'El tercer párrafo de la columna comienza con la expresión «Ahora bien». En el desarrollo del texto, ese párrafo cumple la función de', NULL,
  NULL, 2, 'Comprender cómo se articulan las partes de un texto', '**«Ahora bien»** es un conector que introduce un matiz o una concesión: el autor reconoce algo que podría usarse en contra de su postura. En el tercer párrafo admite que el celular «también sirve para consultar, traducir o practicar en plataformas educativas». Luego delimita su propuesta: el profesor puede autorizar su uso durante un tiempo definido, porque «lo que sobra no es la herramienta, sino su presencia permanente». Así, el párrafo anticipa una objeción y la responde sin abandonar la tesis. Este movimiento (**concesión + precisión**) fortalece la columna, porque muestra que el autor consideró el otro lado del debate. No es una razón más (A), ni un cambio de postura (B), ni la conclusión (C).', 120,
  ARRAY['función de un párrafo', 'conectores', 'concesión', 'texto argumentativo']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-01'), 'A', 'añadir una cuarta razón a favor de guardar los celulares, del mismo tipo que las del segundo párrafo.', false, '«Ahora bien» no suma una razón más a favor de la medida (eso lo haría un conector como «además»); introduce un matiz frente a lo dicho.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-01'), 'B', 'mostrar que el autor cambió de postura y ahora considera que guardar el celular es un error.', false, 'El autor no cambia de opinión: después de reconocer los usos del celular, mantiene que «lo que sobra no es la herramienta, sino su presencia permanente».'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-01'), 'C', 'resumir los argumentos anteriores y cerrar la columna con una conclusión.', false, 'No es el cierre del texto: después viene un cuarto párrafo que responde a otra objeción y concluye la columna.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-01'), 'D', 'reconocer una posible objeción, los usos educativos del celular, y precisar el alcance de la propuesta para que no se entienda como una prohibición total.', true, 'Correcta. El autor concede que el celular sirve «para consultar, traducir o practicar» y aclara que nadie propone «desterrarlo para siempre», sino evitar su presencia permanente.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-ANA-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-ANA-02', (SELECT id FROM subtemas WHERE slug = 'analisis-textos'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-05'), 'Al comparar los comentarios de la rectora y del personero con los datos de la infografía, se puede afirmar que', NULL,
  NULL, 3, 'Reflexionar a partir de un texto y evaluar su contenido', 'Esta pregunta pide evaluar la **relación entre unas afirmaciones y los datos** que deberían respaldarlas. El personero describe: 38 % + 24 % = 62 % de los encuestados usa pantallas al menos media hora antes de dormir (es la mayoría), y en esos grupos el promedio es de 6,4 y 5,8 horas, es decir, menos de siete. Todo eso se comprueba en la tabla. La rectora da dos pasos que los datos no permiten: primero, afirma que las pantallas **causan** el poco sueño, cuando la tabla solo muestra que ambas cosas aparecen juntas (podrían influir otros factores, como las tareas o los horarios); segundo, predice que **todos** dormirán las horas recomendadas, aunque incluso quienes no usan pantallas promedian 7,6 horas, por debajo de las 8 recomendadas. Recuerda: **correlación no es causalidad**.', 180,
  ARRAY['texto discontinuo', 'relación entre afirmaciones', 'correlación y causalidad', 'evaluación de información']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-02'), 'A', 'el personero se limita a describir lo que muestran los datos, mientras que la rectora afirma una relación de causa y efecto y hace una predicción que la tabla no permite sostener.', true, 'Correcta. El 38 % más el 24 % (62 %, la mayoría) usa pantallas media hora o más, y esos grupos duermen 6,4 y 5,8 horas. La rectora, en cambio, habla de causas y predice que «todos» dormirán las horas recomendadas, cuando incluso el grupo que no usa pantallas promedia 7,6 horas.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-02'), 'B', 'ambos comentarios se desprenden directamente de la tabla, porque los dos relacionan el uso de pantallas con las horas de sueño.', false, 'Hablar de los mismos temas no significa estar respaldado por los datos. La tabla muestra que dos variables cambian juntas, pero no prueba causas ni permite predecir lo que pasará.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-02'), 'C', 'la rectora tiene razón y el personero se equivoca, porque solo el 24 % de los estudiantes usa pantallas durante toda la hora.', false, 'Error de lectura: el personero habla de quienes usan pantallas «por lo menos media hora», es decir, los grupos de 38 % y 24 %, que suman 62 %.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ANA-02'), 'D', 'ninguno de los dos comentarios es válido, porque una encuesta a 1.200 estudiantes no permite decir nada sobre sus hábitos de sueño.', false, 'El comentario del personero describe a los propios encuestados, así que sí está respaldado por los datos. Descartar toda la encuesta es una exageración.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-ARG-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-ARG-01', (SELECT id FROM subtemas WHERE slug = 'argumentacion'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-02'), 'En el segundo párrafo, el autor sostiene que guardar los celulares durante la jornada ayuda a reducir el ciberacoso. ¿Cuál de los siguientes hallazgos, de ser cierto, debilitaría más ese argumento?', NULL,
  NULL, 3, 'Reflexionar a partir de un texto y evaluar su contenido', 'Para debilitar un argumento hay que atacar el vínculo entre sus razones y su conclusión. El autor razona así: muchos videos para humillar a compañeros **se grababan dentro del colegio**; por lo tanto, si los celulares se guardan durante la jornada, habrá menos ciberacoso. Si se demostrara que casi todo el ciberacoso **se origina y se difunde fuera de la jornada**, la medida tendría un efecto mínimo sobre ese problema y la premisa del autor quedaría en duda. La opción B, en cambio, refuerza el argumento; la A apela a la popularidad de la norma, que no prueba nada sobre sus efectos; y la D repite una objeción que el autor ya reconoció y que no se refiere al ciberacoso. Pregunta clave para estos ítems: ¿qué dato haría que la conclusión dejara de seguirse de las razones?', 150,
  ARRAY['debilitar un argumento', 'premisas', 'evaluación de argumentos', 'texto argumentativo']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-01'), 'A', 'Después de unos meses, la mayoría de los estudiantes del colegio manifestó estar de acuerdo con guardar los celulares.', false, 'Que una medida sea popular no dice nada sobre su efecto en el ciberacoso. Este dato no fortalece ni debilita la relación entre la medida y el problema.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-01'), 'B', 'En varios colegios de la ciudad, los videos con los que se humillaba a estudiantes se grababan con frecuencia en baños y salones.', false, 'Este hallazgo coincide con la premisa del autor (los videos «se grababan dentro del colegio, en los baños o en los salones»), así que refuerza el argumento en lugar de debilitarlo.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-01'), 'C', 'Un estudio encontró que casi todos los casos de ciberacoso entre estudiantes se originan y se difunden fuera de la jornada escolar, desde las casas.', true, 'Correcta. Si el ciberacoso ocurre casi siempre fuera del colegio, guardar los celulares durante la jornada tendría poco efecto sobre él, y la premisa del autor pierde fuerza.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-01'), 'D', 'Muchos estudiantes usan el celular en su casa hasta altas horas de la noche.', false, 'El autor ya admite este hecho en el cuarto párrafo («Es cierto») y lo responde. Además, el dato habla de cuánto usan el celular, no de dónde se produce el ciberacoso.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- LEC-ARG-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('LEC-ARG-02', (SELECT id FROM subtemas WHERE slug = 'argumentacion'), (SELECT id FROM contextos WHERE codigo = 'LEC-CTX-03'), 'En el segundo párrafo, el autor cuestiona a quienes sostienen que, si casi todos en una comunidad creen algo, eso es verdadero. ¿Cuál de los siguientes razonamientos comete el mismo error que el autor señala en esa postura?', NULL,
  NULL, 3, 'Reflexionar a partir de un texto y evaluar su contenido', 'Primero hay que identificar el error de la postura criticada: pasar de «casi todos creen X» a «X es verdadero». El autor la refuta con un **contraejemplo** histórico: la mayoría creyó que la Tierra estaba quieta, «y la Tierra no dejó de moverse por eso». Ese error se conoce como **falacia ad populum** o apelación a la mayoría: tomar la popularidad de una creencia como si fuera una prueba. En la opción A ocurre exactamente lo mismo: que todo el barrio use y recomiende un remedio no demuestra que cure la gripa; eso solo lo muestran las pruebas. Las otras opciones también son razonamientos defectuosos, pero de otro tipo: ataque a la persona (B), generalización apresurada (C) y falsa disyuntiva (D). En preguntas de «mismo error» no basta con encontrar un razonamiento incorrecto: debe tener la misma estructura.', 150,
  ARRAY['falacias', 'ad populum', 'contraejemplo', 'evaluación de argumentos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-02'), 'A', '«Ese remedio casero seguro cura la gripa: en mi barrio todo el mundo lo usa y lo recomienda».', true, 'Correcta. Toma la cantidad de personas que creen en el remedio como prueba de que funciona, igual que la postura que critica el autor (falacia ad populum o apelación a la mayoría).'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-02'), 'B', '«No le creo a Julián lo que dice sobre el reciclaje, porque él mismo bota basura en la calle».', false, 'Aquí se descalifica una idea por la conducta de quien la dice (falacia ad hominem). No se apela a lo que cree la mayoría.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-02'), 'C', '«Leí dos novelas de ciencia ficción y me aburrieron; todos los libros de ese género son aburridos».', false, 'Es una generalización apresurada: se concluye algo sobre todo un género a partir de dos casos. El error no consiste en apelar a la mayoría.'),
  ((SELECT id FROM preguntas WHERE codigo = 'LEC-ARG-02'), 'D', '«O apoyas todas las propuestas del personero, o estás en contra del colegio».', false, 'Es una falsa disyuntiva: presenta solo dos opciones cuando existen otras (por ejemplo, apoyar algunas propuestas y otras no). No se relaciona con la opinión de la mayoría.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;

