Grado | Bus | Bicicleta | A pie | Total
10.º | 75 | 30 | 45 | 150
11.º | 35 | 25 | 40 | 100
Total | 110 | 55 | 85 | 250', NULL, NULL, 'Texto original elaborado para ICFES Lab')
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
