-- MAT-ALG-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-ALG-01-CTX', NULL, 'En una plaza de mercado de Tunja, el precio de un bulto de papa pastusa pasó de $80.000 en enero a $92.000 en marzo.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-ALG-01', (SELECT id FROM subtemas WHERE slug = 'algebra'), (SELECT id FROM contextos WHERE codigo = 'MAT-ALG-01-CTX'), '¿En qué porcentaje aumentó el precio del bulto de papa entre enero y marzo?', NULL,
  NULL, 1, 'Formulación y ejecución', '**Paso 1.** Calcula el aumento en pesos: 92.000 − 80.000 = $12.000.
**Paso 2.** Compara ese aumento con el precio **inicial**: 12.000 ÷ 80.000 = 0,15.
**Paso 3.** Exprésalo en porcentaje: 0,15 × 100 = 15 %.
**Comprobación:** aumentar un 15 % equivale a multiplicar por 1,15, y 80.000 × 1,15 = 92.000 ✓.
Recuerda: la variación porcentual siempre se calcula respecto al valor inicial, no al final.', 75,
  ARRAY['porcentajes', 'variación porcentual', 'aumento de precios']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-01'), 'A', '12 %', false, 'Toma el aumento de $12.000 como si fuera un 12 %. Un aumento en pesos no es un porcentaje: hay que compararlo con el precio inicial, 12.000 ÷ 80.000 = 0,15.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-01'), 'B', '13 %', false, 'Resulta de dividir el aumento entre el precio final (12.000 ÷ 92.000 ≈ 0,13). La variación porcentual se calcula respecto al valor inicial, $80.000.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-01'), 'C', '15 %', true, 'Correcto: el aumento es 92.000 − 80.000 = $12.000 y 12.000 ÷ 80.000 = 0,15, es decir, 15 %. Comprobación: 80.000 × 1,15 = 92.000.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-01'), 'D', '115 %', false, 'Sale de 92.000 ÷ 80.000 = 1,15, que indica que el precio de marzo es el 115 % del de enero. El aumento es solo lo que supera el 100 %, es decir, 15 %.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-ALG-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-ALG-02-CTX', NULL, 'El grupo de teatro de un colegio de Barranquilla presentó una obra en el auditorio. La boleta general costaba $12.000 y la boleta para estudiantes, $8.000. En total se vendieron 180 boletas y se recaudaron $1.840.000.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-ALG-02', (SELECT id FROM subtemas WHERE slug = 'algebra'), (SELECT id FROM contextos WHERE codigo = 'MAT-ALG-02-CTX'), '¿Cuántas boletas para estudiantes se vendieron?', NULL,
  NULL, 2, 'Formulación y ejecución', 'Sean g las boletas generales y e las boletas para estudiantes. El enunciado da dos ecuaciones:
• g + e = 180 (cantidad de boletas)
• 12.000g + 8.000e = 1.840.000 (dinero recaudado)
De la primera, g = 180 − e. Al sustituir en la segunda: 12.000(180 − e) + 8.000e = 1.840.000 → 2.160.000 − 4.000e = 1.840.000 → 4.000e = 320.000 → **e = 80**. Entonces g = 180 − 80 = 100.
**Comprobación:** 100 × 12.000 + 80 × 8.000 = 1.200.000 + 640.000 = 1.840.000 ✓.', 150,
  ARRAY['sistemas de ecuaciones', 'sistema 2×2', 'método de sustitución']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-02'), 'A', '40', false, 'Sale de suponer que todas las boletas fueron generales (180 × 12.000 = 2.160.000) y dividir el excedente de $320.000 entre 8.000. Cada boleta de estudiante reduce el recaudo en 12.000 − 8.000 = 4.000, así que el excedente debe dividirse entre 4.000, lo que da 80.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-02'), 'B', '80', true, 'Correcto: con g + e = 180 y 12.000g + 8.000e = 1.840.000 se obtiene e = 80 y g = 100. Comprobación: 100 × 12.000 + 80 × 8.000 = 1.840.000.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-02'), 'C', '92', false, 'Resulta de dividir 1.840.000 entre la suma de los precios (20.000). Eso supondría que se vendieron 92 boletas de cada tipo, es decir, 184 boletas en total y no 180.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-ALG-02'), 'D', '100', false, '100 es la cantidad de boletas generales. El sistema se resolvió bien, pero se respondió la otra incógnita: las boletas para estudiantes son 180 − 100 = 80.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-GEO-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-GEO-01-CTX', NULL, 'Don Hernando tiene un lote en una vereda de Duitama (Boyacá) con forma de trapecio rectángulo, como se muestra en la figura. El lado de 15 m es perpendicular a las dos bases. Él quiere cercar todo el borde del lote con malla.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-GEO-01', (SELECT id FROM subtemas WHERE slug = 'geometria'), (SELECT id FROM contextos WHERE codigo = 'MAT-GEO-01-CTX'), '¿Cuántos metros de malla necesita don Hernando para cercar todo el lote?', '/img/preguntas/MAT-GEO-01.svg',
  'Trapecio rectángulo que representa el lote: base inferior de 20 m, base superior de 12 m y lado vertical de 15 m, perpendicular a ambas bases. El lado inclinado no tiene medida y está marcado con un signo de interrogación.', 2, 'Formulación y ejecución', '**Paso 1.** Traza una línea vertical desde el extremo derecho de la base menor hasta la base mayor. Se forma un triángulo rectángulo con catetos de 15 m (la altura) y 20 − 12 = 8 m.
**Paso 2.** El lado inclinado es la hipotenusa. Por el teorema de Pitágoras: c² = 8² + 15² = 64 + 225 = 289, así que c = √289 = 17 m.
**Paso 3.** El perímetro es la suma de los cuatro lados: 20 + 12 + 15 + 17 = **64 m**.
Observa que 8, 15 y 17 forman una terna pitagórica que conviene recordar.', 120,
  ARRAY['perímetro', 'teorema de pitágoras', 'trapecio']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-01'), 'A', '47 m', false, 'Solo suma los tres lados con medida conocida (20 + 12 + 15 = 47) y olvida el lado inclinado, que también hay que cercar.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-01'), 'B', '55 m', false, 'Toma el lado inclinado como 8 m, la diferencia entre las bases. Ese valor es solo uno de los catetos del triángulo rectángulo que se forma; el lado inclinado es la hipotenusa.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-01'), 'C', '62 m', false, 'Supone que el lado inclinado mide lo mismo que la altura (15 m). El lado inclinado es la hipotenusa de un triángulo rectángulo y siempre es más largo que cada cateto.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-01'), 'D', '64 m', true, 'Correcto: el lado inclinado mide √(8² + 15²) = √289 = 17 m y el perímetro es 20 + 12 + 15 + 17 = 64 m.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-GEO-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-GEO-02-CTX', NULL, 'El acueducto de una vereda de Garzón (Huila) tiene un tanque cilíndrico de 2 m de radio y 3 m de altura. La junta de acción comunal planea construir un tanque nuevo, también cilíndrico, con el doble del radio y la mitad de la altura del actual. El ingeniero encargado afirma: «El tanque nuevo tendrá la misma capacidad que el actual, porque lo que gana en radio lo pierde en altura».', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-GEO-02', (SELECT id FROM subtemas WHERE slug = 'geometria'), (SELECT id FROM contextos WHERE codigo = 'MAT-GEO-02-CTX'), '¿Es correcta la afirmación del ingeniero?', NULL,
  NULL, 3, 'Argumentación', 'La capacidad de un tanque cilíndrico es su volumen: V = π·r²·h.
• Tanque actual: V = π · 2² · 3 = 12π m³ ≈ 37,7 m³.
• Tanque nuevo: r = 4 m y h = 1,5 m, así que V = π · 4² · 1,5 = 24π m³ ≈ 75,4 m³.
Como el radio está **al cuadrado**, duplicarlo multiplica el volumen por 2² = 4; reducir la altura a la mitad lo divide entre 2. El efecto neto es 4 ÷ 2 = 2: el tanque nuevo tiene el **doble** de capacidad, así que la afirmación del ingeniero es falsa.
Ojo: la superficie lateral sí es igual en ambos tanques (12π m²), pero el área no indica cuánta agua cabe.', 150,
  ARRAY['volumen', 'cilindro', 'cambio de dimensiones']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-02'), 'A', 'No, porque el volumen depende del cuadrado del radio: el tanque nuevo tendría 24π m³, el doble de los 12π m³ del actual.', true, 'Correcto: V = π·r²·h. Actual: π·2²·3 = 12π m³. Nuevo: π·4²·1,5 = 24π m³. Duplicar el radio multiplica el volumen por 4 y reducir la altura a la mitad lo divide entre 2: el efecto neto es ×2.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-02'), 'B', 'No, porque al duplicar el radio el volumen se cuadruplica: el tanque nuevo tendría 48π m³, cuatro veces la capacidad actual.', false, 'Tiene en cuenta el efecto del radio (×4), pero olvida que la altura se reduce a la mitad. 48π m³ sería la capacidad si la altura siguiera siendo de 3 m.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-02'), 'C', 'Sí, porque el radio se multiplica por 2 y la altura se divide entre 2, y esos dos cambios se compensan exactamente.', false, 'Es un razonamiento lineal: el radio aparece elevado al cuadrado en la fórmula del volumen, así que su efecto (×4) es mayor que el de la altura (÷2).'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GEO-02'), 'D', 'Sí, porque los dos tanques tienen la misma superficie lateral, 12π m², y por lo tanto les cabe la misma cantidad de agua.', false, 'Es cierto que la superficie lateral (2π·r·h) mide 12π m² en ambos tanques, pero el área no mide la capacidad. La capacidad es el volumen, y el del tanque nuevo es el doble.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-EST-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-EST-01-CTX', NULL, 'La bibliotecaria de un colegio de Tunja registró cuántos libros prestó cada día, de lunes a viernes, durante una semana. Los resultados se muestran en la gráfica.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-EST-01', (SELECT id FROM subtemas WHERE slug = 'estadistica'), (SELECT id FROM contextos WHERE codigo = 'MAT-EST-01-CTX'), '¿Cuál fue el promedio (media aritmética) de libros prestados por día durante esa semana?', '/img/preguntas/MAT-EST-01.svg',
  'Gráfica de barras del número de libros prestados por día: lunes 15, martes 20, miércoles 10, jueves 25 y viernes 20. El eje vertical va de 0 a 30 de 5 en 5.', 1, 'Interpretación y representación', '**Paso 1.** Lee en la gráfica el valor de cada barra: lunes 15, martes 20, miércoles 10, jueves 25 y viernes 20.
**Paso 2.** Suma todos los datos: 15 + 20 + 10 + 25 + 20 = 90.
**Paso 3.** Divide entre la cantidad de datos (5 días): 90 ÷ 5 = **18 libros por día**.
No confundas la media con la mediana ni con la moda, que en este caso valen 20.', 75,
  ARRAY['media aritmética', 'gráfica de barras', 'lectura de gráficas']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-EST-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-01'), 'A', '17,5 libros', false, 'Resulta de promediar solo los valores distintos (10, 15, 20 y 25): 70 ÷ 4 = 17,5. Cada día cuenta, así que el 20 debe sumarse dos veces (martes y viernes).'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-01'), 'B', '18 libros', true, 'Correcto: la suma es 15 + 20 + 10 + 25 + 20 = 90 libros y hay 5 días, así que la media es 90 ÷ 5 = 18.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-01'), 'C', '20 libros', false, '20 es la mediana (el dato central al ordenar: 10, 15, 20, 20, 25) y también la moda, pero no la media.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-01'), 'D', '90 libros', false, '90 es el total de libros prestados en la semana. Para obtener el promedio falta dividir entre los 5 días.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-EST-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-EST-02-CTX', NULL, 'El consejo estudiantil de un colegio de Pereira, que tiene 1.200 estudiantes, quiere saber cuál es el deporte preferido para organizar un torneo. Para ello encuestó a los 40 integrantes de la selección de fútbol del colegio, y 30 de ellos respondieron que su deporte preferido es el fútbol. Con base en esto, el consejo concluyó que el 75 % de los estudiantes del colegio prefiere el fútbol.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-EST-02', (SELECT id FROM subtemas WHERE slug = 'estadistica'), (SELECT id FROM contextos WHERE codigo = 'MAT-EST-02-CTX'), '¿Es válida la conclusión del consejo estudiantil?', NULL,
  NULL, 2, 'Argumentación', 'Para generalizar el resultado de una encuesta a toda la población (los 1.200 estudiantes), la muestra debe ser **representativa**, es decir, parecerse a la población en lo que se quiere estudiar.
Aquí se encuestó únicamente a la selección de fútbol, un grupo que por su naturaleza tiende a preferir ese deporte: es un **sesgo de selección**.
El cálculo 30 ÷ 40 = 75 % es correcto, pero solo describe a la selección, no al colegio.
Una forma adecuada sería escoger al azar estudiantes de todos los grados y cursos; el problema no es el tamaño de la muestra, sino cómo se eligió.', 90,
  ARRAY['muestra representativa', 'sesgo', 'encuestas']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-EST-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-02'), 'A', 'Sí, porque 30 de los 40 encuestados equivalen exactamente al 75 %, y ese porcentaje se puede aplicar a todo el colegio.', false, 'El cálculo es correcto (30 ÷ 40 = 0,75), pero solo describe a la selección de fútbol. Un cálculo bien hecho no corrige una muestra mal escogida.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-02'), 'B', 'Sí, porque 40 estudiantes es una muestra suficientemente grande para representar a un colegio de 1.200 estudiantes.', false, 'El tamaño no es lo único importante: si los encuestados salen de un grupo particular, la muestra sigue sesgada, sin importar cuántos sean.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-02'), 'C', 'No, porque para que una encuesta sea válida se debe preguntar como mínimo a la mitad de los estudiantes del colegio.', false, 'No existe esa regla. Una muestra pequeña puede ser válida si se elige al azar entre todos los estudiantes; el problema aquí es a quiénes se encuestó, no cuántos.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-EST-02'), 'D', 'No, porque solo se encuestó a jugadores de fútbol, que tienden a preferir ese deporte, así que la muestra no representa al colegio.', true, 'Correcto: la muestra tiene un sesgo de selección. Para generalizar, habría que elegir al azar estudiantes de todos los grados y cursos.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-PRO-01
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-PRO-01', (SELECT id FROM subtemas WHERE slug = 'probabilidad'), (SELECT id FROM contextos WHERE codigo = 'MAT-CTX-01'), 'Si se elige al azar uno de los 250 estudiantes encuestados, ¿cuál es la probabilidad de que llegue al colegio en bus?', NULL,
  NULL, 1, 'Interpretación y representación', 'La probabilidad clásica es P = casos favorables ÷ casos posibles.
**Casos posibles:** los 250 estudiantes encuestados.
**Casos favorables:** los que llegan en bus; según la columna «Bus», son 75 + 35 = 110.
P = 110/250 = 11/25 = 0,44, es decir, **44 %**.
Si la pregunta hubiera dicho «si se elige un estudiante de 10.º», el total de casos posibles se reduciría a 150.', 75,
  ARRAY['probabilidad clásica', 'tabla de doble entrada', 'casos favorables']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-01'), 'A', '1/3', false, 'Supone que los tres medios de transporte son igual de probables. No es así: cada estudiante es un caso, y muchos más estudiantes llegan en bus que en bicicleta.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-01'), 'B', '11/25', true, 'Correcto: 110 de los 250 estudiantes llegan en bus, y 110/250 = 11/25 = 0,44 = 44 %.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-01'), 'C', '1/2', false, 'Es la probabilidad calculada solo con los estudiantes de 10.º (75/150). La pregunta se refiere a todos los encuestados, así que se deben usar los totales.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-01'), 'D', '11/14', false, 'Divide los casos favorables entre los no favorables (110/140). En la probabilidad, el denominador son todos los casos posibles: 250.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-PRO-02
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-PRO-02', (SELECT id FROM subtemas WHERE slug = 'probabilidad'), (SELECT id FROM contextos WHERE codigo = 'MAT-CTX-01'), 'Mateo observa en la tabla que 30 estudiantes de 10.º llegan en bicicleta, mientras que en 11.º solo lo hacen 25. Por eso afirma: «Si se elige al azar un estudiante de 10.º, es más probable que llegue en bicicleta que si se elige al azar un estudiante de 11.º». ¿Es correcta la afirmación de Mateo?', NULL,
  NULL, 3, 'Argumentación', 'La afirmación compara dos probabilidades **condicionales**: primero se fija el grado y luego se pregunta por la bicicleta. Por eso los casos posibles son solo los estudiantes de ese grado.
• P(bicicleta | 10.º) = 30/150 = 0,20 = 20 % (se lee «probabilidad de llegar en bicicleta dado que es de 10.º»).
• P(bicicleta | 11.º) = 25/100 = 0,25 = 25 %.
Aunque en 10.º hay más ciclistas (30 > 25), también hay más estudiantes (150 > 100), así que la proporción es menor.
Es más probable que un estudiante de 11.º llegue en bicicleta, y la afirmación de Mateo es **falsa**.', 150,
  ARRAY['probabilidad condicional', 'tabla de doble entrada', 'argumentación']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-02'), 'A', 'No, porque la probabilidad es 30/150 = 20 % para un estudiante de 10.º y 25/100 = 25 % para uno de 11.º.', true, 'Correcto: al fijar el grado, los casos posibles son solo los estudiantes de ese grado. En proporción, en 11.º hay más estudiantes que llegan en bicicleta.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-02'), 'B', 'No, porque en ambos casos la probabilidad es 55/250 = 22 %, ya que todos son estudiantes del mismo colegio.', false, '22 % es la probabilidad de que un estudiante cualquiera llegue en bicicleta. Al elegir dentro de un grado, el total de casos posibles cambia y la probabilidad también.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-02'), 'C', 'Sí, porque 30 es mayor que 25; es decir, en 10.º hay más casos favorables que en 11.º.', false, 'Compara solo los casos favorables e ignora que los grupos tienen distinto tamaño: 150 estudiantes en 10.º y 100 en 11.º.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-PRO-02'), 'D', 'Sí, porque de los 55 estudiantes que llegan en bicicleta, 30 son de 10.º y 25 de 11.º, y 30/55 es mayor que 25/55.', false, 'Invierte la condición: 30/55 es la probabilidad de que un ciclista elegido al azar sea de 10.º, no la de que un estudiante de 10.º llegue en bicicleta.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-CAL-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-CAL-01-CTX', NULL, 'En el Festival del Viento y de las Cometas de Villa de Leyva (Boyacá), Samuel registró la altura de su cometa durante 12 minutos de vuelo. La gráfica muestra la altura h, en metros, en función del tiempo t, en minutos.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-CAL-01', (SELECT id FROM subtemas WHERE slug = 'calculo-basico'), (SELECT id FROM contextos WHERE codigo = 'MAT-CAL-01-CTX'), '¿En cuál de los siguientes intervalos de tiempo la cometa descendió con mayor rapidez?', '/img/preguntas/MAT-CAL-01.svg',
  'Gráfica de la altura de la cometa (en metros) contra el tiempo (en minutos), formada por segmentos rectos: sube de 0 m a 30 m entre los minutos 0 y 2, llega a 50 m en el minuto 4, se mantiene en 50 m hasta el minuto 6, baja a 30 m en el minuto 7 y desciende hasta 0 m en el minuto 12.', 2, 'Interpretación y representación', 'La rapidez con que cambia la altura en un intervalo es la tasa de cambio: Δh ÷ Δt. Solo interesan los tramos en los que la gráfica **baja**.
• Del minuto 6 al 7: (30 − 50) ÷ (7 − 6) = −20 m/min.
• Del minuto 7 al 12: (0 − 30) ÷ (12 − 7) = −6 m/min.
El signo negativo indica descenso. La cometa descendió más rápido entre los minutos 6 y 7 (20 m por minuto), aunque en total perdió más altura entre los minutos 7 y 12.
En la gráfica, ese es el tramo decreciente más inclinado.', 105,
  ARRAY['tasa de cambio', 'interpretación de gráficas', 'decrecimiento']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-01'), 'A', 'Entre el minuto 0 y el minuto 2', false, 'En ese tramo la altura cambia rápido (15 m por minuto), pero la cometa está subiendo, no descendiendo: la gráfica es creciente.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-01'), 'B', 'Entre el minuto 4 y el minuto 6', false, 'En ese tramo la cometa está en su altura máxima (50 m), pero la gráfica es horizontal: la altura no cambia, así que la rapidez de cambio es 0.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-01'), 'C', 'Entre el minuto 6 y el minuto 7', true, 'Correcto: la altura baja de 50 m a 30 m en 1 minuto, es decir, 20 m por minuto. Es el tramo decreciente más inclinado.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-01'), 'D', 'Entre el minuto 7 y el minuto 12', false, 'Es el tramo en el que más altura se pierde (30 m), pero lo hace en 5 minutos: 30 ÷ 5 = 6 m por minuto, más lento que entre los minutos 6 y 7.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- MAT-CAL-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-CAL-02-CTX', NULL, 'Un emprendimiento de arepas de Bogotá tiene 1.600 seguidores en redes sociales. Una agencia de publicidad le ofrece dos estrategias:
• Estrategia 1: ganar 1.500 seguidores nuevos cada mes.
• Estrategia 2: aumentar cada mes el número de seguidores en un 50 % respecto a los que tenga al final del mes anterior.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('MAT-CAL-02', (SELECT id FROM subtemas WHERE slug = 'calculo-basico'), (SELECT id FROM contextos WHERE codigo = 'MAT-CAL-02-CTX'), 'Si cada estrategia se cumple exactamente como se describe, ¿al final de qué mes el número de seguidores con la estrategia 2 supera por primera vez al de la estrategia 1?', NULL,
  NULL, 3, 'Formulación y ejecución', 'La estrategia 1 es **lineal** (suma 1.500 cada mes): S₁ = 1.600 + 1.500·n. La estrategia 2 es **exponencial** (multiplica por 1,5 cada mes): S₂ = 1.600 · 1,5ⁿ.
Mes a mes (estrategia 1 frente a estrategia 2):
• Mes 1: 3.100 frente a 2.400
• Mes 2: 4.600 frente a 3.600
• Mes 3: 6.100 frente a 5.400
• Mes 4: 7.600 frente a **8.100**
La estrategia 2 supera a la 1 por primera vez al final del **cuarto mes**. Aunque empieza más despacio, sus aumentos crecen cada mes, y a largo plazo un crecimiento exponencial siempre supera a uno lineal.', 180,
  ARRAY['crecimiento exponencial', 'crecimiento lineal', 'tasa de cambio']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-02'), 'A', 'Al final del segundo mes', false, 'Resulta de calcular la estrategia 2 como 1.600 × 1,5 × n (4.800 en el mes 2). Pero el 50 % se aplica sobre el valor del mes anterior, así que el factor 1,5 se multiplica una vez por cada mes: en el mes 2 hay 1.600 × 1,5² = 3.600 seguidores, menos que 4.600.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-02'), 'B', 'Al final del tercer mes', false, 'En el tercer mes el aumento de la estrategia 2 (1.800 seguidores) supera por primera vez al de la estrategia 1 (1.500), pero el total todavía es menor: 5.400 frente a 6.100. Que la tasa de cambio sea mayor no significa que el valor ya lo sea.'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-02'), 'C', 'Al final del cuarto mes', true, 'Correcto: en el mes 4 la estrategia 2 llega a 1.600 × 1,5⁴ = 8.100 seguidores y la estrategia 1 a 1.600 + 4 × 1.500 = 7.600. En el mes 3 todavía iba perdiendo (5.400 frente a 6.100).'),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-CAL-02'), 'D', 'Nunca, porque la estrategia 2 solo agrega 800 seguidores cada mes', false, 'Calcula el 50 % siempre sobre los 1.600 seguidores iniciales. En la estrategia 2 el porcentaje se aplica sobre la cantidad acumulada, así que los aumentos crecen cada mes: 800, 1.200, 1.800, 2.700…')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;

-- ---------------------------------------------------------------- sociales-ciudadanas.json
-- SOC-HIS-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-HIS-01-CTX', NULL, 'Entre 1958 y 1974 funcionó en Colombia el Frente Nacional, un acuerdo entre los partidos Liberal y Conservador pactado como respuesta al periodo conocido como La Violencia y al gobierno militar del general Gustavo Rojas Pinilla. Según el acuerdo, la Presidencia de la República se alternaba cada cuatro años entre los dos partidos y los cargos públicos se repartían por partes iguales entre ellos.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-HIS-01', (SELECT id FROM subtemas WHERE slug = 'historia'), (SELECT id FROM contextos WHERE codigo = 'SOC-HIS-01-CTX'), 'Una historiadora afirma que el Frente Nacional “fue una solución que trajo nuevos problemas”. ¿Cuál de las siguientes afirmaciones sustenta mejor esta idea?', NULL,
  NULL, 1, 'Pensamiento reflexivo y sistémico', 'El Frente Nacional (1958-1974) fue la salida que encontraron los dos partidos tradicionales para terminar la violencia bipartidista y el gobierno militar: se turnaron la Presidencia y se repartieron por mitades los cargos públicos.
**La solución:** disminuyó notablemente la confrontación armada entre liberales y conservadores.
**Los nuevos problemas:** el sistema quedó cerrado para otras fuerzas políticas. Muchos historiadores señalan esa exclusión como uno de los factores que contribuyeron al surgimiento de guerrillas en los años sesenta (FARC, ELN, EPL) y, más tarde, del M-19, que tomó su nombre de las cuestionadas elecciones del 19 de abril de 1970.
Por eso la opción B es la única que muestra a la vez el logro y su consecuencia negativa. Las opciones C y D contienen errores históricos, y la A dice lo contrario de lo que ocurrió.', 90,
  ARRAY['frente nacional', 'siglo xx', 'bipartidismo', 'exclusión política']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-01'), 'A', 'Amplió la participación política, porque permitió que nuevos partidos compitieran por la Presidencia en igualdad de condiciones.', false, 'Ocurrió lo contrario: el acuerdo reservó la Presidencia y los cargos públicos a liberales y conservadores, de modo que otros movimientos no podían competir en igualdad de condiciones.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-01'), 'B', 'Redujo la violencia entre liberales y conservadores, pero dejó por fuera del poder a las fuerzas políticas distintas de esos dos partidos.', true, 'Correcta. Recoge las dos caras de la frase: la “solución” (el fin de la confrontación bipartidista) y los “nuevos problemas” (la exclusión de otras fuerzas políticas, que alimentó el descontento).'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-01'), 'C', 'Estableció la elección popular de alcaldes, lo que debilitó el control de los partidos tradicionales sobre las regiones.', false, 'Es un anacronismo: la elección popular de alcaldes se aprobó en 1986 y las primeras elecciones se hicieron en 1988, más de una década después del Frente Nacional.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-01'), 'D', 'Puso fin al conflicto armado, pero causó una crisis económica por la desmovilización de las guerrillas.', false, 'Es falsa: durante el Frente Nacional surgieron guerrillas como las FARC, el ELN y el EPL; el conflicto armado no terminó en ese periodo.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-HIS-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-HIS-02-CTX', NULL, 'Testimonios ficticios, elaborados con fines educativos, de personas que vivieron el proceso que llevó a la Asamblea Nacional Constituyente de 1991:
• Estudiante universitaria (1990): “La violencia y la corrupción nos mostraron que las instituciones no escuchaban a la gente. Votar la ‘séptima papeleta’ fue decir que los ciudadanos también podemos proponer un nuevo pacto.”
• Líder indígena del Cauca: “Queremos que la nueva Constitución reconozca que Colombia es un país con muchos pueblos, culturas y lenguas, y que nosotros tengamos voz en esa decisión.”
• Excombatiente de una guerrilla desmovilizada: “Dejamos las armas porque creemos que los cambios se pueden lograr por la vía política. La Asamblea es la prueba de que ese camino existe.”
• Congresista de un partido tradicional: “Comparto que el país necesita reformas, pero la Constitución vigente dice que su reforma le corresponde al Congreso. Me preocupa que una Asamblea sin límites claros genere inseguridad jurídica.”', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-HIS-02', (SELECT id FROM subtemas WHERE slug = 'historia'), (SELECT id FROM contextos WHERE codigo = 'SOC-HIS-02-CTX'), 'Al comparar los cuatro testimonios, es correcto afirmar que', NULL,
  NULL, 2, 'Interpretación y análisis de perspectivas', 'Para analizar perspectivas, identifica en cada testimonio **quién habla, qué propone y qué le preocupa**.
1. La estudiante ve la Asamblea como una forma de que los ciudadanos propongan un nuevo pacto.
2. La líder indígena busca el reconocimiento de la diversidad y tener voz en la decisión.
3. El excombatiente la ve como prueba de que la vía política es posible.
4. El congresista acepta la necesidad de reformas, pero su preocupación es jurídica: la Constitución de 1886 reservaba al Congreso la facultad de reformarla.
Ese debate fue real: la convocatoria se hizo por vías excepcionales (la ‘séptima papeleta’ y la votación de mayo de 1990) y la Corte Suprema de Justicia la avaló en 1990. La Asamblea, elegida en diciembre de ese año, expidió la Constitución el 4 de julio de 1991.', 150,
  ARRAY['constitución de 1991', 'séptima papeleta', 'asamblea nacional constituyente', 'perspectivas']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-02'), 'A', 'el congresista se opone a cualquier cambio y defiende que la Constitución de 1886 siga igual.', false, 'El congresista dice explícitamente que “el país necesita reformas”; su reparo es sobre el procedimiento, no sobre la necesidad de cambios.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-02'), 'B', 'la estudiante y el excombatiente coinciden en que la reforma debía hacerla únicamente el Congreso.', false, 'Ninguno de los dos lo plantea: ambos valoran la Asamblea como un camino abierto a la participación ciudadana y política. La idea de que la reforma le corresponde al Congreso aparece en el testimonio del congresista.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-02'), 'C', 'la líder indígena rechaza la Asamblea porque cree que no reconocerá la diversidad cultural.', false, 'Confunde su postura: la líder espera que la nueva Constitución sí reconozca la diversidad y quiere participar en su redacción.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-HIS-02'), 'D', 'tres de los actores ven en la Asamblea un canal de participación, y el congresista cuestiona el procedimiento, no la necesidad de reformas.', true, 'Correcta. La estudiante, la líder indígena y el excombatiente ven la Asamblea como una oportunidad de ser escuchados; el congresista acepta que se necesitan reformas, pero duda del mecanismo.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-GEO-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-GEO-01-CTX', NULL, 'Mariana vive en un municipio ubicado a orillas del río Magdalena, a unos 300 m sobre el nivel del mar, donde la temperatura media es de 28 °C y abundan los cultivos de cacao y mango. En vacaciones visita la finca de su abuelo, en una ladera de la cordillera cercana, a 2.700 m de altitud. Allí la temperatura media es de 13 °C y se cultivan papa y haba.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-GEO-01', (SELECT id FROM subtemas WHERE slug = 'geografia'), (SELECT id FROM contextos WHERE codigo = 'SOC-GEO-01-CTX'), '¿Qué explica principalmente la diferencia entre los cultivos de los dos lugares?', NULL,
  NULL, 1, 'Pensamiento social', 'En Colombia, por estar en la zona intertropical, la temperatura depende sobre todo de la **altitud**: en promedio desciende unos 6 °C por cada 1.000 m de ascenso (0,6 °C por cada 100 m).
Entre los dos lugares hay 2.400 m de diferencia (2.700 − 300), lo que equivale a unos 14 o 15 °C menos; por eso se pasa de 28 °C a 13 °C.
Esa diferencia ubica al municipio de Mariana en el **piso térmico cálido** (menos de 1.000 m, más de 24 °C) y a la finca del abuelo en el **piso frío** (2.000 a 3.000 m, entre 12 y 18 °C).
Cada piso favorece cultivos distintos: cacao, mango y plátano en el cálido; café en el templado; papa, haba y hortalizas en el frío. Es un ejemplo de la relación entre sociedad y territorio: las condiciones naturales influyen en las actividades económicas de las comunidades.', 75,
  ARRAY['pisos térmicos', 'altitud', 'clima', 'sociedad y territorio']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-01'), 'A', 'La finca del abuelo está lejos del río, y sin riego es imposible cultivar cacao o mango.', false, 'El caso no habla de riego ni de la distancia al río; la información clave es la diferencia de altitud (300 m frente a 2.700 m) y de temperatura (28 °C frente a 13 °C).'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-01'), 'B', 'A mayor altitud aumenta la temperatura, y la papa necesita más calor que el cacao.', false, 'Es el error inverso: al ascender, la temperatura disminuye, como lo muestran los datos (28 °C abajo y 13 °C arriba). La papa se adapta al clima frío.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-01'), 'C', 'Al ascender disminuye la temperatura, y cada piso térmico favorece cultivos distintos.', true, 'Correcta. El municipio de Mariana está en el piso térmico cálido (cacao, mango) y la finca, en el frío (papa, haba). La altitud determina la temperatura, y esta, los cultivos posibles.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-01'), 'D', 'La papa y la haba solo se cultivan en tierras planas, como las de los valles de los ríos.', false, 'Es falso: en Colombia la papa y la haba se cultivan sobre todo en laderas y altiplanos de clima frío, como los de Boyacá, Cundinamarca y Nariño.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-GEO-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-GEO-02-CTX', NULL, 'Santa Rosa es un municipio andino ficticio cuyo acueducto se abastece de las quebradas que nacen en un páramo cercano. En los últimos años, varias familias campesinas que viven en el páramo han ampliado los cultivos de papa y los potreros para ganado, y una empresa solicitó permiso para extraer oro en la zona. La empresa de acueducto advierte que el caudal de las quebradas ha disminuido, mientras que las familias campesinas explican que la agricultura es su principal fuente de ingresos.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-GEO-02', (SELECT id FROM subtemas WHERE slug = 'geografia'), (SELECT id FROM contextos WHERE codigo = 'SOC-GEO-02-CTX'), '¿Cuál de las siguientes propuestas atiende de manera más completa las dimensiones ambiental, económica y social de este problema?', NULL,
  NULL, 2, 'Pensamiento reflexivo y sistémico', 'Los páramos funcionan como **esponjas**: su vegetación (frailejones, musgos, pajonales) y sus suelos captan el agua de la lluvia y la neblina y la liberan poco a poco hacia las quebradas. Colombia tiene una de las mayores extensiones de páramo del mundo, y muchas ciudades dependen de ellos para su abastecimiento de agua.
Un problema socioambiental tiene varias dimensiones: **ambiental** (proteger el ecosistema), **económica** (ingresos de las familias y del municipio) y **social** (derechos y bienestar de la comunidad).
Una buena solución no sacrifica por completo una dimensión por otra. La opción A protege el agua y, al mismo tiempo, busca alternativas para las familias; B, C y D atienden una sola dimensión o solo un síntoma. En Colombia, la ley de páramos (Ley 1930 de 2018) prohíbe la minería en estos ecosistemas y prevé la reconversión gradual de las actividades agropecuarias con acompañamiento a sus habitantes.', 120,
  ARRAY['páramos', 'agua', 'conflictos ambientales', 'dimensiones de un problema']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-02'), 'A', 'Delimitar el páramo, no permitir allí la minería y acordar con las familias un plan gradual de reconversión productiva con apoyo técnico y económico.', true, 'Correcta. Protege el ecosistema que regula el agua (dimensión ambiental), ofrece alternativas de ingreso (dimensión económica) y reconoce a las familias como parte de la solución (dimensión social).'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-02'), 'B', 'Autorizar la mina y la ampliación de los cultivos, porque generan empleo e ingresos para el municipio en el corto plazo.', false, 'Solo considera la dimensión económica inmediata e ignora que el deterioro del páramo afectaría el agua de todo el municipio. Además, la ley colombiana prohíbe la minería en los páramos.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-02'), 'C', 'Desalojar de inmediato a las familias campesinas, sin compensación, para que el ecosistema se recupere lo más rápido posible.', false, 'Atiende solo la dimensión ambiental y desconoce los derechos y el sustento de las familias; además, generaría un nuevo conflicto social.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-GEO-02'), 'D', 'Construir un tanque de almacenamiento más grande en el casco urbano, sin intervenir lo que ocurre en el páramo.', false, 'Ataca un síntoma (la falta de agua almacenada), pero no la causa: si el páramo se sigue deteriorando, el agua que llega a las quebradas seguirá disminuyendo.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-ECO-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-ECO-01-CTX', NULL, 'El Gobierno nacional estudia eliminar el arancel (impuesto que se cobra a los productos importados) que hoy pagan las importaciones de arroz. Una asociación de consumidores apoya la medida, porque las familias de menores ingresos destinan una parte importante de su presupuesto a los alimentos. En cambio, los productores de arroz del Tolima y del Casanare se oponen a ella.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-ECO-01', (SELECT id FROM subtemas WHERE slug = 'economia'), (SELECT id FROM contextos WHERE codigo = 'SOC-ECO-01-CTX'), '¿Qué interés explica mejor la oposición de los productores de arroz?', NULL,
  NULL, 2, 'Interpretación y análisis de perspectivas', 'Un **arancel** encarece los productos importados y así protege a los productores nacionales de la competencia externa.
Si se elimina, el arroz importado llega más barato: aumenta la **oferta** en el mercado y, con una demanda similar, el **precio** tiende a bajar.
• Los **consumidores** ganan: pagan menos por un alimento básico (por eso apoyan la medida).
• Los **productores nacionales** pierden: deben vender más barato o pierden compradores (por eso se oponen).
Analizar perspectivas consiste en identificar qué gana o qué pierde cada actor con una decisión. Este tipo de debate acompaña a la globalización y a la apertura económica que Colombia inició a comienzos de los años noventa.', 120,
  ARRAY['oferta y demanda', 'aranceles', 'globalización', 'actores e intereses']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-01'), 'A', 'Evitar que el precio del arroz suba y que las familias compren menos, lo que reduciría sus ventas.', false, 'Confunde el efecto de la medida: sin arancel, el arroz importado entra más barato, así que la presión es a que el precio baje, no a que suba.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-01'), 'B', 'Proteger a las familias de menores ingresos, que gastan buena parte de su dinero en alimentos.', false, 'Ese es el argumento de la asociación de consumidores, no el de los productores. Confundir las perspectivas de los actores es un error frecuente.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-01'), 'C', 'Evitar que el arroz importado, al entrar más barato, aumente la oferta, haga bajar el precio y reduzca sus ingresos.', true, 'Correcta. Sin arancel, el arroz importado compite con ventaja; la mayor oferta presiona el precio a la baja y los productores nacionales venderían menos o a menor precio.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-01'), 'D', 'Evitar que el nuevo impuesto se cobre a los productores nacionales por cada tonelada que vendan.', false, 'Confunde qué es un arancel: es un impuesto a los productos importados, no a los nacionales. Además, la medida propone eliminarlo, no crearlo.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-ECO-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-ECO-02-CTX', NULL, 'La gráfica presenta datos ficticios de un país hipotético: el aumento porcentual del salario mínimo decretado para cada año y la inflación registrada durante ese mismo año.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-ECO-02', (SELECT id FROM subtemas WHERE slug = 'economia'), (SELECT id FROM contextos WHERE codigo = 'SOC-ECO-02-CTX'), 'Un candidato afirma: “Como el salario mínimo subió todos los años, el poder de compra de quienes lo ganan mejoró en cada uno de esos años”. Con base en la gráfica, ¿cuál es la evaluación correcta de esta afirmación?', '/img/preguntas/SOC-ECO-02.svg',
  'Gráfica de barras agrupadas por año. 2021: aumento del salario mínimo 4 %, inflación 3 %. 2022: aumento del salario mínimo 10 %, inflación 13 %. 2023: aumento del salario mínimo 16 %, inflación 9 %. 2024: aumento del salario mínimo 12 %, inflación 6 %.', 3, 'Pensamiento reflexivo y sistémico', 'La clave es distinguir el **salario nominal** (los pesos que se reciben) del **salario real** (los bienes y servicios que se pueden comprar con ellos).
Una forma aproximada de estimar el cambio del salario real es: aumento del salario − inflación.
• 2021: 4 % − 3 % ≈ +1 % (gana poder de compra)
• 2022: 10 % − 13 % ≈ −3 % (pierde poder de compra)
• 2023: 16 % − 9 % ≈ +7 % (gana)
• 2024: 12 % − 6 % ≈ +6 % (gana)
El cálculo exacto para 2022 es 1,10 ÷ 1,13 ≈ 0,973, es decir, una pérdida cercana al 2,7 %. Como ese año el salario perdió poder de compra, la afirmación del candidato es falsa. Evaluar afirmaciones con evidencia, y no aceptarlas por quién las dice, es una habilidad clave del pensamiento reflexivo.', 180,
  ARRAY['inflación', 'salario real', 'lectura de gráficas', 'evaluación de argumentos']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-02'), 'A', 'Es correcta, porque un aumento del salario nominal siempre se traduce en mayor poder de compra.', false, 'Confunde el salario nominal (la cantidad de pesos) con el salario real (lo que se puede comprar con ellos). Si los precios suben más que el salario, el poder de compra cae aunque el salario aumente.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-02'), 'B', 'Es incorrecta, porque en 2022 la inflación (13 %) superó el aumento del salario (10 %), así que ese año el salario alcanzó para comprar menos.', true, 'Correcta. En 2022 los precios subieron más que el salario, de modo que el salario real disminuyó (cerca de 2,7 %). Basta un año en esa situación para refutar la afirmación.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-02'), 'C', 'Es incorrecta, porque en 2023 se registró la inflación más alta del periodo y ese año el salario perdió poder de compra.', false, 'Error de lectura de la gráfica: la inflación más alta fue la de 2022 (13 %). En 2023 el salario subió 16 % y la inflación fue de 9 %, así que el poder de compra aumentó.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-ECO-02'), 'D', 'Es correcta, porque en todos los años el aumento del salario fue mayor que la inflación.', false, 'Error de lectura: en 2022 la barra de la inflación (13 %) es más alta que la del aumento del salario (10 %).')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-POL-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-POL-01-CTX', NULL, 'En el municipio ficticio de El Porvenir, la alcaldía pagó la totalidad de un contrato para construir un puente peatonal, pero la obra quedó abandonada a mitad de camino. Una veeduría ciudadana, es decir, un grupo de ciudadanos organizado para vigilar la gestión pública, denunció el caso y pidió que se establezca si hubo un daño a los recursos públicos y que se recupere el dinero perdido.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-POL-01', (SELECT id FROM subtemas WHERE slug = 'politica'), (SELECT id FROM contextos WHERE codigo = 'SOC-POL-01-CTX'), '¿Qué entidad es la competente para adelantar el proceso que determine si hubo un daño al patrimonio público y quién debe responder económicamente por él?', NULL,
  NULL, 2, 'Pensamiento social', 'Un mismo hecho puede dar lugar a **tres investigaciones distintas** que avanzan en paralelo:
• **Fiscal** (Contraloría): ¿se perdieron recursos públicos?, ¿quién debe responder por ellos?
• **Disciplinaria** (Procuraduría o personería): ¿el servidor público incumplió sus deberes?
• **Penal** (Fiscalía General de la Nación, que pertenece a la rama judicial): ¿se cometió un delito?
La pregunta pide establecer el daño al patrimonio y quién responde económicamente: eso es **control fiscal**. Según el origen de los recursos, lo ejerce la contraloría territorial (departamental o municipal) o la Contraloría General de la República. La Contraloría y el Ministerio Público (Procuraduría, Defensoría del Pueblo y personerías) son los órganos de control del Estado.', 120,
  ARRAY['órganos de control', 'contraloría', 'procuraduría', 'veedurías ciudadanas']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-POL-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-01'), 'A', 'La Contraloría, porque ejerce el control fiscal sobre el manejo de los recursos públicos.', true, 'Correcta. El control fiscal consiste en vigilar cómo se gestionan los recursos públicos; mediante un proceso de responsabilidad fiscal, la Contraloría determina quién causó el daño y le exige resarcirlo.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-01'), 'B', 'La Defensoría del Pueblo, porque vela por la promoción y la protección de los derechos humanos.', false, 'La Defensoría hace parte del Ministerio Público, pero su función es promover y proteger los derechos humanos, no investigar el manejo del dinero público.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-01'), 'C', 'La Procuraduría, porque vigila la conducta de los servidores públicos y adelanta investigaciones disciplinarias.', false, 'Es el distractor más cercano: la Procuraduría sí podría abrir una investigación disciplinaria por el incumplimiento de deberes. Pero determinar el daño patrimonial y su resarcimiento es control fiscal, tarea de la Contraloría.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-01'), 'D', 'El Concejo municipal, porque es el órgano de la rama judicial encargado de juzgar al alcalde.', false, 'El concejo es una corporación administrativa de elección popular que ejerce control político sobre la administración municipal; no pertenece a la rama judicial ni adelanta procesos de responsabilidad fiscal.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-POL-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-POL-02-CTX', NULL, 'En un foro sobre descentralización se escucharon estas intervenciones (testimonios ficticios):
• Gobernadora: “Los departamentos y municipios conocen mejor las necesidades de su gente. Deberían recibir más recursos y decidir con mayor autonomía en qué invertirlos.”
• Funcionario del Gobierno nacional: “Muchos municipios pequeños tienen poco personal técnico y recaudan muy pocos impuestos propios. Si se les transfieren más recursos sin fortalecer esas capacidades, aumenta el riesgo de que se malgasten.”
• Líder comunitaria de una vereda: “Las decisiones sobre nuestras vías y escuelas se toman muy lejos de aquí. Con más autonomía local, la comunidad podría participar directamente en la definición del presupuesto.”', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-POL-02', (SELECT id FROM subtemas WHERE slug = 'politica'), (SELECT id FROM contextos WHERE codigo = 'SOC-POL-02-CTX'), '¿Cuál de las siguientes propuestas recoge a la vez la preocupación del funcionario nacional y las aspiraciones de la gobernadora y de la líder comunitaria?', NULL,
  NULL, 3, 'Interpretación y análisis de perspectivas', 'La **descentralización** consiste en trasladar poder de decisión, funciones y recursos del nivel nacional a departamentos y municipios. En Colombia avanzó con la elección popular de alcaldes (desde 1988) y de gobernadores (desde 1991), y con las transferencias de la Nación a los territorios.
Para resolver una pregunta de perspectivas de nivel alto, primero identifica el interés de cada actor:
• Gobernadora: más recursos y **autonomía**.
• Funcionario: evitar el **malgasto** por falta de capacidad técnica.
• Líder comunitaria: **participación** directa de la comunidad.
Luego busca la propuesta que no sacrifique a ningún actor. Solo la D combina autonomía, fortalecimiento técnico, control y participación; A, B y C responden a un solo actor o deforman lo que dijo.', 180,
  ARRAY['descentralización', 'autonomía territorial', 'participación ciudadana', 'perspectivas']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-POL-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-02'), 'A', 'Centralizar en el Gobierno nacional la ejecución de las vías y escuelas, para evitar que los recursos se pierdan en los municipios.', false, 'Responde solo a la preocupación del funcionario y va en contra de la autonomía territorial que piden la gobernadora y la líder comunitaria.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-02'), 'B', 'Aumentar las transferencias a los municipios sin ninguna condición, pues la autonomía territorial impide cualquier tipo de control.', false, 'Recoge solo la aspiración de la gobernadora e ignora el riesgo señalado por el funcionario. Además, es falso que la autonomía impida el control: las entidades territoriales están sujetas a los órganos de control y a la vigilancia ciudadana.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-02'), 'C', 'Reemplazar al concejo municipal por asambleas veredales que decidan todo el presupuesto sin intervención de las autoridades elegidas.', false, 'Exagera la postura de la líder: ella pide participar, no reemplazar a las autoridades elegidas. Además, no responde a la preocupación del funcionario por la capacidad técnica.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-POL-02'), 'D', 'Transferir más recursos y competencias, acompañados de asistencia técnica a los municipios y de presupuestos participativos con veeduría ciudadana.', true, 'Correcta. Amplía la autonomía (gobernadora), fortalece capacidades y control para reducir el riesgo de malgasto (funcionario) y abre espacios de participación directa (líder comunitaria).')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-CIU-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-CIU-01-CTX', NULL, 'En el municipio ficticio de La Esperanza, la alcaldesa fue elegida con un programa de gobierno que prometía construir un acueducto veredal y un puesto de salud. Después de un año y medio de gobierno, un grupo de ciudadanos considera que ella no ha cumplido ese programa y quiere que deje el cargo antes de que termine su periodo.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-CIU-01', (SELECT id FROM subtemas WHERE slug = 'ciudadania'), (SELECT id FROM contextos WHERE codigo = 'SOC-CIU-01-CTX'), '¿Qué mecanismo de participación ciudadana, reconocido en la Constitución de 1991, permite a los ciudadanos lograr este propósito?', NULL,
  NULL, 1, 'Pensamiento social', 'La Constitución de 1991 creó una **democracia participativa**: además de votar, los ciudadanos pueden intervenir directamente en las decisiones públicas. El artículo 103 enumera los mecanismos de participación: el voto, el plebiscito, el referendo, la consulta popular, el cabildo abierto, la iniciativa legislativa y la revocatoria del mandato.
La **revocatoria del mandato** permite terminar anticipadamente el periodo de un alcalde o de un gobernador. Se relaciona con el **voto programático**: quien elige a un alcalde o gobernador le impone como mandato el programa que presentó al inscribirse como candidato.
La ley fija requisitos para usarla, como recoger un número mínimo de firmas, que haya pasado un tiempo mínimo desde la posesión y que la ciudadanía la apruebe en una votación.
La tutela (B) es un mecanismo de protección, no de participación; el cabildo abierto (A) y el plebiscito (D) tienen otros fines.', 75,
  ARRAY['mecanismos de participación', 'revocatoria del mandato', 'voto programático', 'constitución de 1991']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-01'), 'A', 'El cabildo abierto, porque en él los ciudadanos votan para destituir a los funcionarios municipales.', false, 'El cabildo abierto es una sesión pública de una corporación, como el concejo o la junta administradora local, en la que los habitantes discuten asuntos de interés comunitario; no sirve para destituir a nadie.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-01'), 'B', 'La acción de tutela, porque protege a la comunidad cuando un gobernante incumple sus promesas de campaña.', false, 'La tutela es un mecanismo judicial para proteger derechos fundamentales; no es un mecanismo de participación ni sirve para terminar el mandato de un gobernante.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-01'), 'C', 'La revocatoria del mandato, porque permite a los ciudadanos dar por terminado el mandato de un alcalde o de un gobernador.', true, 'Correcta. Es el mecanismo con el que los ciudadanos pueden terminar anticipadamente el mandato de alcaldes y gobernadores, por ejemplo, por incumplir el programa con el que fueron elegidos.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-01'), 'D', 'El plebiscito, porque permite a los habitantes de un municipio elegir un nuevo alcalde en cualquier momento.', false, 'El plebiscito lo convoca el presidente de la República para que el pueblo apoye o rechace una decisión del Ejecutivo; no sirve para cambiar alcaldes.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- SOC-CIU-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-CIU-02-CTX', NULL, 'Analiza las siguientes situaciones (casos ficticios):
1. Hace dos meses, Luz Marina radicó una petición escrita en la Secretaría de Educación municipal para conocer los cupos escolares disponibles para su hija. Hasta hoy no ha recibido ninguna respuesta.
2. Un joven fue capturado sin orden judicial y sin haber sido sorprendido cometiendo un delito. Han pasado más de 36 horas y no ha sido puesto a disposición de un juez.
3. Los habitantes de un barrio quieren que un juez ordene detener los vertimientos tóxicos que una fábrica hace en la quebrada que atraviesa el sector y que afectan a toda la comunidad.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('SOC-CIU-02', (SELECT id FROM subtemas WHERE slug = 'ciudadania'), (SELECT id FROM contextos WHERE codigo = 'SOC-CIU-02-CTX'), '¿Cuál es el mecanismo judicial más adecuado para cada situación?', NULL,
  NULL, 3, 'Pensamiento social', 'Para elegir el mecanismo, sigue tres pasos: **1)** ¿qué derecho se vulnera?, **2)** ¿es individual o colectivo?, **3)** ¿existe un mecanismo específico para ese caso?
• Situación 1: la petición es un derecho fundamental (art. 23) y la ley fija plazos breves para responder (la regla general es de 15 días hábiles). Como la petición ya se presentó y no fue respondida, procede la **acción de tutela** (art. 86) para que un juez ordene responder.
• Situación 2: toda persona detenida debe ser puesta a disposición de un juez dentro de las 36 horas siguientes. Ante una privación ilegal de la libertad procede el **hábeas corpus** (art. 30), que debe resolverse en un término de 36 horas.
• Situación 3: el ambiente sano es un derecho colectivo; se protege con la **acción popular** (art. 88).
La acción de cumplimiento (art. 87) sirve para exigir que una autoridad cumpla una ley o un acto administrativo, lo que no corresponde a ninguno de los tres casos.', 180,
  ARRAY['mecanismos de protección', 'acción de tutela', 'hábeas corpus', 'acción popular']::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-02');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-02'), 'A', '1: acción de tutela; 2: hábeas corpus; 3: acción popular.', true, 'Correcta. En la situación 1 se vulneró el derecho fundamental de petición (no hubo respuesta), que se protege con tutela; en la 2 hay una privación ilegal de la libertad (hábeas corpus); en la 3 se afecta un derecho colectivo, el ambiente sano (acción popular).'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-02'), 'B', '1: derecho de petición; 2: acción de tutela; 3: acción de cumplimiento.', false, 'Luz Marina ya ejerció el derecho de petición, que además no es una acción judicial. Para la detención ilegal existe un mecanismo específico y más rápido, el hábeas corpus, y la acción de cumplimiento sirve para exigir que se cumpla una ley o un acto administrativo, no para proteger derechos colectivos.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-02'), 'C', '1: acción de cumplimiento; 2: hábeas corpus; 3: acción de tutela.', false, 'Acierta solo en la situación 2. En la 1 lo vulnerado es un derecho fundamental, que se protege con tutela, y en la 3 el derecho afectado es colectivo, por lo que corresponde la acción popular.'),
  ((SELECT id FROM preguntas WHERE codigo = 'SOC-CIU-02'), 'D', '1: derecho de petición; 2: hábeas corpus; 3: acción popular.', false, 'Es la opción más tentadora, pero falla en la situación 1: la petición ya se presentó y no fue respondida, así que lo que procede es acudir a un juez mediante tutela. El derecho de petición no es una acción judicial: se ejerce directamente ante las autoridades.')
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;

-- ---------------------------------------------------------------- lecciones/ciencias-naturales.json
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'biologia'), 'CIE-BIO-L1', 'Genética mendeliana: descifra la herencia', 'Aprenderás a usar el cuadro de Punnett para predecir cómo se heredan los rasgos dominantes y recesivos.', '[{"tipo":"texto","contenido":"¿Te has preguntado por qué a veces aparece en un hijo un rasgo que no se ve en ninguno de sus padres? Hace más de 150 años, el monje Gregor Mendel lo descubrió cruzando plantas de arveja y contando con paciencia a sus descendientes. Hoy vas a usar sus mismas herramientas para **predecir** la herencia como lo hace un genetista."},{"tipo":"concepto","titulo":"Gen, alelo, genotipo y fenotipo","contenido":"Un **gen** es un fragmento de ADN que determina una característica, como el color de la flor. Cada gen tiene versiones llamadas **alelos**, y cada individuo lleva dos: uno heredado de la madre y otro del padre. El **genotipo** es la combinación de alelos (por ejemplo, Mm) y el **fenotipo** es lo que se observa (por ejemplo, flor morada)."},{"tipo":"concepto","titulo":"Dominante y recesivo","contenido":"El alelo **dominante** (con mayúscula, M) se manifiesta aunque haya una sola copia. El alelo **recesivo** (con minúscula, m) solo se manifiesta cuando hay dos copias (mm). Un individuo con dos alelos iguales es **homocigoto** (MM o mm) y uno con alelos distintos es **heterocigoto** (Mm)."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: el cuadro de Punnett","enunciado":"En la arveja, la flor morada (M) es dominante sobre la flor blanca (m). Se cruzan dos plantas heterocigotas (Mm × Mm) y germinan 200 semillas. ¿Cuántas plantas de flor blanca se esperan?","pasos":["Escribe los gametos de cada padre: cada uno puede aportar M o m.","Arma el cuadro de Punnett combinando los gametos: MM, Mm, mM y mm.","Identifica el fenotipo de cada casilla: solo mm tiene flor blanca, es decir, 1 de 4 casillas (25 %).","Aplica la proporción al total: 200 × 1/4 = 50 plantas."],"respuesta":"Se esperan unas 50 plantas de flor blanca y 150 de flor morada (proporción 3:1)."},{"tipo":"lista","titulo":"Proporciones que conviene reconocer","items":["Mm × Mm → 3 con el rasgo dominante : 1 con el recesivo (75 % y 25 %).","Mm × mm → 1 dominante : 1 recesivo (50 % y 50 %).","MM × mm → 100 % heterocigotos (Mm), todos con el rasgo dominante.","MM × cualquier genotipo → 100 % con el rasgo dominante.","Cruce de prueba: para saber si un individuo dominante es MM o Mm, crúzalo con uno mm; si aparece algún descendiente con el rasgo recesivo, era Mm."]},{"tipo":"lista","titulo":"Errores frecuentes","items":["Creer que dos padres con el rasgo dominante no pueden tener hijos con el rasgo recesivo.","Confundir el genotipo (las letras) con el fenotipo (lo que se observa).","Esperar proporciones exactas en pocas crías: 3:1 es una probabilidad, no una garantía.","Pensar que ''dominante'' significa ''más frecuente'' en la población."]},{"tipo":"tip","contenido":"Tip ICFES: si un descendiente muestra el rasgo recesivo, cada uno de sus padres le aportó un alelo recesivo, aunque ellos muestren el dominante. Usa esa pista para deducir los genotipos ''ocultos'' antes de armar el cuadro de Punnett."},{"tipo":"ejercicio","enunciado":"Se cruza una planta de arveja de flor morada heterocigota (Mm) con una de flor blanca (mm). ¿Qué porcentaje de la descendencia se espera con flor blanca?","opciones":["0 %","25 %","50 %","100 %"],"correcta":2,"explicacion":"Mm × mm produce Mm, Mm, mm y mm: 2 de las 4 casillas son mm, es decir, un 50 % de plantas con flor blanca."},{"tipo":"ejercicio","enunciado":"En los conejos, el pelo corto (L) es dominante sobre el pelo largo (l). Dos conejos de pelo corto tienen una cría de pelo largo. ¿Cuáles son los genotipos de los padres?","opciones":["LL y LL","Ll y Ll","LL y ll","ll y ll"],"correcta":1,"explicacion":"La cría de pelo largo es ll, así que recibió un alelo l de cada padre. Como ambos padres tienen pelo corto, también poseen un alelo L: los dos son Ll."}]'::jsonb,
  10, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'medio-ambiente'), 'CIE-MED-L1', 'El ciclo del carbono y el cambio climático', 'Entenderás cómo circula el carbono entre la atmósfera, los seres vivos y los océanos, y por qué alterar ese ciclo está calentando el planeta.', '[{"tipo":"texto","contenido":"El carbono que hoy forma parte de tu cuerpo pudo estar hace unos años en el aire, en una hoja de un árbol amazónico o en el fondo del mar. Los átomos de la Tierra se **reciclan** una y otra vez en los ciclos biogeoquímicos. Entender el ciclo del carbono te ayudará a explicar uno de los grandes retos de tu generación: el cambio climático."},{"tipo":"concepto","titulo":"¿Qué es el ciclo del carbono?","contenido":"Es el recorrido del carbono entre la atmósfera (como CO₂), los seres vivos, los suelos, los océanos y las rocas. Las plantas y las algas lo **retiran** del aire mediante la fotosíntesis; los seres vivos lo **devuelven** con la respiración y la descomposición. Los seres humanos, además, liberan en poco tiempo el carbono que estuvo guardado durante millones de años en el carbón, el petróleo y el gas."},{"tipo":"formula","contenido":"Fotosíntesis: 6 CO₂ + 6 H₂O + luz → C₆H₁₂O₆ + 6 O₂","nota":"La respiración celular hace el proceso inverso: C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O + energía."},{"tipo":"lista","titulo":"Entradas y salidas de CO₂ en la atmósfera","items":["Fotosíntesis: retira CO₂ del aire y lo convierte en azúcares.","Respiración celular: plantas, animales, hongos y bacterias liberan CO₂.","Descomposición: hongos y bacterias devuelven el carbono de los restos de seres vivos.","Combustión: quemar madera, gasolina, carbón o gas libera CO₂.","Océanos: absorben parte del CO₂ del aire; al absorber más, el agua se vuelve más ácida."]},{"tipo":"concepto","titulo":"Efecto invernadero no es lo mismo que calentamiento global","contenido":"El **efecto invernadero** es natural y necesario: el CO₂, el metano (CH₄) y el vapor de agua retienen parte del calor que emite la superficie terrestre. Sin él, la temperatura media del planeta sería de unos −18 °C en lugar de unos 15 °C. El **calentamiento global** ocurre porque las actividades humanas aumentan la cantidad de esos gases e intensifican el efecto."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: deforestación y CO₂","enunciado":"En la Amazonia colombiana se tala y se quema una hectárea de bosque para sembrar pasto para ganado. ¿Cómo cambia el balance de gases de efecto invernadero en la atmósfera?","pasos":["Al quemar los árboles, el carbono almacenado en su madera se libera como CO₂ (combustión).","Desaparece la fotosíntesis de esos árboles, que cada año retiraba CO₂ del aire.","El pasto almacena mucho menos carbono que el bosque.","Además, el ganado libera metano (CH₄), otro gas de efecto invernadero."],"respuesta":"Aumentan las entradas de gases de efecto invernadero y disminuyen las salidas de CO₂: la deforestación intensifica el cambio climático."},{"tipo":"lista","titulo":"Efectos del cambio climático en Colombia","items":["Retroceso de los glaciares: los nevados colombianos han perdido la mayor parte de su hielo desde el siglo XIX.","Especies de montaña que se desplazan hacia zonas más altas, lo que aumenta la presión sobre los páramos.","Aguaceros más intensos, inundaciones y sequías más fuertes.","Aumento del nivel del mar en las costas del Caribe y del Pacífico."]},{"tipo":"tip","contenido":"Tip ICFES: en las preguntas sobre ciclos, identifica la dirección del flujo. La fotosíntesis **saca** CO₂ de la atmósfera; la respiración, la descomposición y la combustión lo **devuelven**. Muchas opciones incorrectas invierten esa dirección."},{"tipo":"ejercicio","enunciado":"¿Cuál de estos procesos retira CO₂ de la atmósfera?","opciones":["La respiración de los animales","La quema de gasolina en los carros","La descomposición de hojas secas","La fotosíntesis de las plantas y las algas"],"correcta":3,"explicacion":"En la fotosíntesis, las plantas y las algas toman CO₂ del aire y lo convierten en glucosa. La respiración, la combustión y la descomposición liberan CO₂."},{"tipo":"ejercicio","enunciado":"Un compañero afirma: ''El efecto invernadero es dañino y habría que eliminarlo por completo''. ¿Qué respuesta es científicamente correcta?","opciones":["Tiene razón, porque el efecto invernadero es causado solo por la contaminación.","Tiene razón, porque el efecto invernadero destruye la capa de ozono.","No tiene razón, porque sin el efecto invernadero natural la Tierra sería demasiado fría; el problema es su intensificación.","No tiene razón, porque el efecto invernadero enfría el planeta y evita el calentamiento global."],"correcta":2,"explicacion":"El efecto invernadero natural mantiene la temperatura media cerca de 15 °C; sin él sería de unos −18 °C. El problema actual es que las emisiones humanas lo intensifican. Además, el efecto invernadero y el agujero de la capa de ozono son fenómenos distintos."}]'::jsonb,
  10, 30, 5, 1)
