  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'fisica'), 'CIE-FIS-L1', 'Movimiento y fuerzas: de las gráficas a las leyes de Newton', 'Aprenderás a describir movimientos con MRU y MRUA, a leer gráficas velocidad–tiempo y a conectarlas con las leyes de Newton.', '[{"tipo":"texto","contenido":"Cuando el metro de Medellín arranca, sientes que te vas hacia atrás; cuando frena, te vas hacia adelante. La física explica esos movimientos con pocas ideas, pero muy poderosas. Si dominas las ecuaciones del movimiento, las gráficas velocidad–tiempo y las leyes de Newton, tendrás a tu favor muchas preguntas del ICFES."},{"tipo":"concepto","titulo":"MRU y MRUA","contenido":"En el **movimiento rectilíneo uniforme (MRU)** la velocidad es constante: el cuerpo recorre distancias iguales en tiempos iguales y su aceleración es cero. En el **movimiento rectilíneo uniformemente acelerado (MRUA)** la velocidad cambia la misma cantidad en cada segundo, es decir, la aceleración es constante. Un objeto en caída libre, sin resistencia del aire, tiene un MRUA con a = g = 10 m/s²."},{"tipo":"formula","contenido":"MRU: d = v·t   |   MRUA: a = Δv/Δt ;  v = v₀ + a·t ;  d = v₀·t + ½·a·t²","nota":"Usa unidades del SI: d en m, v en m/s, a en m/s² y t en s. Para pasar de km/h a m/s, divide entre 3,6."},{"tipo":"concepto","titulo":"Cómo leer una gráfica velocidad–tiempo","contenido":"La **pendiente** de la gráfica es la aceleración y el **área** bajo la línea es la distancia recorrida. Una línea horizontal indica velocidad constante (no reposo); una línea que sube indica que el cuerpo acelera y una que baja, que frena. El cuerpo está en reposo solo cuando la línea coincide con v = 0."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: distancia a partir de una gráfica","enunciado":"Un ciclista parte del reposo, acelera de manera uniforme hasta 12 m/s en 6 s y luego mantiene esa velocidad durante 10 s. ¿Qué distancia recorre en total?","pasos":["Tramo 1 (MRUA): a = Δv/Δt = (12 m/s − 0) ÷ 6 s = 2 m/s².","Distancia del tramo 1 = área del triángulo = ½ × 6 s × 12 m/s = 36 m. Comprueba con la fórmula: d = ½·a·t² = ½ × 2 × 6² = 36 m.","Tramo 2 (MRU): d = v·t = 12 m/s × 10 s = 120 m.","Suma los dos tramos: 36 m + 120 m = 156 m."],"respuesta":"El ciclista recorre 156 m en total."},{"tipo":"concepto","titulo":"Las tres leyes de Newton","contenido":"**Primera ley (inercia):** si la fuerza neta es cero, un cuerpo sigue en reposo o en MRU. **Segunda ley:** una fuerza neta produce una aceleración en su misma dirección. **Tercera ley:** las fuerzas aparecen en pares de acción y reacción, de igual magnitud y sentido contrario, que actúan sobre cuerpos distintos."},{"tipo":"formula","contenido":"F neta = m · a","nota":"F en newtons (N), m en kilogramos (kg) y a en m/s². Si la velocidad es constante, a = 0 y la fuerza neta es 0 N, aunque el cuerpo se esté moviendo."},{"tipo":"lista","titulo":"Errores frecuentes","items":["Pensar que si algo se mueve, debe haber una fuerza neta en la dirección del movimiento.","Leer una línea horizontal en una gráfica v–t como si el cuerpo estuviera quieto.","Creer que una línea que baja en una gráfica v–t significa que el cuerpo se devuelve.","Olvidar el ½ al calcular el área de un triángulo.","Mezclar km/h con m/s en la misma operación."]},{"tipo":"tip","contenido":"Tip ICFES: frente a una gráfica v–t hazte dos preguntas: ¿qué dice la pendiente? (aceleración) y ¿qué dice el área? (distancia). Y si el enunciado menciona ''velocidad constante'', piensa de inmediato en fuerza neta igual a cero."},{"tipo":"ejercicio","enunciado":"Un carro pasa de 0 a 20 m/s en 5 s con aceleración constante. ¿Cuál es su aceleración?","opciones":["4 m/s²","10 m/s²","100 m/s²","0,25 m/s²"],"correcta":0,"explicacion":"a = Δv/Δt = (20 − 0) m/s ÷ 5 s = 4 m/s². El valor de 100 m/s² sale de multiplicar en vez de dividir, y el de 0,25 m/s², de invertir la división."},{"tipo":"ejercicio","enunciado":"Se deja caer una piedra desde el reposo. Con g = 10 m/s² y sin resistencia del aire, ¿qué velocidad tiene a los 3 s?","opciones":["10 m/s","30 m/s","45 m/s","90 m/s"],"correcta":1,"explicacion":"v = v₀ + g·t = 0 + 10 m/s² × 3 s = 30 m/s. El valor de 45 confunde la velocidad con la distancia recorrida (½·g·t² = 45 m) y el de 90 resulta de calcular g·t²."}]'::jsonb,
  12, 30, 5, 1)
