INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'quimica'), 'CIE-QUI-L1', 'Soluciones: concentración y solubilidad sin misterio', 'Calcularás concentraciones, entenderás qué pasa al diluir una solución y aprenderás a leer curvas de solubilidad.', '[{"tipo":"texto","contenido":"El agua de panela, el suero oral y el agua de mar tienen algo en común: son **soluciones**. Saber cuánto soluto contienen y cuánto más pueden disolver es clave en la cocina, en la medicina y, por supuesto, en el ICFES. ¡Vamos paso a paso!"},{"tipo":"concepto","titulo":"Soluto, solvente y solución","contenido":"Una **solución** es una mezcla homogénea: a simple vista se ve una sola fase. El **soluto** es la sustancia que se disuelve (la panela, la sal) y el **solvente** es la que disuelve, casi siempre el agua. La **concentración** indica cuánto soluto hay en cierta cantidad de solución."},{"tipo":"formula","contenido":"% m/m = (masa de soluto ÷ masa de solución) × 100   |   C (g/L) = masa de soluto (g) ÷ volumen de solución (L)","nota":"Recuerda: masa de solución = masa de soluto + masa de solvente."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: porcentaje en masa","enunciado":"Se disuelven 25 g de azúcar en 225 g de agua. ¿Cuál es el porcentaje en masa (% m/m) de la solución?","pasos":["Calcula la masa de la solución: 25 g + 225 g = 250 g.","Aplica la fórmula: % m/m = (25 g ÷ 250 g) × 100.","Resuelve: 0,1 × 100 = 10 %."],"respuesta":"La solución tiene 10 % m/m de azúcar (no 11,1 %, que sale de dividir entre la masa del agua)."},{"tipo":"formula","contenido":"Dilución: C₁ · V₁ = C₂ · V₂","nota":"Al agregar agua, la cantidad de soluto no cambia; solo aumenta el volumen, por eso la concentración disminuye."},{"tipo":"concepto","titulo":"Solubilidad y curvas de solubilidad","contenido":"La **solubilidad** es la máxima cantidad de soluto que se disuelve en una cantidad de solvente (por lo general, 100 g de agua) a una temperatura dada. Si hay menos soluto que ese máximo, la solución es **insaturada**; si tiene justo el máximo, es **saturada**; y si por un enfriamiento cuidadoso queda con más del máximo, es **sobresaturada** e inestable. En la mayoría de los sólidos la solubilidad aumenta con la temperatura, mientras que en los gases disminuye: por eso una gaseosa caliente pierde el gas más rápido."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: ¿cuánto se disuelve?","enunciado":"La solubilidad de la sal de cocina (NaCl) es de unos 36 g por cada 100 g de agua a 20 °C. Si se agregan 50 g de sal a 100 g de agua a esa temperatura, ¿qué ocurre?","pasos":["Compara lo agregado con la solubilidad: 50 g es más que el máximo de 36 g.","Se disuelven 36 g y la solución queda saturada.","El resto, 50 g − 36 g = 14 g, queda sin disolver en el fondo."],"respuesta":"Se forma una solución saturada y quedan 14 g de sal sin disolver."},{"tipo":"lista","titulo":"Errores frecuentes","items":["Dividir entre la masa del solvente en lugar de la masa de la solución.","Pensar que al diluir se pierde soluto.","Creer que todos los solutos se disuelven más con el calor: los gases hacen lo contrario.","Olvidar ajustar la solubilidad cuando no hay exactamente 100 g de agua."]},{"tipo":"tip","contenido":"Tip ICFES: en una curva de solubilidad, un punto sobre la curva representa una solución saturada y uno por debajo, una insaturada. Si el problema no usa 100 g de agua, ajusta con una regla de tres: con la mitad del agua se disuelve la mitad del soluto."},{"tipo":"ejercicio","enunciado":"Un jugo concentrado tiene 200 g/L de azúcar. Se toman 250 mL y se completa con agua hasta 1 L. ¿Cuál es la concentración del jugo preparado?","opciones":["800 g/L","50 g/L","200 g/L","66,7 g/L"],"correcta":1,"explicacion":"C₁·V₁ = C₂·V₂ → 200 g/L × 0,25 L = C₂ × 1 L → C₂ = 50 g/L. Los 50 g de azúcar no cambian; solo se reparten en más volumen. El valor de 66,7 g/L sale de usar los 750 mL de agua agregada en lugar del volumen final de 1 L."},{"tipo":"ejercicio","enunciado":"La solubilidad del NaCl es de unos 36 g por cada 100 g de agua a 20 °C. ¿Cuál es la máxima cantidad de NaCl que se disuelve en 50 g de agua a esa temperatura?","opciones":["72 g","36 g","18 g","14 g"],"correcta":2,"explicacion":"Con la mitad del agua se disuelve la mitad del soluto: 36 g × 50/100 = 18 g. El valor de 72 g resulta de duplicar en lugar de dividir, y el de 36 g, de olvidar ajustar la cantidad de agua."}]'::jsonb,
  12, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'metodo-cientifico'), 'CIE-MET-L1', 'Piensa como científico: variables, hipótesis y conclusiones', 'Aprenderás a identificar variables, formular hipótesis, diseñar experimentos justos y sacar conclusiones válidas.', '[{"tipo":"texto","contenido":"La ciencia no se trata de memorizar datos, sino de hacer buenas preguntas y responderlas con evidencia. En el ICFES, las preguntas de **indagación** no te piden recordar fórmulas: te piden pensar como un investigador. La buena noticia es que esa habilidad se entrena."},{"tipo":"concepto","titulo":"Pregunta, hipótesis y predicción","contenido":"Toda investigación parte de una **pregunta** que se pueda responder con experimentos u observaciones. La **hipótesis** es una posible respuesta a esa pregunta que se puede poner a prueba. Suele expresarse como una predicción del tipo: ''si aumento X, entonces Y aumentará (o disminuirá)''."},{"tipo":"concepto","titulo":"Los tres tipos de variables","contenido":"La **variable independiente** es la que el investigador cambia a propósito. La **variable dependiente** es la que mide para ver el efecto de ese cambio. Las **variables controladas** son todas las condiciones que se mantienen iguales para que no influyan en el resultado."},{"tipo":"concepto","titulo":"Grupo control y repeticiones","contenido":"El **grupo control** no recibe el tratamiento que se está probando y sirve como punto de comparación. Además, un buen experimento usa varios individuos por grupo o repite las mediciones, para que el azar no decida el resultado."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: diseñar un experimento justo","enunciado":"Sofía quiere saber si la temperatura del agua influye en el tiempo que tarda en disolverse una pastilla efervescente. ¿Cómo debería diseñar su experimento?","pasos":["Pregunta: ¿la temperatura del agua afecta el tiempo de disolución de la pastilla?","Hipótesis: a mayor temperatura del agua, menor tiempo de disolución, porque las partículas se mueven más rápido y reaccionan con mayor frecuencia.","Variable independiente: temperatura del agua (por ejemplo, 10 °C, 25 °C, 40 °C y 60 °C). Variable dependiente: tiempo de disolución, medido en segundos.","Variables controladas: mismo volumen de agua (200 mL), misma marca de pastilla, mismo tipo de vaso y sin agitar.","Repeticiones: medir tres veces con cada temperatura y calcular el promedio."],"respuesta":"Un diseño justo cambia solo la temperatura, mide el tiempo de disolución y mantiene constantes todas las demás condiciones."},{"tipo":"lista","titulo":"¿Cuándo es válida una conclusión?","items":["Se apoya en los datos obtenidos, no en opiniones.","Habla solo de las variables que se midieron.","No generaliza más allá de las condiciones probadas.","Compara los resultados con el grupo control.","Reconoce que pocos datos producen conclusiones débiles."]},{"tipo":"lista","titulo":"Errores frecuentes","items":["Cambiar dos variables al mismo tiempo.","Confundir la variable independiente con la dependiente.","Confundir la hipótesis (lo que se espera) con la conclusión (lo que muestran los datos).","Sacar conclusiones a partir de una sola medición."]},{"tipo":"tip","contenido":"Tip ICFES: para identificar variables, pregúntate ''¿qué cambió el investigador a propósito?'' (independiente) y ''¿qué midió?'' (dependiente). Si dos grupos se diferencian en más de una condición, el experimento no permite saber cuál de ellas causó el efecto."},{"tipo":"ejercicio","enunciado":"Carlos riega tres grupos de plantas de tomate con 0, 50 y 100 mL de agua al día y cada semana mide su altura. ¿Cuál es la variable dependiente?","opciones":["La cantidad de agua de riego","La altura de las plantas","El tipo de planta","La duración del experimento"],"correcta":1,"explicacion":"La altura es lo que Carlos mide para ver el efecto del riego: es la variable dependiente. La cantidad de agua es la independiente, y el tipo de planta y la duración son variables controladas."},{"tipo":"ejercicio","enunciado":"Para probar si un abono aumenta la producción de fresas, Ana aplica abono a 10 plantas ubicadas al sol y no aplica nada a 10 plantas ubicadas a la sombra. ¿Cuál es el principal problema de su diseño?","opciones":["Usó muy pocas plantas en el grupo sin abono.","No incluyó ningún grupo de comparación.","Debió aplicar abono a las 20 plantas.","Cambió dos variables a la vez: el abono y la cantidad de luz."],"correcta":3,"explicacion":"Si las plantas abonadas producen más fresas, no se sabe si fue por el abono o por recibir más luz. Todas las plantas deberían estar en las mismas condiciones de luz, y solo el abono debería cambiar."}]'::jsonb,
  10, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;

-- ---------------------------------------------------------------- lecciones/ingles.json
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'reading'), 'ING-REA-L1', 'Lee como detective: skimming y scanning', 'Aprenderás a leer textos en inglés con estrategia para responder preguntas literales e inferenciales sin traducir palabra por palabra.', '[{"tipo":"texto","contenido":"¿Te ha pasado que lees un texto en inglés y a la mitad ya olvidaste cómo empezaba? No es falta de nivel: es falta de estrategia. En las **Partes 5 y 6** del ICFES no necesitas entender cada palabra, sino saber **qué buscar y dónde buscarlo**. Hoy vas a aprender las dos técnicas que usan los lectores expertos."},{"tipo":"concepto","titulo":"Skimming y scanning","contenido":"**Skimming** es leer rápido para captar la idea general: miras el título, la primera oración de cada párrafo y las palabras que se repiten. **Scanning** es buscar un dato específico (un nombre, una fecha, un número o una palabra clave) sin leer todo con detalle, como cuando buscas tu nombre en una lista de resultados."},{"tipo":"concepto","titulo":"Preguntas literales vs. inferenciales","contenido":"Una pregunta **literal** (Parte 5) tiene la respuesta escrita en el texto, aunque con otras palabras (paráfrasis). Una pregunta **inferencial** (Parte 6) te pide deducir algo que no se dice directamente: la actitud del autor, su propósito o una conclusión lógica a partir de varias pistas."},{"tipo":"lista","titulo":"Frases que anuncian una pregunta inferencial","items":["What can we infer about…? → ¿Qué podemos deducir sobre…?","What is the writer''s attitude…? → ¿Cuál es la actitud del autor…?","What is the main purpose of the text? → ¿Cuál es el propósito principal del texto?","What does the writer mean by…? → ¿Qué quiere decir el autor con…?","It is likely that… → Es probable que…"]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto","enunciado":"Text: “Camila started running in 2023. At first, she could only run for ten minutes without stopping. Last month, she finished her first 10-kilometer race in Bucaramanga, and now she is training for a half marathon.”\nQuestion: How has Camila changed since 2023?","pasos":["Skimming: el texto habla de Camila y de su progreso como corredora.","Scanning: busca las expresiones de tiempo para comparar el antes y el después: at first → solo diez minutos; last month → terminó una carrera de 10 kilómetros; now → entrena para una media maratón.","Inferencia: el texto no dice «she is stronger», pero todas las pistas muestran que ahora puede correr distancias mucho más largas."],"respuesta":"She can run much longer distances than before."},{"tipo":"tip","contenido":"Tip ICFES: lee primero la pregunta y después el texto; así sabrás exactamente qué buscar. Desconfía de las opciones que copian palabras exactas del texto: suelen ser trampas. La respuesta correcta casi siempre está parafraseada."},{"tipo":"lista","titulo":"Errores frecuentes","items":["Traducir palabra por palabra y perder la idea general.","Elegir una opción solo porque repite palabras del texto.","Responder con tu opinión o con lo que sabes del tema, en lugar de lo que dice el texto.","Confundir la opinión de un personaje con la del autor."]},{"tipo":"ejercicio","enunciado":"Read: “The school library opens at 7 a.m. and closes at 4 p.m. On Fridays, it closes two hours earlier.”\nWhat time does the library close on Fridays?","opciones":["At 7 a.m.","At 2 p.m.","At 4 p.m.","At 6 p.m."],"correcta":1,"explicacion":"Haz scanning con la palabra Fridays: ese día la biblioteca cierra dos horas antes (two hours earlier) de lo normal, es decir, a las 2 p.m. Las 4 p.m. es la hora de cierre de los demás días, y las 6 p.m. resulta de sumar las dos horas en lugar de restarlas."},{"tipo":"ejercicio","enunciado":"Read: “Andrés looked at the dark clouds, put his umbrella in his backpack and told his mom: ‘I think I''ll take the bus today instead of my bike.’”\nWhat can we infer?","opciones":["Andrés''s bike is broken.","Andrés doesn''t like his school.","Andrés thinks it is going to rain.","Andrés''s mom is going to drive him."],"correcta":2,"explicacion":"El texto no dice que la bicicleta esté dañada ni que su mamá lo vaya a llevar. Las pistas son las nubes oscuras (dark clouds), el paraguas en la maleta y que prefiere el bus a la bicicleta: todo indica que cree que va a llover. Eso es una inferencia: no está escrito, pero se deduce de varias pistas."}]'::jsonb,
  10, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'grammar'), 'ING-GRA-L1', 'Present perfect vs. simple past: ¿ya terminó o sigue pasando?', 'Aprenderás a elegir entre el present perfect y el simple past usando las pistas de tiempo que trae cada oración.', '[{"tipo":"texto","contenido":"En la **Parte 4** del ICFES encontrarás textos cortos con huecos, y muchos de ellos evalúan tiempos verbales. El par que más confunde a los hispanohablantes es el **present perfect** (I have lived) y el **simple past** (I lived). La buena noticia: casi siempre la oración trae una pista que te dice cuál usar. ¡Vamos a aprender a encontrarla!"},{"tipo":"concepto","titulo":"La idea clave","contenido":"Usa el **simple past** para acciones terminadas en un momento concreto del pasado (yesterday, last year, in 2019, two days ago). Usa el **present perfect** cuando la acción empezó en el pasado y continúa hoy, o cuando importa la experiencia o el resultado sin decir cuándo ocurrió (since, for, ever, never, already, yet)."},{"tipo":"formula","contenido":"Present perfect: Subject + have/has + past participle","nota":"I have visited Cartagena twice. / She has lived in Cali since 2020."},{"tipo":"formula","contenido":"Simple past: Subject + verb in the past (-ed or irregular form)","nota":"We visited Cartagena last December. / She moved to Cali in 2020."},{"tipo":"lista","titulo":"Palabras pista","items":["Simple past → yesterday, last week, last year, ago, in 2019, when I was a child","Present perfect → since, for, already, yet, ever, never, just, so far","Since + punto de inicio (since 2020, since Monday)","For + duración (for three years, for a week)"]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto","enunciado":"Complete: “My brother ______ (play) soccer since he was six, and last Saturday he ______ (score) his first goal in a real match.”","pasos":["Primer hueco: since he was six indica una acción que empezó en el pasado y continúa hoy → present perfect.","El sujeto es my brother (he), así que se usa has: has played.","Segundo hueco: last Saturday es un momento terminado del pasado → simple past: scored."],"respuesta":"has played / scored"},{"tipo":"lista","titulo":"Errores frecuentes","items":["I live here since 2020 ✗ → I have lived here since 2020 ✓","I have seen that movie yesterday ✗ → I saw that movie yesterday ✓","She has went to Medellín ✗ → She has gone to Medellín ✓ (se usa el participio, no el pasado)","I have studied here since three years ✗ → I have studied here for three years ✓"]},{"tipo":"tip","contenido":"Tip ICFES: antes de mirar las opciones, subraya las expresiones de tiempo que rodean el hueco. Si ves ago, yesterday o last, piensa en simple past; si ves since o for con una situación que continúa, piensa en present perfect."},{"tipo":"ejercicio","enunciado":"Choose the correct option: “I ______ Medellín three years ago.”","opciones":["have visited","visited","has visited","visit"],"correcta":1,"explicacion":"Three years ago señala un momento terminado del pasado, por eso se usa el simple past: visited. La palabra ago nunca va con present perfect."},{"tipo":"ejercicio","enunciado":"Choose the correct option: “Laura and Felipe ______ best friends since 2018.”","opciones":["are","were","have been","has been"],"correcta":2,"explicacion":"Since 2018 indica que la amistad empezó en el pasado y continúa hoy, así que se usa present perfect. Como el sujeto es plural (Laura and Felipe), la forma correcta es have been, no has been."}]'::jsonb,
  12, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'vocabulary'), 'ING-VOC-L1', 'Avisos y falsos amigos: que no te engañen las palabras', 'Aprenderás a interpretar avisos cortos y a reconocer los falsos amigos que más confunden a los hispanohablantes en las Partes 1 y 2.', '[{"tipo":"texto","contenido":"Las **Partes 1 y 2** del ICFES evalúan vocabulario. En la Parte 1 lees avisos (notices) y decides dónde podrías verlos o qué significan; en la Parte 2 relacionas descripciones con palabras. Son preguntas rápidas, ideales para sumar puntos, pero tienen trampas: palabras que se parecen al español y significan otra cosa."},{"tipo":"concepto","titulo":"¿Qué es un falso amigo?","contenido":"Un **falso amigo** (false friend) es una palabra en inglés que se escribe o suena parecido a una del español, pero tiene otro significado. Por ejemplo, **library** no es «librería», sino «biblioteca», y **parents** no son «parientes», sino «padres»."},{"tipo":"lista","titulo":"Falsos amigos que debes conocer","items":["library = biblioteca (librería = bookstore)","parents = padres (parientes = relatives)","carpet = alfombra (carpeta = folder)","exit = salida (éxito = success)","actually = en realidad (actualmente = currently)","embarrassed = avergonzado (embarazada = pregnant)","assist = ayudar (asistir = attend)"]},{"tipo":"concepto","titulo":"El lenguaje de los avisos","contenido":"Los avisos usan frases cortas y directas. Memoriza estas fórmulas: **No + verbo-ing** (No parking = prohibido estacionar), **Please do not…** (por favor, no…), **… must be…** (obligación: Helmets must be worn = es obligatorio usar casco), **Keep + adjetivo** (Keep this door closed = mantenga esta puerta cerrada) y **Out of order** (fuera de servicio)."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto","enunciado":"Notice: “Out of order. Please use the stairs.”\nWhere can you see this notice?","pasos":["Identifica las palabras clave: out of order (fuera de servicio) y stairs (escaleras).","Pregúntate qué aparato podría dañarse y obligarte a usar las escaleras en su lugar.","Conclusión: el aviso está en un ascensor (elevator) o en una escalera eléctrica (escalator) de un edificio."],"respuesta":"On an elevator (or an escalator) in a building."},{"tipo":"tip","contenido":"Tip ICFES: en la Parte 1, lee todas las palabras del aviso, no solo la primera o la última. Imagina la escena: ¿quién lo escribió y para quién? Cada opción incorrecta suele estar diseñada para atrapar a quien reconoce solo una palabra suelta."},{"tipo":"lista","titulo":"Pistas para la Parte 2 (léxico)","items":["Identifica la categoría: ¿la descripción habla de una persona, un lugar, un objeto o una acción?","Fíjate en el inicio: You can buy… here (lugar), This person… (persona o profesión), You use this to… (objeto).","Descarta primero las opciones de otra categoría.","Si una opción se parece mucho a una palabra en español, verifica que no sea un falso amigo."]},{"tipo":"ejercicio","enunciado":"Notice: “Keep off the grass.”\nWhat does this notice mean?","opciones":["You can play soccer here.","You must cut the grass.","Do not walk on the grass.","The grass is for sale."],"correcta":2,"explicacion":"Keep off significa «mantenerse alejado de algo»: Keep off the grass = no pisar el césped. La primera opción dice lo contrario, la segunda inventa una obligación que el aviso no menciona y la cuarta no tiene relación con el mensaje."},{"tipo":"ejercicio","enunciado":"Which word completes the sentence? “I need a ______ to keep all my English worksheets together.”","opciones":["carpet","folder","library","record"],"correcta":1,"explicacion":"Folder significa «carpeta», el objeto para guardar hojas. Carpet es un falso amigo: significa «alfombra». Library es «biblioteca» y record significa «registro» o «disco»."}]'::jsonb,
  10, 30, 5, 1)
