INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'context-understanding'), 'ING-CON-L1', 'Conversaciones reales: responde según la situación', 'Aprenderás a escoger la respuesta más natural en diálogos cortos y a deducir el propósito o la actitud de quien habla o escribe.', '[{"tipo":"texto","contenido":"Entender el contexto es saber leer entre líneas. En la **Parte 3** del ICFES completas conversaciones cortas eligiendo la respuesta más adecuada, y en la **Parte 6** deduces ideas que el texto no dice directamente. En ambos casos la gramática no basta: necesitas pensar en **la situación, la intención y el tono** de quien habla."},{"tipo":"concepto","titulo":"Funciones comunicativas","contenido":"Cada frase cumple una función: pedir algo, ofrecer, agradecer, disculparse, sugerir o invitar. La respuesta correcta es la que **corresponde a esa función**. Si alguien te agradece (Thanks a lot!), respondes You''re welcome; si alguien se disculpa (I''m sorry I''m late), respondes Don''t worry o That''s OK."},{"tipo":"lista","titulo":"Pares frecuentes (frase → respuesta natural)","items":["Thank you so much! → You''re welcome. / No problem.","I''m sorry I''m late. → Don''t worry. / That''s OK.","Would you like some juice? → Yes, please. / No, thanks.","Could you help me with this box? → Sure! / Of course.","Why don''t we go to the park? → Good idea! / That sounds great.","Have a nice weekend! → Thanks, you too!"]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto","enunciado":"A: Would you like to come to my house on Saturday to watch the match?\nB: ______\nA: Great! It starts at three.","pasos":["Identifica la función de la primera línea: Would you like…? es una invitación.","Mira la línea siguiente: Great! It starts at three → B aceptó la invitación.","Descarta las respuestas que rechazan la invitación o que responden a otra función (por ejemplo, You''re welcome responde a un agradecimiento)."],"respuesta":"Sure, I''d love to!"},{"tipo":"tip","contenido":"Tip ICFES: en la Parte 3, lee también lo que viene **después** del hueco. Si la otra persona responde Yes, here it is o Great!, esa reacción te dice exactamente qué tipo de frase falta."},{"tipo":"concepto","titulo":"Inferir propósito y actitud","contenido":"En reseñas, correos o mensajes, pregúntate: ¿para qué lo escribió (informar, quejarse, recomendar, invitar, disculparse)? ¿Cómo se siente (entusiasmado, decepcionado, preocupado)? Las pistas están en los adjetivos (amazing, disappointing), en los conectores de contraste (but, however) y en los consejos finales (My advice…, You should…)."},{"tipo":"lista","titulo":"Errores frecuentes","items":["Responder a la gramática y no a la intención: Why don''t we…? es una sugerencia, no una pregunta sobre razones.","Confundir You''re welcome (de nada) con Welcome (bienvenido).","Elegir una opción porque repite una palabra del diálogo.","Atribuirle al autor la opinión de otro personaje."]},{"tipo":"ejercicio","enunciado":"Complete the conversation:\nA: I passed my chemistry exam! I studied all weekend.\nB: ______","opciones":["Congratulations! That''s great news.","Never mind. Maybe next time.","You''re welcome.","I''m sorry to hear that."],"correcta":0,"explicacion":"A comparte una buena noticia, así que lo natural es felicitarlo: Congratulations! Never mind. Maybe next time sirve para consolar a alguien a quien le fue mal, You''re welcome responde a un agradecimiento e I''m sorry to hear that se usa ante una mala noticia."},{"tipo":"ejercicio","enunciado":"Read: “Hi, Ms. Duarte. I''m writing because I was sick yesterday and missed the English test. Is it possible to take it another day? I can bring a doctor''s note. Thank you, Samuel.”\nWhat is Samuel''s main purpose?","opciones":["To complain about the English test.","To explain why he missed school last week.","To ask for another date to take the test.","To send his doctor''s note to the teacher."],"correcta":2,"explicacion":"Samuel explica que estuvo enfermo, pero su propósito principal es pedir otra oportunidad: Is it possible to take it another day? No se queja del examen, habla de ayer (no de la semana pasada) y ofrece llevar la excusa médica después; no la está enviando."}]'::jsonb,
  10, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'language-use'), 'ING-LAN-L1', 'Texto incompleto: conectores y colocaciones que suman puntos', 'Aprenderás a completar textos en inglés reconociendo conectores y colocaciones, las claves de la Parte 7.', '[{"tipo":"texto","contenido":"La **Parte 7** del ICFES es un texto con huecos en el que varias opciones parecen posibles si traduces palabra por palabra. El secreto está en mirar **la estructura alrededor del hueco**: qué viene antes, qué viene después y qué relación hay entre las ideas. Dos tipos de huecos aparecen una y otra vez: **conectores** y **colocaciones**."},{"tipo":"concepto","titulo":"Conectores: la relación entre ideas","contenido":"Los conectores muestran cómo se relacionan dos ideas: **adición** (and, also, moreover), **contraste** (but, however, although, despite), **causa** (because, since) y **consecuencia** (so, therefore). Primero decide qué relación hay entre las ideas y luego revisa qué estructura gramatical exige cada conector."},{"tipo":"formula","contenido":"Although / Even though + subject + verb, main clause","nota":"Although it was raining, we went to the Ciclovía."},{"tipo":"formula","contenido":"Despite / In spite of + noun or verb-ing, main clause","nota":"Despite the rain, we went to the Ciclovía. / Despite feeling tired, she finished the race."},{"tipo":"concepto","titulo":"Colocaciones: palabras que siempre van juntas","contenido":"Una **colocación** es una combinación de palabras que los hablantes nativos usan siempre de la misma forma. No se traduce literalmente: en español «hacemos» una pregunta, pero en inglés se dice **ask** a question; «tomamos» una decisión, pero en inglés se dice **make** a decision."},{"tipo":"lista","titulo":"Colocaciones frecuentes","items":["make: a decision, a mistake, a plan, friends, noise","do: homework, exercise, a favor, the dishes, your best","take: part in, a photo, a break, a bus, a test","have: breakfast, a party, fun, a good time","pay: attention, a visit, the bill"]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto","enunciado":"Complete: “______ it was raining very hard, my cousin took amazing photos of Caño Cristales.” (although / despite / because)","pasos":["Hay dos ideas opuestas: llovía mucho / tomó fotos increíbles → se necesita un conector de contraste, así que because queda descartado.","Después del hueco viene sujeto + verbo (it was raining) → despite no sirve, porque exige un sustantivo o un verbo-ing.","El único conector de contraste que acepta sujeto + verbo es although."],"respuesta":"Although it was raining very hard, my cousin took amazing photos of Caño Cristales."},{"tipo":"lista","titulo":"Errores frecuentes","items":["Make part of ✗ → be part of / take part in ✓","Despite it was late ✗ → Although it was late / Despite the late hour ✓","Even it was late ✗ → Even though it was late ✓","Make homework ✗ → Do homework ✓"]},{"tipo":"tip","contenido":"Tip ICFES: en la Parte 7, lee primero el texto completo sin detenerte en los huecos para entender la idea general. Luego prueba cada opción mentalmente con las palabras de antes y de después. Si dudas entre dos conectores, revisa si lo que sigue es una oración (sujeto + verbo) o un sustantivo."},{"tipo":"ejercicio","enunciado":"Complete: “Sofía couldn''t go to the concert ______ she had a very important exam the next day.”","opciones":["although","because","despite","however"],"correcta":1,"explicacion":"Tener un examen importante es la causa de que Sofía no fuera al concierto, así que se necesita un conector de causa: because. Although y despite expresan contraste, y however no puede unir dos oraciones de esa manera."},{"tipo":"ejercicio","enunciado":"Complete: “Our teacher always says: ‘Don''t worry if you ______ a mistake. That''s how we learn!’”","opciones":["do","take","make","have"],"correcta":2,"explicacion":"La colocación correcta es make a mistake (cometer un error). Aunque en español decimos «hacer» o «cometer», en inglés mistake va siempre con make, nunca con do, take ni have."}]'::jsonb,
  12, 30, 5, 1)
