-- ---------------------------------------------------------------- lecciones/lectura-critica.json
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'comprension-textual'), 'LEC-COM-L1', 'Lee lo que el texto dice (y nada más)', 'Aprenderás a localizar información explícita, a parafrasear sin deformar y a descubrir el sentido de palabras y expresiones según su contexto.', '[{"tipo":"texto","contenido":"En el ICFES, muchas preguntas de Lectura Crítica no buscan tu opinión: quieren comprobar que entiendes **qué dice exactamente el texto**. Parece fácil, pero es donde más puntos se pierden, porque leemos rápido, completamos con lo que ya sabemos y terminamos respondiendo algo que el texto nunca dijo. En esta lección vas a entrenar el ojo para leer con precisión."},{"tipo":"concepto","titulo":"Comprensión literal","contenido":"Es la capacidad de identificar la información que aparece **de forma explícita** en un texto: quién hace qué, cuándo, dónde, cómo y por qué, además del significado de palabras y expresiones **según el contexto** en el que aparecen. Una respuesta literal siempre se puede señalar con el dedo en el texto."},{"tipo":"lista","titulo":"Estrategia L-P-V para preguntas literales","items":["**Localiza**: subraya la palabra clave del enunciado y búscala (o un sinónimo) en el texto.","**Parafrasea**: di con tus palabras lo que dice ese fragmento, sin agregar ni quitar información.","**Verifica**: compara cada opción con el fragmento y descarta las que agregan datos, invierten causa y efecto o mezclan información de otro párrafo."]},{"tipo":"concepto","titulo":"El sentido depende del contexto","contenido":"Una misma palabra cambia de significado según la frase: «pesado» no significa lo mismo en «un bulto pesado» que en «un compañero pesado». Cuando el ICFES pregunta qué significa una expresión **en el texto**, busca el sentido que tiene allí, no la definición del diccionario. Relee la oración anterior y la siguiente: casi siempre ahí está la pista."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: sentido de una expresión","enunciado":"Micro-texto: «Cuando anunciaron que el examen se aplazaba, el salón fue una olla a presión que por fin soltó el vapor: gritos, risas y hasta aplausos». ¿Qué significa en el texto la expresión «una olla a presión que por fin soltó el vapor»?","pasos":["Paso 1: reconoce que la expresión es figurada: el salón no es literalmente una olla.","Paso 2: busca las pistas cercanas. Antes: el anuncio de que el examen se aplazaba. Después: «gritos, risas y hasta aplausos».","Paso 3: piensa qué tienen en común el salón y la olla: una tensión acumulada que se libera de golpe.","Paso 4: formula el sentido con tus palabras y comprueba que encaje con las pistas: los estudiantes estaban tensos y, con la noticia, soltaron esa tensión con alegría.","Paso 5: descarta lecturas literales (algo se calentó en el salón) y extrapolaciones (los estudiantes estaban furiosos con el profesor)."],"respuesta":"La expresión indica que los estudiantes, tensos por el examen, liberaron de golpe esa tensión al saber que se aplazaba."},{"tipo":"lista","titulo":"Trampas frecuentes en preguntas literales","items":["Opciones que dicen algo **cierto en la vida real**, pero que el texto no menciona.","Opciones que **mezclan** datos de dos párrafos distintos.","Opciones que **invierten** la causa y el efecto o el orden de los hechos.","Opciones que cambian una palabra clave: «algunos» por «todos», «puede» por «siempre»."]},{"tipo":"tip","contenido":"Tip ICFES: en las preguntas literales, la opción correcta casi nunca copia el texto palabra por palabra; suele ser una **paráfrasis fiel**. Desconfía de la opción que repite una frase exacta, pero le cambia una palabra clave como «nunca», «todos» o «siempre»."},{"tipo":"ejercicio","enunciado":"Lee: «La biblioteca del barrio abre de lunes a sábado. Los sábados solo atiende en la mañana porque, en la tarde, el salón se usa para el taller de teatro». Según el texto, ¿por qué la biblioteca no atiende los sábados en la tarde?","opciones":["Porque los sábados en la tarde no llegan lectores.","Porque en la tarde el salón se usa para el taller de teatro.","Porque los bibliotecarios descansan los fines de semana.","Porque la biblioteca solo abre de lunes a viernes."],"correcta":1,"explicacion":"El texto dice explícitamente que en la tarde «el salón se usa para el taller de teatro». La primera opción inventa una causa, la tercera agrega información que no aparece y la cuarta contradice el texto, que dice que la biblioteca abre de lunes a sábado."},{"tipo":"ejercicio","enunciado":"Lee: «Después de tres derrotas seguidas, el entrenador reunió al equipo y habló sin rodeos: el problema no era la suerte, sino la falta de entrenamiento». En el texto, la expresión «habló sin rodeos» significa que el entrenador","opciones":["habló durante mucho tiempo sin dejar participar a nadie.","habló caminando en línea recta frente al equipo.","dijo las cosas de manera directa y clara.","evitó hablar del problema para no desanimar al equipo."],"correcta":2,"explicacion":"«Sin rodeos» significa «de forma directa». Lo confirma lo que sigue: el entrenador dice abiertamente que el problema era la falta de entrenamiento. La opción de caminar en línea recta es una lectura literal, y la de evitar el problema dice lo contrario de lo que ocurre."}]'::jsonb,
  9, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'inferencias'), 'LEC-INF-L1', 'Leer entre líneas sin inventar', 'Aprenderás a sacar conclusiones que el texto no dice directamente, pero que sus pistas permiten sostener, y a diferenciarlas de las suposiciones sin base.', '[{"tipo":"texto","contenido":"Los textos no lo dicen todo: dejan pistas para que el lector complete el sentido. Si un personaje «mira el reloj por quinta vez», nadie tiene que escribir que está impaciente. A eso se le llama **inferir**. En el ICFES, las preguntas de inferencia son de las más frecuentes, y la clave está en el punto medio: ni quedarse en lo literal, ni inventar."},{"tipo":"concepto","titulo":"¿Qué es una inferencia válida?","contenido":"Es una conclusión que **no aparece escrita** en el texto, pero que se deduce de las pistas que sí están, combinadas con conocimientos generales razonables. Fórmula práctica: **pista del texto + lo que sé = conclusión**. Si no puedes señalar ninguna pista que la apoye, no es una inferencia: es una suposición."},{"tipo":"lista","titulo":"Tres tipos de conclusiones que encontrarás en las opciones","items":["**Literal**: repite lo que el texto dice. Es verdadera, pero no responde cuando te piden inferir.","**Inferencia válida**: va más allá del texto, pero se apoya en pistas concretas.","**Extrapolación**: va demasiado lejos; suena lógica, pero el texto no da pistas suficientes para sostenerla (o incluso la contradice)."]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: ¿qué se puede inferir?","enunciado":"Micro-texto: «Camila llegó empapada, dejó el paraguas roto en la entrada y le pidió a su hermano una toalla. Afuera, los carros avanzaban despacio por la calle convertida en río». ¿Cuál conclusión es una inferencia válida? (1) Llovía con fuerza. (2) Camila odia la lluvia. (3) Camila perdió el bus por culpa de su hermano.","pasos":["Paso 1: subraya las pistas: «llegó empapada», «paraguas roto», «pidió una toalla», «calle convertida en río», «carros avanzaban despacio».","Paso 2: combina las pistas con lo que sabes: alguien empapado, con el paraguas roto y una calle inundada indican un aguacero fuerte.","Paso 3: revisa la conclusión 2: el texto no dice nada sobre lo que Camila siente por la lluvia. Es una suposición.","Paso 4: revisa la conclusión 3: no hay ninguna pista sobre un bus ni sobre el hermano como responsable. Es una invención.","Paso 5: aplica la prueba del dedo: para la conclusión 1 puedes señalar varias pistas en el texto; para las otras, ninguna."],"respuesta":"La inferencia válida es la 1: llovía con fuerza."},{"tipo":"concepto","titulo":"Inferir en textos narrativos","contenido":"En los cuentos, las emociones y las intenciones de los personajes casi nunca se nombran: se muestran con acciones, gestos, silencios y detalles del ambiente. Pregúntate: ¿qué hace el personaje?, ¿qué cambia entre el comienzo y el final?, ¿qué sabe el narrador y qué sabe el lector? A veces el lector deduce cosas que el propio narrador todavía no entiende."},{"tipo":"tip","contenido":"Tip ICFES: cuando dudes entre dos opciones de inferencia, elige la que necesite **menos suposiciones extra**. La correcta suele ser la más prudente: se apoya en varias pistas y no agrega hechos que el texto no menciona."},{"tipo":"lista","titulo":"Señales de que una opción es una extrapolación","items":["Usa palabras absolutas como «siempre», «nunca», «todos» o «nadie» que el texto no respalda.","Atribuye a los personajes intenciones o sentimientos sin ninguna pista.","Predice consecuencias muy lejanas a partir de un solo dato.","Contradice algún detalle del texto que se leyó con prisa."]},{"tipo":"ejercicio","enunciado":"Lee: «Don Ernesto puso el arroz y la panela sobre el mostrador, contó sus monedas dos veces y, con un suspiro, devolvió la panela al estante». ¿Qué se puede inferir del texto?","opciones":["Don Ernesto no tenía dinero suficiente para comprar todo lo que quería.","A don Ernesto no le gusta la panela.","Don Ernesto es el dueño de la tienda.","Don Ernesto siempre tiene problemas económicos."],"correcta":0,"explicacion":"Las pistas («contó sus monedas dos veces», «con un suspiro», «devolvió la panela») indican que el dinero no le alcanzaba para todo. Que no le guste la panela no tiene apoyo (el suspiro sugiere que sí la quería), nada indica que sea el dueño de la tienda y la última opción generaliza con «siempre» a partir de una sola escena."},{"tipo":"ejercicio","enunciado":"Lee: «Todos los días, a las seis de la tarde, Sofía se asoma a la ventana cuando pasa el bus del colegio. Desde que su mejor amiga se trasteó a Cali, el bus pasa y Sofía sigue mirando la calle un largo rato». ¿Cuál es la inferencia más razonable?","opciones":["Sofía quiere cambiarse de colegio.","Sofía también se va a trastear a Cali.","A Sofía le molesta el ruido del bus.","Sofía extraña a su amiga, a quien seguramente veía llegar en ese bus."],"correcta":3,"explicacion":"El texto relaciona el cambio en la conducta de Sofía con el trasteo de su amiga: el bus pasa y ella se queda mirando la calle. Eso permite inferir que la extraña y que antes la esperaba. Las demás opciones no tienen ninguna pista que las respalde."}]'::jsonb,
  10, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'interpretacion'), 'LEC-INT-L1', 'Del detalle al sentido global', 'Aprenderás a encontrar la idea principal de un texto, a interpretar el lenguaje figurado y a leer tablas e infografías sin caer en trampas.', '[{"tipo":"texto","contenido":"Interpretar es construir el **sentido global** de un texto: qué quiere decir como un todo, qué significa una metáfora o qué muestran los datos de una tabla. Es como armar un rompecabezas: cada párrafo es una ficha, y tu tarea es ver la imagen completa sin perder de vista ninguna pieza."},{"tipo":"concepto","titulo":"Tema, idea principal e ideas secundarias","contenido":"El **tema** es de qué habla el texto, en pocas palabras («los páramos»). La **idea principal** es lo que el texto afirma sobre ese tema, en una oración completa («los páramos son vitales porque regulan el agua que consumen muchas ciudades»). Las **ideas secundarias** son los ejemplos, datos, explicaciones o detalles que apoyan la idea principal."},{"tipo":"lista","titulo":"Prueba rápida de la idea principal","items":["¿Resume el texto completo y no solo un párrafo?","¿Los ejemplos y los datos del texto la apoyan?","¿Evita exagerar («todos», «nunca») o agregar propuestas que el autor no hace?","¿Podría ser el titular fiel del texto?"]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: encontrar la idea principal","enunciado":"Micro-texto: «Muchos creen que reciclar consiste solo en separar la basura. Sin embargo, si el plástico llega sucio, las plantas de aprovechamiento lo descartan. Además, sin rutas de recolección selectiva, lo que se separa en casa termina mezclado en el camión. Separar es apenas el primer eslabón de una cadena». ¿Cuál es la idea principal?","pasos":["Paso 1: identifica el tema: el reciclaje.","Paso 2: ubica la afirmación que el autor defiende. El conector «Sin embargo» marca el giro frente a la creencia común.","Paso 3: clasifica el resto: el plástico sucio y la falta de rutas son ejemplos, es decir, ideas secundarias.","Paso 4: busca la frase que recoge todo: «Separar es apenas el primer eslabón de una cadena».","Paso 5: formula la idea principal en una oración y comprueba que cubra todo el texto."],"respuesta":"Reciclar no es solo separar la basura: para que funcione se necesitan otros eslabones, como entregar materiales limpios y contar con recolección selectiva."},{"tipo":"concepto","titulo":"Interpretar el lenguaje figurado","contenido":"Metáforas, comparaciones, ironías y personificaciones dicen algo **distinto** de su sentido literal. Para interpretarlas, identifica los dos elementos que se relacionan, pregúntate qué tienen en común y verifica que tu interpretación encaje con el resto del texto. Ejemplo: «el páramo es una esponja» significa que absorbe el agua y la suelta poco a poco, no que sea blando."},{"tipo":"concepto","titulo":"Leer tablas, gráficas e infografías","contenido":"Los textos discontinuos también se leen con método. Antes de responder, revisa el **título**, las **columnas** o los ejes, las **unidades** (%, horas, pesos) y la **fuente**. Después busca **tendencias**: qué sube, qué baja y qué se mantiene. Y recuerda: que dos datos cambien juntos no prueba que uno cause el otro."},{"tipo":"tip","contenido":"Tip ICFES: si una opción de idea principal es muy específica (un dato, un nombre, un ejemplo), casi seguro es un distractor. Si es tan general que serviría para cualquier texto, también. La correcta está en el punto justo: cubre todo el texto y dice algo concreto."},{"tipo":"ejercicio","enunciado":"Lee: «En Colombia se desperdician millones de toneladas de alimentos cada año. Una parte se pierde en el campo por falta de vías; otra, en las plazas de mercado por mal almacenamiento; y otra, en los hogares, cuando compramos más de lo que consumimos. Reducir el desperdicio exige cambios en toda la cadena, desde la finca hasta la nevera». ¿Cuál es la idea principal?","opciones":["En los hogares colombianos se compran más alimentos de los que se consumen.","El desperdicio de alimentos ocurre en varias etapas, por lo que reducirlo requiere cambios en toda la cadena.","Colombia debe construir más vías para sacar las cosechas del campo.","Los alimentos se dañan en las plazas de mercado por mal almacenamiento."],"correcta":1,"explicacion":"La opción correcta recoge la afirmación central y la conclusión del texto («reducir el desperdicio exige cambios en toda la cadena»). Las opciones sobre los hogares y las plazas de mercado son ejemplos de un solo eslabón (ideas secundarias), y la de construir vías es una propuesta que el texto no hace."},{"tipo":"ejercicio","enunciado":"Una tabla muestra las visitas a la biblioteca de un colegio: enero, 120; febrero, 180; marzo, 240; abril, 90 (mes con vacaciones de Semana Santa). ¿Cuál interpretación se sostiene con los datos?","opciones":["La asistencia aumentó todos los meses del primer cuatrimestre.","Las vacaciones hicieron que los estudiantes dejaran de leer para siempre.","La asistencia creció de enero a marzo y cayó en abril, el mes con vacaciones.","En abril hubo el doble de visitas que en enero."],"correcta":2,"explicacion":"Los datos suben de 120 a 180 y a 240, y bajan a 90 en abril. La primera opción ignora la caída de abril, la segunda es una extrapolación que la tabla no permite (además confunde visitas a la biblioteca con lectura) y la cuarta es falsa: 90 es menos que 120."}]'::jsonb,
  11, 30, 5, 1)
