  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'analisis-textos'), 'LEC-ANA-L1', 'Cómo está armado un texto: tipos, partes y conectores', 'Aprenderás a reconocer el tipo de texto y su intención, a identificar la función de cada párrafo y a usar los conectores como mapa de lectura.', '[{"tipo":"texto","contenido":"Un texto no es un montón de frases sueltas: es una construcción en la que cada parte cumple un papel. Así como un equipo de fútbol tiene arquero, defensas y delanteros, un texto tiene párrafos que introducen, argumentan, ejemplifican, conceden o concluyen. Cuando ves esa estructura, las preguntas de análisis se vuelven mucho más fáciles."},{"tipo":"concepto","titulo":"Tipos de texto e intención comunicativa","contenido":"Según su propósito, un texto puede ser **narrativo** (cuenta hechos reales o imaginarios), **expositivo** (explica o informa), **argumentativo** (defiende una tesis para convencer), **descriptivo** (muestra cómo es algo), **instructivo** (indica pasos) o **discontinuo** (tablas, gráficas, infografías, avisos). La **intención comunicativa** es ese propósito: narrar, informar, persuadir, criticar, describir u orientar."},{"tipo":"lista","titulo":"Funciones típicas de un párrafo","items":["**Introducir**: presenta el tema o el problema.","**Plantear la tesis**: dice qué defiende el autor.","**Argumentar**: da razones, datos o ejemplos.","**Conceder**: reconoce una idea contraria o una limitación («es cierto que…», «ahora bien…»).","**Refutar**: responde a una objeción.","**Concluir**: recoge lo dicho o hace una propuesta."]},{"tipo":"lista","titulo":"Conectores y la relación que marcan","items":["**Adición**: además, también, asimismo, incluso.","**Contraste**: pero, sin embargo, no obstante, en cambio.","**Concesión**: aunque, si bien, a pesar de que, ahora bien.","**Causa**: porque, ya que, puesto que, dado que.","**Consecuencia**: por eso, por lo tanto, así que, de modo que.","**Ejemplificación**: por ejemplo, es decir, como.","**Conclusión**: en conclusión, en síntesis, finalmente."]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: la función de un fragmento","enunciado":"Micro-texto de una columna: (1) «Los parques de Medellín deberían tener más bebederos públicos». (2) «Cada fin de semana miles de personas hacen ejercicio en ellos y muchas compran agua embotellada, lo que genera toneladas de plástico». (3) «Es cierto que instalar bebederos cuesta dinero. Sin embargo, sale más barato que recoger y procesar esas botellas». ¿Qué función cumple el fragmento (3)?","pasos":["Paso 1: identifica la tesis: el fragmento (1) dice lo que el autor defiende (más bebederos).","Paso 2: identifica el argumento: el fragmento (2) da una razón (el plástico de las botellas).","Paso 3: observa los conectores del fragmento (3): «Es cierto que» reconoce un punto en contra (el costo) y «Sin embargo» introduce la respuesta del autor.","Paso 4: nombra la función: el autor concede una objeción y luego la refuta para sostener su tesis.","Paso 5: descarta funciones que no encajan: el fragmento no introduce el tema, no cambia la postura del autor ni presenta un ejemplo."],"respuesta":"El fragmento (3) reconoce una posible objeción (el costo) y la refuta para sostener la tesis."},{"tipo":"concepto","titulo":"¿Quién habla en el texto?","contenido":"En un texto pueden aparecer varias voces: el narrador, los personajes, el autor, las personas que el autor cita o las posturas con las que discute. Distingue siempre **quién dice qué**: una idea que el autor menciona no siempre es una idea que el autor defiende. En los cuentos, pregúntate además qué tanto sabe el narrador."},{"tipo":"tip","contenido":"Tip ICFES: cuando te pregunten por la función de un párrafo, mira cómo empieza. Los conectores del inicio («Sin embargo», «Por eso», «Ahora bien», «Por ejemplo») son el mapa que te dice cómo se relaciona ese párrafo con lo anterior."},{"tipo":"ejercicio","enunciado":"Lee: «Moverse en bicicleta es económico: no requiere gasolina ni parqueadero pago. ______, mejora la salud de quienes la usan». ¿Qué conector completa mejor el texto?","opciones":["Sin embargo","Por lo tanto","Además","Aunque"],"correcta":2,"explicacion":"La segunda oración suma otro beneficio de la bicicleta, así que se necesita un conector de adición: «Además». «Sin embargo» y «Aunque» marcan contraste o concesión, y «Por lo tanto» presentaría la buena salud como consecuencia del ahorro de dinero, lo cual no tiene sentido."},{"tipo":"ejercicio","enunciado":"¿Cuál es la intención comunicativa principal de un texto que explica, con datos y ejemplos, cómo se forman los huracanes en el mar Caribe?","opciones":["Convencer al lector de mudarse lejos de la costa.","Narrar la historia de una familia afectada por un huracán.","Dar instrucciones para armar un kit de emergencias.","Informar y explicar un fenómeno natural."],"correcta":3,"explicacion":"Un texto que explica cómo se forma un fenómeno, con datos y ejemplos, es expositivo: su intención es informar y explicar. Convencer corresponde a un texto argumentativo, narrar a uno narrativo y dar instrucciones a uno instructivo."}]'::jsonb,
  12, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'argumentacion'), 'LEC-ARG-L1', 'Tesis, argumentos y trampas del razonamiento', 'Aprenderás a identificar la tesis y los argumentos de un texto, a reconocer falacias frecuentes y a decidir qué información refuerza o debilita una postura.', '[{"tipo":"texto","contenido":"Las preguntas más exigentes de Lectura Crítica te piden **evaluar**: ¿el argumento es sólido?, ¿qué dato lo debilitaría?, ¿dónde está la trampa? La buena noticia es que evaluar argumentos es una habilidad que se entrena, como un tiro libre: con técnica y práctica, cada vez aciertas más. Además, te servirá mucho más allá del examen: en redes, en debates y en cualquier decisión importante."},{"tipo":"concepto","titulo":"Tesis, argumentos, contraargumentos y refutación","contenido":"La **tesis** es la postura que el autor defiende (responde a «¿qué quiere que yo crea?»). Los **argumentos** son las razones que la sostienen (responden a «¿por qué debería creerlo?»). Un **contraargumento** es una objeción a la tesis, y la **refutación** es la respuesta del autor a esa objeción."},{"tipo":"lista","titulo":"Tipos de argumento frecuentes","items":["**De autoridad**: cita a un experto o a una institución reconocida en el tema.","**Con datos**: usa cifras, encuestas o estudios.","**Por ejemplificación**: se apoya en casos concretos.","**Por analogía**: compara con una situación parecida.","**De causa y efecto**: muestra que algo produce una consecuencia.","**Contraejemplo**: presenta un caso que demuestra que una afirmación general es falsa."]},{"tipo":"lista","titulo":"Falacias frecuentes: argumentos con trampa","items":["**Ad hominem**: atacar a la persona en lugar de sus razones.","**Ad populum**: creer que algo es verdadero porque mucha gente lo cree.","**Generalización apresurada**: concluir algo sobre todos a partir de pocos casos.","**Falsa disyuntiva**: presentar solo dos opciones cuando hay más.","**Falsa causa**: suponer que, como algo ocurrió después de otra cosa, fue causado por ella.","**Pendiente resbaladiza**: afirmar sin pruebas que un paso llevará a una cadena de desastres.","**Autoridad irrelevante**: citar a alguien famoso que no es experto en el tema."]},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: ¿qué dato debilita el argumento?","enunciado":"Micro-texto: «El colegio debería abrir la biblioteca hasta las 6:00 p. m. Muchos estudiantes no tienen internet ni computador en casa, y hoy la biblioteca cierra a las 2:00 p. m., justo cuando termina la jornada». ¿Cuál dato, de ser cierto, debilitaría el argumento? (1) El 70 % de los estudiantes no tiene computador en casa. (2) Una encuesta mostró que casi todos los estudiantes sin computador trabajan o cuidan a sus hermanos en la tarde y no podrían quedarse. (3) La biblioteca acaba de recibir veinte computadores nuevos.","pasos":["Paso 1: identifica la tesis: abrir la biblioteca hasta las 6:00 p. m.","Paso 2: identifica el argumento: los estudiantes sin internet ni computador necesitan usarla después de clase.","Paso 3: reconstruye el supuesto oculto: esos estudiantes podrían quedarse en la tarde si la biblioteca abriera.","Paso 4: evalúa cada dato. El (1) muestra que la necesidad es real y el (3) que la biblioteca tiene recursos: ambos apoyan la tesis.","Paso 5: el (2) ataca el supuesto: si quienes más la necesitan no pueden quedarse, ampliar el horario no resolvería su problema."],"respuesta":"El dato (2) debilita el argumento, porque muestra que los estudiantes que más necesitan la biblioteca no podrían aprovechar el nuevo horario."},{"tipo":"tip","contenido":"Tip ICFES: en las preguntas de «refuerza o debilita», escribe primero el argumento en una línea: «X, porque Y». Luego busca la opción que ataque ese **porque** (la razón o el supuesto). Cuidado con las opciones que repiten lo que el texto ya dice (refuerzan) o que hablan de otro tema (no afectan)."},{"tipo":"concepto","titulo":"Falacia no es lo mismo que opinión contraria","contenido":"Un argumento no es falaz porque no estés de acuerdo con él. Es falaz cuando su **estructura** es defectuosa: las razones no apoyan la conclusión, aunque parezca que sí. Por eso el ICFES te pide identificar el error de razonamiento, no juzgar si la postura te gusta."},{"tipo":"ejercicio","enunciado":"«No hay que hacerle caso a la propuesta de Andrés de crear una huerta escolar: él siempre saca malas notas en biología». ¿Qué error de razonamiento se comete?","opciones":["Ad populum, porque se apela a lo que piensa la mayoría.","Ad hominem, porque se descalifica la propuesta atacando a quien la hace.","Falsa disyuntiva, porque se presentan solo dos opciones.","Generalización apresurada, porque se concluye algo sobre todos a partir de un solo caso."],"correcta":1,"explicacion":"Se rechaza la propuesta por una característica de Andrés (sus notas), no por las razones a favor o en contra de la huerta. Es una falacia ad hominem: el valor de una propuesta no depende de las calificaciones de quien la presenta."},{"tipo":"ejercicio","enunciado":"Un texto defiende que la jornada única mejora el rendimiento académico y, como prueba, cita un estudio según el cual los colegios que la adoptaron subieron su puntaje en las pruebas. ¿Cuál dato, de ser cierto, debilitaría más ese argumento?","opciones":["A los estudiantes de esos colegios les gusta almorzar en el colegio.","Muchos países tienen jornadas escolares largas.","El estudio fue publicado en una revista reconocida.","Esos colegios también renovaron a sus profesores y sus laboratorios el mismo año."],"correcta":3,"explicacion":"Si al mismo tiempo cambiaron los profesores y los laboratorios, la mejora podría deberse a esos factores y no a la jornada única: el vínculo de causa y efecto queda en duda. El gusto por el almuerzo no se relaciona con el rendimiento, lo que ocurre en otros países no aporta evidencia sobre el efecto y la revista reconocida más bien refuerza la confiabilidad del estudio."}]'::jsonb,
  13, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;

-- ---------------------------------------------------------------- lecciones/matematicas.json
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'algebra'), 'MAT-ALG-L1', 'Álgebra en la vida real: ecuaciones, porcentajes y sistemas', 'Aprenderás a convertir situaciones cotidianas en ecuaciones, a calcular porcentajes sin caer en trampas y a resolver sistemas de dos ecuaciones con dos incógnitas.', '[{"tipo":"texto","contenido":"En el ICFES casi nunca te piden resolver una ecuación suelta: te cuentan una historia (un ahorro, una venta de boletas, un precio que sube) y tú debes convertirla en matemáticas. Esa **traducción** es la mitad del trabajo; la otra mitad es operar con orden. ¡Vamos a entrenar ambas!"},{"tipo":"concepto","titulo":"Del lenguaje cotidiano al lenguaje algebraico","contenido":"Una **variable** (x, s, g…) representa una cantidad desconocida. Algunas pistas para traducir: «cada» o «por» indican multiplicación (15.000 por semana → 15.000·s); «más» o «aumenta» indican suma; «el doble» es 2x; «la mitad» es x/2; «es», «da» o «resulta» equivalen al signo =."},{"tipo":"formula","contenido":"a·x + b = c  →  x = (c − b) ÷ a","nota":"Sirve cuando hay un valor fijo inicial (b) y una cantidad (a) que se repite x veces hasta llegar a un total (c)."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: ahorrando para un balón","enunciado":"Julián tiene $35.000 ahorrados y cada semana guarda $15.000 más. ¿En cuántas semanas completará los $170.000 que cuesta un balón de fútbol profesional?","pasos":["Define la variable: s = número de semanas.","Plantea la ecuación: 35.000 + 15.000·s = 170.000.","Resta 35.000 a ambos lados: 15.000·s = 135.000.","Divide entre 15.000: s = 135.000 ÷ 15.000 = 9.","Comprueba: 35.000 + 15.000 × 9 = 35.000 + 135.000 = 170.000 ✓."],"respuesta":"9 semanas"},{"tipo":"concepto","titulo":"Porcentajes: siempre respecto a algo","contenido":"El p % de una cantidad es (p ÷ 100) × cantidad. Aumentar un p % equivale a multiplicar por (1 + p/100), y descontar un p % equivale a multiplicar por (1 − p/100). La **variación porcentual** se calcula respecto al valor inicial: (final − inicial) ÷ inicial × 100 %. Y ojo: los porcentajes sucesivos se **multiplican**, no se suman."},{"tipo":"texto","contenido":"**Sistemas 2×2.** Cuando hay dos incógnitas necesitas dos ecuaciones. Con el **método de sustitución** despejas una variable en una ecuación y la reemplazas en la otra; con el de **reducción** sumas o restas las ecuaciones para eliminar una variable. Por ejemplo, si x + y = 10 y x − y = 4, al sumarlas queda 2x = 14, así que x = 7 y y = 3."},{"tipo":"lista","titulo":"Errores frecuentes","items":["Calcular la variación porcentual dividiendo entre el valor final en lugar del inicial.","Sumar descuentos sucesivos: un 20 % y luego un 10 % no equivalen a un 30 %.","Olvidar el valor fijo inicial al plantear la ecuación (por ejemplo, lo que ya estaba ahorrado).","Resolver bien un sistema, pero responder la otra incógnita."]},{"tipo":"tip","contenido":"Tip ICFES: antes de resolver, subraya qué te preguntan exactamente. En problemas de ecuaciones y sistemas, a veces es más rápido **probar las opciones** en el enunciado: la correcta debe cumplir todas las condiciones al mismo tiempo."},{"tipo":"ejercicio","enunciado":"Un celular cuesta $600.000. En una promoción tiene un descuento del 20 % y, sobre el precio ya rebajado, un descuento adicional del 10 % por pagar de contado. ¿Cuánto se paga finalmente?","opciones":["$420.000","$432.000","$480.000","$540.000"],"correcta":1,"explicacion":"Primero: 600.000 × 0,80 = 480.000. Luego: 480.000 × 0,90 = 432.000. Sumar los descuentos (30 %) daría $420.000, pero el segundo descuento se aplica sobre $480.000, no sobre $600.000."},{"tipo":"ejercicio","enunciado":"En una cafetería de Cali, 2 empanadas y 1 jugo cuestan $7.000, mientras que 1 empanada y 1 jugo cuestan $4.500. ¿Cuánto cuesta una empanada?","opciones":["$2.000","$2.250","$2.500","$3.500"],"correcta":2,"explicacion":"Si a la primera compra le restas la segunda: (2e + j) − (e + j) = 7.000 − 4.500, así que e = 2.500. Entonces el jugo cuesta 4.500 − 2.500 = 2.000. Comprobación: 2 × 2.500 + 2.000 = 7.000 ✓."}]'::jsonb,
  10, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'geometria'), 'MAT-GEO-L1', 'Geometría para medir el mundo: Pitágoras, áreas y volúmenes', 'Repasarás perímetros, áreas y volúmenes, aplicarás el teorema de Pitágoras y descubrirás qué pasa con el área y el volumen cuando una figura cambia de tamaño.', '[{"tipo":"texto","contenido":"La geometría del ICFES es muy práctica: cercar un lote, embaldosar un piso, pintar una pared o llenar un tanque. La clave está en identificar qué te piden: ¿el **borde** (perímetro), la **superficie** (área) o el **espacio interior** (volumen)? Si aciertas en eso, ya tienes medio problema resuelto."},{"tipo":"concepto","titulo":"Perímetro, área y volumen","contenido":"El **perímetro** es la longitud del contorno y se mide en unidades lineales (m, cm). El **área** mide la superficie y se expresa en unidades cuadradas (m², cm²). El **volumen** mide el espacio que ocupa un cuerpo y se expresa en unidades cúbicas (m³, cm³). Dato útil: 1 m³ equivale a 1.000 litros."},{"tipo":"formula","contenido":"Rectángulo: A = b·h   |   Triángulo: A = b·h ÷ 2   |   Trapecio: A = (B + b)·h ÷ 2   |   Círculo: A = π·r² y L = 2·π·r   |   Prisma y cilindro: V = (área de la base)·h","nota":"Las figuras compuestas se resuelven dividiéndolas en partes conocidas."},{"tipo":"concepto","titulo":"Teorema de Pitágoras","contenido":"En todo **triángulo rectángulo**, el cuadrado de la hipotenusa (el lado opuesto al ángulo recto, que es el más largo) es igual a la suma de los cuadrados de los catetos: c² = a² + b². Ternas que conviene recordar: 3-4-5, 5-12-13, 8-15-17 y sus múltiplos (6-8-10, 9-12-15…)."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: la escalera de los bomberos","enunciado":"Un bombero de Manizales apoya una escalera de 6,5 m contra un muro. El pie de la escalera queda a 2,5 m de la base del muro. ¿A qué altura toca la escalera el muro?","pasos":["El muro y el suelo forman un ángulo recto, así que la escalera es la hipotenusa: c = 6,5 m.","Un cateto es la distancia al muro, a = 2,5 m; la altura h es el otro cateto.","Aplica Pitágoras: 6,5² = 2,5² + h², es decir, 42,25 = 6,25 + h².","Despeja: h² = 42,25 − 6,25 = 36, así que h = √36 = 6 m.","Comprueba: 2,5² + 6² = 6,25 + 36 = 42,25 = 6,5² ✓."],"respuesta":"La escalera toca el muro a 6 m de altura."},{"tipo":"concepto","titulo":"Cambio de escala","contenido":"Si todas las longitudes de una figura se multiplican por un factor k, el perímetro se multiplica por k, el área por k² y el volumen por k³. Por ejemplo, al duplicar las medidas de una caja (k = 2), el área de sus caras se multiplica por 4 y su volumen por 8."},{"tipo":"lista","titulo":"Errores frecuentes","items":["Confundir perímetro con área, o escribir un área en metros en lugar de metros cuadrados.","Aplicar Pitágoras en un triángulo que no es rectángulo.","Olvidar sacar la raíz cuadrada al final: si c² = 289, entonces c = 17, no 289.","Creer que si las medidas se duplican, el área o el volumen también se duplican."]},{"tipo":"tip","contenido":"Tip ICFES: marca en la figura todos los datos, incluidos los que se deducen (por ejemplo, la diferencia entre las dos bases de un trapecio). Si aparece un triángulo rectángulo con dos lados conocidos, piensa de inmediato en Pitágoras y revisa si se trata de una terna conocida: te ahorrará cálculos."},{"tipo":"ejercicio","enunciado":"Una rampa de un parque de patinaje de Medellín sube 0,9 m y su base horizontal mide 1,2 m. ¿Cuánto mide la superficie inclinada de la rampa?","opciones":["0,3 m","1,5 m","2,1 m","2,25 m"],"correcta":1,"explicacion":"La superficie inclinada es la hipotenusa: c² = 0,9² + 1,2² = 0,81 + 1,44 = 2,25, así que c = √2,25 = 1,5 m. Sumar los catetos da 2,1 m y olvidar la raíz cuadrada da 2,25."},{"tipo":"ejercicio","enunciado":"Una fábrica de Itagüí duplica el largo, el ancho y el alto de una caja con forma de prisma rectangular. ¿Cuántas veces aumenta la capacidad (el volumen) de la caja?","opciones":["2 veces","4 veces","6 veces","8 veces"],"correcta":3,"explicacion":"V = largo × ancho × alto. Si cada medida se multiplica por 2, el volumen se multiplica por 2 × 2 × 2 = 2³ = 8. El 4 corresponde a lo que ocurre con el área de cada cara (2²)."}]'::jsonb,
  10, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'estadistica'), 'MAT-EST-L1', 'Estadística: haz que los datos hablen', 'Aprenderás a calcular e interpretar la media, la mediana y la moda, a leer gráficas con cuidado y a reconocer cuándo una muestra representa bien a una población.', '[{"tipo":"texto","contenido":"Cada vez que oyes «el promedio de los colombianos…» o ves los resultados de una encuesta, hay estadística detrás. En el ICFES te pedirán leer tablas y gráficas, calcular medidas y, sobre todo, **decidir si una conclusión está bien sustentada**. ¡Aprende a no dejarte engañar por los números!"},{"tipo":"concepto","titulo":"Medidas de tendencia central","contenido":"La **media** (promedio) es la suma de los datos dividida entre la cantidad de datos. La **mediana** es el dato central cuando los datos están ordenados (si hay dos datos centrales, se promedian). La **moda** es el dato que más se repite. El **rango** (dato mayor − dato menor) no es de tendencia central: mide qué tan dispersos están los datos."},{"tipo":"formula","contenido":"Media = (x₁ + x₂ + … + xₙ) ÷ n","nota":"Cada dato cuenta, aunque esté repetido."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: ¿cuánto tardan en llegar?","enunciado":"Seis estudiantes de un colegio de Neiva anotaron cuántos minutos tardan en llegar al colegio: 10, 12, 8, 10, 15 y 65 (este último vive en una vereda lejana). Halla la media, la mediana y la moda. ¿Cuál describe mejor el tiempo típico?","pasos":["Media: (10 + 12 + 8 + 10 + 15 + 65) ÷ 6 = 120 ÷ 6 = 20 minutos.","Mediana: ordena los datos: 8, 10, 10, 12, 15, 65. Como son 6 datos, promedia los dos centrales: (10 + 12) ÷ 2 = 11 minutos.","Moda: el 10 es el único dato que se repite, así que la moda es 10 minutos.","El 65 es un dato atípico que «jala» la media hacia arriba: 5 de los 6 estudiantes tardan menos de 20 minutos. La mediana (11 minutos) describe mejor el caso típico."],"respuesta":"Media = 20 min, mediana = 11 min y moda = 10 min; la mediana es la más representativa."},{"tipo":"concepto","titulo":"Población, muestra y representatividad","contenido":"La **población** es todo el grupo que se quiere estudiar y la **muestra** es la parte que realmente se observa. Una muestra es **representativa** cuando se parece a la población; la mejor forma de lograrlo es elegirla al azar entre toda la población. Si solo se escoge un grupo particular (los amigos, un solo curso, los de un club), la muestra tiene **sesgo** y sus conclusiones no se pueden generalizar."},{"tipo":"lista","titulo":"Cómo leer una gráfica sin errores","items":["Lee el título y qué representa cada eje.","Revisa la escala: ¿de cuánto en cuánto aumentan las marcas?","Fíjate si el eje vertical empieza en cero; si no, las diferencias se ven exageradas.","Distingue entre cantidades (frecuencias) y porcentajes."]},{"tipo":"tip","contenido":"Tip ICFES: si ves un dato muy alejado de los demás, desconfía de la media; la mediana suele representar mejor al grupo. Y cuando te pregunten si una conclusión es válida, revisa primero **a quiénes** se encuestó y **cómo** se escogieron, antes de revisar las cuentas."},{"tipo":"ejercicio","enunciado":"Las notas de Laura en Química durante el periodo fueron 3,0; 4,0; 3,5; 4,5 y 4,0. ¿Cuál es la mediana de sus notas?","opciones":["3,5","3,8","4,0","4,5"],"correcta":2,"explicacion":"Ordenadas: 3,0 – 3,5 – 4,0 – 4,0 – 4,5. El dato central (el tercero) es 4,0. El 3,8 es la media, y el 3,5 aparece si se toma el dato del centro sin ordenar la lista."},{"tipo":"ejercicio","enunciado":"Se quiere estimar cuántas horas al día usan internet los habitantes de Montería. ¿Cuál de estas muestras es la más representativa?","opciones":["Los clientes de un café internet del centro, un sábado por la tarde.","Los estudiantes de un solo colegio de la ciudad.","300 personas elegidas al azar en distintos barrios, de diferentes edades y estratos.","Los seguidores de una cuenta de videojuegos en redes sociales."],"correcta":2,"explicacion":"La muestra elegida al azar entre distintos barrios, edades y estratos es la que más se parece a toda la población. Las demás son grupos con características particulares, es decir, tienen sesgo de selección."}]'::jsonb,
  9, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'probabilidad'), 'MAT-PRO-L1', 'Probabilidad: ¿qué tan posible es?', 'Calcularás probabilidades contando casos favorables y posibles, trabajarás con eventos independientes y usarás tablas de doble entrada para resolver problemas de probabilidad condicional.', '[{"tipo":"texto","contenido":"La probabilidad mide qué tan posible es que algo ocurra, con un número entre 0 (imposible) y 1 (seguro). Aparece en rifas, pronósticos del clima, juegos y encuestas. En el ICFES casi todos los problemas de probabilidad se resuelven **contando bien**: qué casos sirven y cuántos casos hay en total."},{"tipo":"concepto","titulo":"Probabilidad clásica","contenido":"Si todos los resultados de un experimento son igualmente probables, la probabilidad de un evento A es P(A) = casos favorables ÷ casos posibles. Se puede expresar como fracción, decimal o porcentaje: 1/4 = 0,25 = 25 %. La probabilidad de que A **no** ocurra es 1 − P(A)."},{"tipo":"formula","contenido":"P(A) = casos favorables ÷ casos posibles   |   P(no A) = 1 − P(A)   |   P(A y B) = P(A) × P(B), si A y B son independientes","nota":"Dos eventos son independientes cuando el resultado de uno no afecta al otro, como dos lanzamientos de una moneda."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: la rifa del curso","enunciado":"Para la rifa del curso 11-B de un colegio de Cúcuta se venden 200 boletas numeradas del 000 al 199. Sara compró todas las boletas que terminan en 7. ¿Qué probabilidad tiene de ganar?","pasos":["Casos posibles: las 200 boletas.","Casos favorables: 007, 017, 027, …, 197. Hay una por cada decena (de 00 a 19), así que son 20 boletas.","P = 20 ÷ 200 = 1/10 = 0,1."],"respuesta":"1/10, es decir, 10 %"},{"tipo":"concepto","titulo":"Tablas de doble entrada y probabilidad condicional","contenido":"Una tabla de doble entrada clasifica a un grupo según dos características. Cuando la pregunta dice «si se sabe que…», «entre los que…» o «si se elige un estudiante de…», los casos posibles ya no son todos: se reducen a la fila o a la columna de esa condición. Eso es una **probabilidad condicional**."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: ¿quién practica deporte?","enunciado":"En el curso 10-A de un colegio de Pasto hay 40 estudiantes. De los 20 hombres, 12 practican algún deporte; de las 20 mujeres, 10 lo practican. a) Si se elige al azar una mujer del curso, ¿cuál es la probabilidad de que practique deporte? b) Si se elige al azar a alguien que practica deporte, ¿cuál es la probabilidad de que sea mujer?","pasos":["Organiza los datos: hombres, 12 sí y 8 no; mujeres, 10 sí y 10 no. En total, 22 estudiantes practican deporte.","a) La condición es «ser mujer»: los casos posibles son las 20 mujeres y los favorables, las 10 que practican deporte. P = 10/20 = 1/2.","b) Ahora la condición es «practicar deporte»: los casos posibles son los 22 deportistas y los favorables, las 10 mujeres. P = 10/22 = 5/11 ≈ 0,45.","Las dos respuestas usan el 10, pero lo dividen entre totales distintos: el orden de la condición importa."],"respuesta":"a) 1/2   b) 5/11"},{"tipo":"lista","titulo":"Errores frecuentes","items":["Suponer que todos los resultados son igual de probables sin serlo («hay 3 opciones, entonces es 1/3»).","Dividir entre el total general cuando la pregunta tiene una condición.","Confundir «la probabilidad de A si ocurre B» con «la probabilidad de B si ocurre A».","Sumar las probabilidades de eventos independientes cuando se deben multiplicar."]},{"tipo":"tip","contenido":"Tip ICFES: subraya la condición de la pregunta («si es de grado 11…», «entre los que…»). Esa frase te dice cuál es el nuevo total de casos posibles. Además, recuerda que una probabilidad nunca es negativa ni mayor que 1: úsalo para descartar opciones rápidamente."},{"tipo":"ejercicio","enunciado":"Se lanza un dado común de seis caras. ¿Cuál es la probabilidad de obtener un número mayor que 4?","opciones":["1/6","1/3","1/2","2/3"],"correcta":1,"explicacion":"Los números mayores que 4 son 5 y 6: 2 casos favorables de 6 posibles, así que P = 2/6 = 1/3. Si se incluye el 4 se obtiene 1/2, pero «mayor que 4» no incluye al 4."},{"tipo":"ejercicio","enunciado":"Se lanza una moneda dos veces. ¿Cuál es la probabilidad de obtener cara en los dos lanzamientos?","opciones":["1/4","1/3","1/2","1"],"correcta":0,"explicacion":"Los lanzamientos son independientes: P = 1/2 × 1/2 = 1/4. También puedes listar los resultados posibles: CC, CS, SC y SS; solo 1 de los 4 es favorable. Sumar (1/2 + 1/2 = 1) daría un evento seguro, lo cual no tiene sentido."}]'::jsonb,
  11, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'calculo-basico'), 'MAT-CAL-L1', '¿Qué tan rápido cambia? Tasa de cambio y lectura de gráficas', 'Aprenderás a calcular e interpretar la tasa de cambio, a identificar en una gráfica dónde una función crece, decrece o alcanza su máximo, y a distinguir la variación lineal de la exponencial.', '[{"tipo":"texto","contenido":"En el ICFES, el cálculo no aparece con derivadas ni fórmulas complicadas: aparece como la pregunta **¿cómo cambia una cantidad cuando cambia otra?** ¿Qué tan rápido se vacía un tanque? ¿Cuándo alcanzó su altura máxima un balón? ¿Qué crece más rápido, un ahorro fijo o uno con intereses? Todo eso se responde leyendo gráficas y tablas con atención."},{"tipo":"concepto","titulo":"Tasa de cambio y pendiente","contenido":"La **tasa de cambio promedio** entre dos puntos indica cuánto cambia y por cada unidad que cambia x. En una gráfica, es la **pendiente** (inclinación) del segmento que une los dos puntos. Si es positiva, la cantidad crece; si es negativa, decrece; si es cero, se mantiene constante. Sus unidades combinan las de los ejes: m/min, litros/hora, pesos/kg."},{"tipo":"formula","contenido":"Tasa de cambio = Δy ÷ Δx = (y₂ − y₁) ÷ (x₂ − x₁)","nota":"En una función lineal y = m·x + b, la tasa de cambio es siempre la misma: la pendiente m."},{"tipo":"ejemplo","titulo":"Ejemplo resuelto: el tanque de la finca","enunciado":"El tanque de agua de una finca en San Gil (Santander) tenía 1.200 litros a las 6:00 a. m. y 750 litros a las 9:00 a. m. ¿Cuál fue la tasa de cambio promedio del volumen de agua y qué significa?","pasos":["Cambio en el volumen: Δy = 750 − 1.200 = −450 litros.","Cambio en el tiempo: Δx = 9 − 6 = 3 horas.","Tasa de cambio: −450 ÷ 3 = −150 litros por hora.","El signo negativo indica que el volumen disminuye: en promedio, el tanque perdió 150 litros cada hora."],"respuesta":"−150 L/h: el tanque se vació, en promedio, 150 litros por hora."},{"tipo":"concepto","titulo":"Crecimiento, decrecimiento, máximos y mínimos","contenido":"Una función **crece** en un intervalo si al avanzar hacia la derecha la gráfica sube, y **decrece** si baja. El **máximo** es el punto más alto de la gráfica y el **mínimo**, el más bajo; se informan con su valor (en el eje y) y el momento en que ocurren (en el eje x). Cuanto más inclinado es un tramo, más rápido es el cambio."},{"tipo":"concepto","titulo":"Variación lineal vs. exponencial","contenido":"En la variación **lineal** se **suma** la misma cantidad en cada periodo: la tasa de cambio es constante y la gráfica es una recta. En la **exponencial** se **multiplica** por el mismo factor en cada periodo, así que los aumentos son cada vez mayores y la gráfica es una curva que se empina. Por ejemplo, crecer un 10 % al año significa multiplicar por 1,1 cada año: y = y₀ · 1,1ⁿ. A largo plazo, un crecimiento exponencial siempre supera a uno lineal."},{"tipo":"lista","titulo":"¿Lineal o exponencial? Revisa la tabla","items":["Calcula las diferencias entre valores consecutivos: si son iguales, la variación es lineal.","Calcula los cocientes entre valores consecutivos: si son iguales, la variación es exponencial.","En la gráfica, la lineal es una recta; la exponencial creciente es una curva cada vez más empinada."]},{"tipo":"tip","contenido":"Tip ICFES: cuando te pregunten en qué intervalo algo cambió más rápido, no compares cuánto subió o bajó en total: compara la **inclinación**, es decir, el cambio dividido entre el tiempo. Un tramo corto y empinado puede ser más rápido que uno largo."},{"tipo":"ejercicio","enunciado":"Un bus sale de Bogotá hacia Tunja. A las 7:00 a. m. ha recorrido 20 km y a las 9:30 a. m. ha recorrido 145 km. ¿Cuál fue su rapidez promedio en ese intervalo?","opciones":["50 km/h","58 km/h","62,5 km/h","125 km/h"],"correcta":0,"explicacion":"Δd = 145 − 20 = 125 km y Δt = 9:30 − 7:00 = 2,5 h. Rapidez promedio = 125 ÷ 2,5 = 50 km/h. El 58 sale de dividir 145 ÷ 2,5 sin restar los 20 km iniciales, y el 62,5, de usar 2 horas en lugar de 2,5."},{"tipo":"ejercicio","enunciado":"La tabla muestra el número de bacterias en un cultivo de laboratorio: 0 h → 300; 1 h → 600; 2 h → 1.200; 3 h → 2.400. Si el comportamiento se mantiene, ¿qué tipo de variación es y cuántas bacterias habrá a las 5 horas?","opciones":["Lineal; 3.600","Lineal; 4.800","Exponencial; 4.800","Exponencial; 9.600"],"correcta":3,"explicacion":"Los cocientes son iguales: 600 ÷ 300 = 1.200 ÷ 600 = 2.400 ÷ 1.200 = 2, así que la población se duplica cada hora (variación exponencial). A las 4 h habrá 4.800 y a las 5 h, 9.600. El 4.800 corresponde a las 4 horas, no a las 5."}]'::jsonb,
  12, 30, 5, 1)
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, titulo = EXCLUDED.titulo, resumen = EXCLUDED.resumen,
  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;

